import * as THREE from '../vendor/three.module.js';
import { add, group, M, C, GLOW_TEX } from './materials.js';
import { humanWorker, humanMelee, humanRanged, humanHeavy, humanCaster } from './models_human.js';
import { orcWorker, orcMelee, orcRanged, orcHeavy, orcCaster } from './models_orc.js';
import { undeadWorker, undeadMelee, undeadRanged, undeadHeavy, undeadCaster } from './models_undead.js';
import { humanHall, humanFarm, humanBarracks, humanTower, humanSpecial } from './models_human_buildings.js';
import { orcHall, orcFarm, orcBarracks, orcTower, orcSpecial } from './models_orc_buildings.js';
import { undeadHall, undeadFarm, undeadBarracks, undeadTower, undeadSpecial } from './models_undead_buildings.js';

const UNIT_FACTORY = {
  human: { worker: humanWorker, melee: humanMelee, ranged: humanRanged, heavy: humanHeavy, caster: humanCaster },
  orc: { worker: orcWorker, melee: orcMelee, ranged: orcRanged, heavy: orcHeavy, caster: orcCaster },
  undead: { worker: undeadWorker, melee: undeadMelee, ranged: undeadRanged, heavy: undeadHeavy, caster: undeadCaster },
};

const BUILDING_FACTORY = {
  human: { hall: humanHall, farm: humanFarm, barracks: humanBarracks, tower: humanTower, special: humanSpecial },
  orc: { hall: orcHall, farm: orcFarm, barracks: orcBarracks, tower: orcTower, special: orcSpecial },
  undead: { hall: undeadHall, farm: undeadFarm, barracks: undeadBarracks, tower: undeadTower, special: undeadSpecial },
};

export function createUnitModel(race, role, teamColor = 0x4c8dff) {
  const fn = UNIT_FACTORY[race]?.[role];
  if (!fn) throw new Error(`Unknown unit model ${race}/${role}`);
  return fn(teamColor);
}

export function createBuildingModel(race, role, teamColor = 0x4c8dff) {
  const fn = BUILDING_FACTORY[race]?.[role];
  if (!fn) throw new Error(`Unknown building model ${race}/${role}`);
  return fn(teamColor);
}

// ---------------------------------------------------------------------------
// Map props
// ---------------------------------------------------------------------------
const treeTrunk = M(0x5b3c24);
const leafMats = [
  M(0x3f7138), M(0x4f8340), M(0x356229), M(0x6a8a3e),
  M(0x9a6a2f), M(0xb07a32), M(0x35603a), M(0x2c5232),
];
const rockMats = [M(0x7a786d), M(0x8c897b), M(0x62615a), M(0x9a9687)];
const goldMats = [M(0xe3b83e, { metalness: 0.55, roughness: 0.35, emissive: 0x6b4300, emissiveIntensity: 0.35 })];

export function createTree(variant = 0, scale = 1) {
  const g = new THREE.Group();
  const s = scale;
  g.scale.setScalar(s);
  add(g, 'cyl6', treeTrunk, 0, 1.1, 0, 0.26, 2.2, 0.26);
  add(g, 'cyl6', M(0x6b482a), 0, 0.35, 0, 0.4, 0.5, 0.4);
  const v = variant % 3;
  if (v === 0) {
    // broadleaf
    const mat = leafMats[variant % 4];
    add(g, 'sphere', mat, 0, 2.5, 0, 2.4, 1.9, 2.4);
    add(g, 'sphere', mat, -0.65, 3.2, 0.2, 1.7, 1.5, 1.7);
    add(g, 'sphere', leafMats[(variant + 1) % 4], 0.7, 3.25, -0.1, 1.6, 1.4, 1.6);
    add(g, 'sphere', leafMats[(variant + 2) % 4], 0.15, 3.8, 0.1, 1.3, 1.1, 1.3);
  } else if (v === 1) {
    // autumn
    const mat = leafMats[4 + (variant % 2)];
    add(g, 'sphere', mat, 0, 2.6, 0, 2.3, 1.8, 2.3);
    add(g, 'sphere', leafMats[4], -0.55, 3.2, 0, 1.5, 1.5, 1.5);
    add(g, 'sphere', leafMats[5], 0.6, 3.15, 0.1, 1.45, 1.4, 1.45);
    add(g, 'sphere', leafMats[4], 0.05, 3.7, 0, 1.15, 1.1, 1.15);
  } else {
    // pine
    const mat = leafMats[6];
    add(g, 'cone', mat, 0, 2.2, 0, 2.2, 1.9, 2.2);
    add(g, 'cone', mat, 0, 3.1, 0, 1.8, 1.8, 1.8);
    add(g, 'cone', mat, 0, 4.0, 0, 1.3, 1.6, 1.3);
    add(g, 'cone', leafMats[7], 0, 4.8, 0, 0.8, 1.2, 0.8);
  }
  g.userData.height = 5 * s;
  return g;
}

export function createRock(scale = 1, variant = 0) {
  const g = new THREE.Group();
  g.scale.setScalar(scale);
  add(g, 'dodeca', rockMats[variant % rockMats.length], 0, 0.45, 0, 1.3, 0.85, 1.1, 0.2, variant, 0.1);
  add(g, 'dodeca', rockMats[(variant + 1) % rockMats.length], 0.55, 0.25, 0.25, 0.7, 0.5, 0.7, 0.5, 1.2, 0);
  add(g, 'dodeca', rockMats[(variant + 2) % rockMats.length], -0.45, 0.2, 0.3, 0.5, 0.4, 0.45, 1.2, 0.3, 0.4);
  return g;
}

export function createGoldMine() {
  const g = new THREE.Group();
  const rock = M(0x706b5c);
  const rockD = M(0x524e44);
  add(g, 'dodeca', rock, -0.3, 0.55, 0, 2.0, 1.5, 1.8, 0.1, 0.3, 0);
  add(g, 'dodeca', rockD, 0.55, 0.5, -0.15, 1.5, 1.2, 1.5, 0.2, 0.8, 0.2);
  add(g, 'dodeca', rock, 0.1, 0.85, 0.35, 1.45, 1.15, 1.3, 0.3, 0.1, 0.4);
  add(g, 'dodeca', rockD, -0.55, 0.3, 0.45, 0.9, 0.7, 0.8, 0.6, 0.2, 0);
  // entrance
  add(g, 'box', M(0x151411), 0, 0.5, 0.62, 0.75, 1.0, 0.3);
  add(g, 'cyl6', M(C.woodDark), -0.55, 0.65, 0.78, 0.09, 1.3, 0.09);
  add(g, 'cyl6', M(C.woodDark), 0.55, 0.65, 0.78, 0.09, 1.3, 0.09);
  add(g, 'box', M(C.woodDark), 0, 1.32, 0.78, 1.3, 0.16, 0.16);
  add(g, 'cone', goldMats[0], -0.55, 1.5, 0.78, 0.14, 0.28, 0.14);
  // nuggets
  for (let i = 0; i < 12; i++) {
    const a = i * 2.4;
    const r = 0.4 + (i % 4) * 0.22;
    add(g, 'dodeca', goldMats[0], Math.cos(a) * r, 0.2 + (i % 5) * 0.18, Math.sin(a) * r * 0.7 + 0.3, 0.16 + (i % 3) * 0.04, 0.14, 0.16);
  }
  // cart
  add(g, 'box', M(C.woodDark), 1.05, 0.35, 0.4, 0.7, 0.35, 0.5);
  add(g, 'cyl', M(C.iron), 0.85, 0.15, 0.18, 0.26, 0.08, 0.26, Math.PI / 2, 0, 0);
  add(g, 'cyl', M(C.iron), 1.25, 0.15, 0.18, 0.26, 0.08, 0.26, Math.PI / 2, 0, 0);
  add(g, 'dodeca', goldMats[0], 1.05, 0.55, 0.4, 0.5, 0.3, 0.4);
  g.userData.height = 2.2;
  return g;
}

export function createFountain() {
  const g = new THREE.Group();
  const stone = M(C.stoneLight);
  const stoneD = M(C.stoneDark);
  add(g, 'cyl', stoneD, 0, 0.18, 0, 6.2, 0.35, 6.2);
  add(g, 'cyl', stone, 0, 0.42, 0, 5.4, 0.2, 5.4);
  const water = add(g, 'cyl', M(0x40c9d9, { emissive: 0x1a94b5, emissiveIntensity: 0.7, transparent: true, opacity: 0.82 }), 0, 0.55, 0, 4.7, 0.08, 4.7);
  water.userData.water = true;
  // four pillars and statue base
  for (let i = 0; i < 4; i++) {
    const a = i * Math.PI / 2 + Math.PI / 4;
    add(g, 'cyl', stoneD, Math.cos(a) * 4.0, 0.9, Math.sin(a) * 4.0, 0.45, 1.5, 0.45);
    add(g, 'sphere', stone, Math.cos(a) * 4.0, 1.7, Math.sin(a) * 4.0, 0.6, 0.5, 0.6);
    add(g, 'cone', stone, Math.cos(a) * 4.0, 1.95, Math.sin(a) * 4.0, 0.35, 0.45, 0.35);
  }
  add(g, 'cyl', stoneD, 0, 0.9, 0, 1.7, 1.4, 1.7);
  add(g, 'cyl', stone, 0, 1.65, 0, 1.2, 0.2, 1.2);
  // central crystal
  const crystal = add(g, 'dodeca', M(0x7ff5e5, { emissive: 0x2ed6c9, emissiveIntensity: 1.8, transparent: true, opacity: 0.9 }), 0, 2.3, 0, 0.8, 1.5, 0.8);
  crystal.userData.spin = true;
  add(g, 'torus', M(0x9ffcf0, { emissive: 0x2ed6c9, emissiveIntensity: 1.2, transparent: true, opacity: 0.7 }), 0, 2.3, 0, 1.1, 0.25, 1.1, Math.PI / 2, 0, 0);
  // glow
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: GLOW_TEX, color: 0x6ff5e0, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false }));
  sprite.position.set(0, 2.3, 0);
  sprite.scale.set(7, 7, 1);
  g.add(sprite);
  const light = new THREE.PointLight(0x59e6dd, 28, 17, 2);
  light.position.set(0, 2.6, 0);
  g.add(light);
  g.userData.water = water;
  g.userData.crystal = crystal;
  g.userData.height = 3;
  return g;
}

export function createBush(scale = 1) {
  const g = new THREE.Group();
  g.scale.setScalar(scale);
  add(g, 'sphere', leafMats[2], -0.3, 0.3, 0, 0.8, 0.55, 0.7);
  add(g, 'sphere', leafMats[1], 0.25, 0.35, 0.1, 0.75, 0.55, 0.75);
  add(g, 'sphere', leafMats[3], 0, 0.4, -0.25, 0.6, 0.45, 0.6);
  return g;
}

export const MAP = {
  size: 150,
  playable: 62,
  playerBase: { x: -38, z: 34 },
  enemyBase: { x: 38, z: -34 },
  mines: [
    { x: -48, z: 23, amount: 9000, rich: false },
    { x: 48, z: -23, amount: 9000, rich: false },
    { x: 12, z: 8, amount: 14000, rich: true },
  ],
  fountain: { x: -8, z: 12, radius: 4.6 },
  pond: { x: -52, z: -18, radius: 9 },
  path: {
    from: { x: -38, z: 34 },
    to: { x: 38, z: -34 },
  },
};

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function distToSegment(px, pz, ax, az, bx, bz) {
  const abx = bx - ax;
  const abz = bz - az;
  const apx = px - ax;
  const apz = pz - az;
  const t = Math.max(0, Math.min(1, (apx * abx + apz * abz) / (abx * abx + abz * abz)));
  const dx = px - (ax + abx * t);
  const dz = pz - (az + abz * t);
  return Math.hypot(dx, dz);
}

export function generateLayout(seed = 20261031) {
  const rnd = mulberry32(seed);
  const trees = [];
  const rocks = [];
  const bushes = [];
  const flowers = [];
  const stones = [];

  const clusters = [
    { x: -49, z: 46, n: 10, r: 5.2 },
    { x: -28, z: 53, n: 8, r: 4.6 },
    { x: -56, z: 8, n: 8, r: 4.4 },
    { x: -58, z: -34, n: 7, r: 4.2 },
    { x: 49, z: -46, n: 10, r: 5.2 },
    { x: 28, z: -53, n: 8, r: 4.6 },
    { x: 56, z: -8, n: 8, r: 4.4 },
    { x: 58, z: 34, n: 7, r: 4.2 },
    { x: -18, z: -30, n: 6, r: 3.8 },
    { x: 8, z: 31, n: 6, r: 3.6 },
    { x: 22, z: 14, n: 5, r: 3.2 },
    { x: -30, z: -6, n: 5, r: 3.3 },
    { x: 30, z: 30, n: 6, r: 3.6 },
    { x: -8, z: -48, n: 7, r: 4.0 },
    { x: 40, z: 10, n: 5, r: 3.2 },
    { x: -10, z: 49, n: 5, r: 3.4 },
  ];

  const tooClose = (x, z, pad = 0) => {
    if (Math.hypot(x, z) > MAP.playable - 3) return true;
    for (const base of [MAP.playerBase, MAP.enemyBase]) {
      if (Math.hypot(x - base.x, z - base.z) < 14 + pad) return true;
    }
    for (const mine of MAP.mines) {
      if (Math.hypot(x - mine.x, z - mine.z) < 5.2 + pad) return true;
    }
    if (Math.hypot(x - MAP.fountain.x, z - MAP.fountain.z) < 6.5 + pad) return true;
    if (Math.hypot(x - MAP.pond.x, z - MAP.pond.z) < MAP.pond.radius + 2 + pad) return true;
    if (distToSegment(x, z, MAP.path.from.x, MAP.path.from.z, MAP.path.to.x, MAP.path.to.z) < 7.5 + pad) return true;
    return false;
  };

  for (const cluster of clusters) {
    for (let i = 0; i < cluster.n; i++) {
      const a = rnd() * Math.PI * 2;
      const r = Math.sqrt(rnd()) * cluster.r;
      let x = cluster.x + Math.cos(a) * r;
      let z = cluster.z + Math.sin(a) * r;
      let tries = 0;
      while (tooClose(x, z) && tries++ < 12) {
        x += (rnd() - 0.5) * 3;
        z += (rnd() - 0.5) * 3;
      }
      if (tooClose(x, z)) continue;
      let overlap = false;
      for (const t of trees) {
        if ((t.x - x) ** 2 + (t.z - z) ** 2 < 4.6) { overlap = true; break; }
      }
      if (overlap) continue;
      trees.push({
        x, z,
        variant: Math.floor(rnd() * 3),
        scale: 0.82 + rnd() * 0.42,
        rot: rnd() * Math.PI * 2,
      });
    }
  }

  // A few lone trees to break up the open ground.
  for (let i = 0; i < 18; i++) {
    const a = rnd() * Math.PI * 2;
    const r = 20 + rnd() * 38;
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r;
    if (tooClose(x, z, 2)) continue;
    trees.push({ x, z, variant: Math.floor(rnd() * 3), scale: 0.9 + rnd() * 0.35, rot: rnd() * Math.PI * 2 });
  }

  // Big collidable rocks.
  for (let i = 0; i < 18; i++) {
    const a = rnd() * Math.PI * 2;
    const r = 28 + rnd() * 34;
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r;
    if (tooClose(x, z, 1)) continue;
    rocks.push({ x, z, scale: 0.8 + rnd() * 1.2, variant: i % 4, rot: rnd() * Math.PI * 2 });
  }
  rocks.push({ x: -46, z: -14, scale: 1.4, variant: 2, rot: 0.4 });
  rocks.push({ x: 40, z: 28, scale: 1.1, variant: 1, rot: 1.2 });
  rocks.push({ x: 18, z: -38, scale: 1.2, variant: 3, rot: 2.1 });

  // Non-collidable ground dressing.
  for (let i = 0; i < 60; i++) {
    const a = rnd() * Math.PI * 2;
    const r = Math.sqrt(rnd()) * 58;
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r;
    if (Math.hypot(x - MAP.pond.x, z - MAP.pond.z) < MAP.pond.radius) continue;
    bushes.push({ x, z, scale: 0.55 + rnd() * 0.75, rot: rnd() * Math.PI * 2 });
  }
  for (let i = 0; i < 180; i++) {
    const a = rnd() * Math.PI * 2;
    const r = Math.sqrt(rnd()) * 58;
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r;
    if (Math.hypot(x - MAP.pond.x, z - MAP.pond.z) < MAP.pond.radius + 1) continue;
    flowers.push({ x, z, color: Math.floor(rnd() * 4), scale: 0.7 + rnd() * 0.7 });
  }
  for (let i = 0; i < 90; i++) {
    const a = rnd() * Math.PI * 2;
    const r = Math.sqrt(rnd()) * 57;
    stones.push({ x: Math.cos(a) * r, z: Math.sin(a) * r, scale: 0.25 + rnd() * 0.5, rot: rnd() * Math.PI });
  }

  return { trees, rocks, bushes, flowers, stones, seed };
}

import * as THREE from '../vendor/three.module.js';
import { M, C, GEO, add } from './materials.js';
import { MAP, generateLayout, mulberry32 } from './map.js';
import { createBush } from './models.js';

const SIZE = 1024;
const WORLD = 150;

function w2c(v) {
  return ((v + WORLD / 2) / WORLD) * SIZE;
}

function makeTerrainCanvas(layout) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = SIZE;
  const ctx = canvas.getContext('2d');
  const rnd = mulberry32(7741);

  // Base grass with painterly patches.
  ctx.fillStyle = '#638b4c';
  ctx.fillRect(0, 0, SIZE, SIZE);
  const greens = ['#5d8447', '#6c9452', '#587d44', '#719b57', '#4f7440', '#7da05c', '#628a4b'];
  for (let i = 0; i < 1500; i++) {
    ctx.fillStyle = greens[Math.floor(rnd() * greens.length)];
    ctx.globalAlpha = 0.18 + rnd() * 0.3;
    const r = 8 + rnd() * 60;
    ctx.beginPath();
    ctx.ellipse(rnd() * SIZE, rnd() * SIZE, r, r * (0.4 + rnd() * 0.8), rnd() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // Darker forest floor under clusters of trees.
  ctx.globalAlpha = 0.22;
  for (const t of layout.trees) {
    const grd = ctx.createRadialGradient(w2c(t.x), w2c(t.z), 0, w2c(t.x), w2c(t.z), 26 * t.scale);
    grd.addColorStop(0, '#2f4c2b');
    grd.addColorStop(1, 'rgba(47,76,43,0)');
    ctx.fillStyle = grd;
    ctx.beginPath();
    ctx.arc(w2c(t.x), w2c(t.z), 26 * t.scale, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // Dirt road between bases.
  const ax = w2c(MAP.path.from.x), az = w2c(MAP.path.from.z);
  const bx = w2c(MAP.path.to.x), bz = w2c(MAP.path.to.z);
  const road = (width, color, alpha) => {
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(ax, az);
    ctx.bezierCurveTo(w2c(-10), w2c(18), w2c(6), w2c(-8), bx, bz);
    ctx.stroke();
  };
  road(86, '#8d7b56', 0.55);
  road(64, '#b19a6b', 0.72);
  road(40, '#c3ad7d', 0.65);
  // Worn wheel ruts.
  ctx.globalAlpha = 0.18;
  ctx.strokeStyle = '#6d5d40';
  ctx.lineWidth = 4;
  for (const offset of [-10, 10]) {
    ctx.beginPath();
    ctx.moveTo(ax + offset, az + offset * 0.2);
    ctx.bezierCurveTo(w2c(-10) + offset, w2c(18), w2c(6) + offset, w2c(-8), bx + offset, bz + offset * 0.2);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // Side trails to gold mines.
  for (const mine of MAP.mines) {
    const base = mine.z < 0 ? MAP.enemyBase : MAP.playerBase;
    ctx.save();
    ctx.setLineDash([10, 18]);
    ctx.strokeStyle = '#b8a173';
    ctx.lineWidth = 22;
    ctx.globalAlpha = 0.5;
    ctx.beginPath();
    ctx.moveTo(w2c(mine.x), w2c(mine.z));
    ctx.lineTo(w2c(base.x), w2c(base.z));
    ctx.stroke();
    ctx.restore();
    ctx.globalAlpha = 1;
  }

  // Stone plazas under both bases.
  for (const base of [MAP.playerBase, MAP.enemyBase]) {
    const x = w2c(base.x), z = w2c(base.z);
    const g = ctx.createRadialGradient(x, z, 2, x, z, 92);
    g.addColorStop(0, '#8f8368');
    g.addColorStop(0.72, '#81765f');
    g.addColorStop(1, 'rgba(129,118,95,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, z, 94, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 0.3;
    ctx.strokeStyle = '#5d5545';
    ctx.lineWidth = 2;
    for (let i = 1; i <= 3; i++) {
      ctx.beginPath();
      ctx.arc(x, z, 22 * i, 0, Math.PI * 2);
      ctx.stroke();
    }
    for (let i = 0; i < 18; i++) {
      const a = i / 18 * Math.PI * 2;
      ctx.beginPath();
      ctx.moveTo(x + Math.cos(a) * 20, z + Math.sin(a) * 20);
      ctx.lineTo(x + Math.cos(a) * 86, z + Math.sin(a) * 86);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;
  }

  // Pond basin.
  const px = w2c(MAP.pond.x), pz = w2c(MAP.pond.z);
  const pondGrad = ctx.createRadialGradient(px - 10, pz - 10, 20, px, pz, 72);
  pondGrad.addColorStop(0, '#2f7486');
  pondGrad.addColorStop(0.7, '#23596b');
  pondGrad.addColorStop(1, '#2f5e4a');
  ctx.fillStyle = pondGrad;
  ctx.beginPath();
  ctx.ellipse(px, pz, 74, 66, 0.2, 0, Math.PI * 2);
  ctx.fill();

  // Fine noise so the terrain does not look flat.
  const noise = ctx.createImageData(SIZE, SIZE);
  for (let i = 0; i < noise.data.length; i += 4) {
    const v = Math.floor(rnd() * 34);
    noise.data[i] = v;
    noise.data[i + 1] = v + 5;
    noise.data[i + 2] = v;
    noise.data[i + 3] = 22;
  }
  ctx.putImageData(noise, 0, 0);

  // Little flowers sprinkled into the texture.
  const petals = ['#e7dc8e', '#f0e6bf', '#c7a6e0', '#e8a9a9', '#f5c96a'];
  for (let i = 0; i < 260; i++) {
    ctx.fillStyle = petals[Math.floor(rnd() * petals.length)];
    ctx.globalAlpha = 0.55;
    ctx.beginPath();
    ctx.arc(rnd() * SIZE, rnd() * SIZE, 1.2 + rnd() * 1.6, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  return canvas;
}

export class World {
  constructor(scene, layout) {
    this.scene = scene;
    this.layout = layout;
    this.clouds = [];
    this.pondMaterial = null;
    this.time = 0;
    this.build();
  }

  build() {
    const scene = this.scene;
    scene.background = new THREE.Color(0x9fc7d6);
    scene.fog = new THREE.Fog(0xa9c9cf, 92, 185);

    this.createSky();
    this.createLights();

    this.terrainCanvas = makeTerrainCanvas(this.layout);
    const tex = new THREE.CanvasTexture(this.terrainCanvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.anisotropy = 8;
    tex.minFilter = THREE.LinearMipmapLinearFilter;
    this.terrainTexture = tex;
    const ground = new THREE.Mesh(
      new THREE.PlaneGeometry(WORLD, WORLD, 1, 1),
      new THREE.MeshStandardMaterial({ map: tex, roughness: 0.98, metalness: 0, color: 0xffffff }),
    );
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    ground.name = 'terrain';
    scene.add(ground);

    // Base plazas: subtle raised stone discs under the starting halls.
    for (const base of [MAP.playerBase, MAP.enemyBase]) {
      const disc = new THREE.Mesh(new THREE.CylinderGeometry(13, 13.4, 0.14, 36), M(0x81765f, { roughness: 0.95 }));
      disc.position.set(base.x, 0.04, base.z);
      disc.receiveShadow = true;
      scene.add(disc);
      const ring = new THREE.Mesh(new THREE.TorusGeometry(10.2, 0.12, 4, 48), M(0x5a5244, { roughness: 1 }));
      ring.rotation.x = Math.PI / 2;
      ring.position.set(base.x, 0.12, base.z);
      scene.add(ring);
    }

    this.createPond();
    this.createMountainRing();
    this.createClouds();
    this.createGroundDetail();
    this.createPollen();
  }

  createSky() {
    const geo = new THREE.SphereGeometry(280, 24, 16);
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        top: { value: new THREE.Color(0x4f93cf) },
        mid: { value: new THREE.Color(0xa8d4e4) },
        bottom: { value: new THREE.Color(0xf2d5a0) },
      },
      vertexShader: `
        varying vec3 vWorld;
        void main() {
          vec4 wp = modelMatrix * vec4(position, 1.0);
          vWorld = wp.xyz;
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: `
        uniform vec3 top; uniform vec3 mid; uniform vec3 bottom;
        varying vec3 vWorld;
        void main() {
          float h = normalize(vWorld).y;
          vec3 col = mix(bottom, mid, smoothstep(-0.05, 0.25, h));
          col = mix(col, top, smoothstep(0.2, 0.85, h));
          float sun = pow(max(dot(normalize(vWorld), normalize(vec3(-0.45, 0.3, 0.65))), 0.0), 120.0);
          col += vec3(1.0, 0.74, 0.4) * sun * 0.65;
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    const sky = new THREE.Mesh(geo, mat);
    sky.frustumCulled = false;
    this.scene.add(sky);

    // A soft sun halo.
    const sun = new THREE.Sprite(new THREE.SpriteMaterial({
      color: 0xffe3a3,
      transparent: true,
      opacity: 0.55,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      fog: false,
    }));
    const c = document.createElement('canvas');
    c.width = c.height = 128;
    const ctx = c.getContext('2d');
    const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
    g.addColorStop(0, 'rgba(255,244,205,1)');
    g.addColorStop(0.25, 'rgba(255,221,145,.65)');
    g.addColorStop(1, 'rgba(255,210,120,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, 128, 128);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    sun.material.map = tex;
    sun.position.set(-95, 95, 150);
    sun.scale.set(70, 70, 1);
    this.scene.add(sun);
  }

  createLights() {
    const hemi = new THREE.HemisphereLight(0xcbe6ff, 0x4e5b3a, 1.5);
    this.scene.add(hemi);

    const sun = new THREE.DirectionalLight(0xffe4ba, 2.65);
    sun.position.set(38, 68, 34);
    sun.castShadow = true;
    sun.shadow.mapSize.set(2048, 2048);
    sun.shadow.camera.left = -72;
    sun.shadow.camera.right = 72;
    sun.shadow.camera.top = 72;
    sun.shadow.camera.bottom = -72;
    sun.shadow.camera.near = 1;
    sun.shadow.camera.far = 180;
    sun.shadow.bias = -0.0007;
    sun.shadow.normalBias = 0.045;
    this.scene.add(sun);
    this.scene.add(sun.target);
    this.sun = sun;

    const fill = new THREE.DirectionalLight(0x9fc8ff, 0.42);
    fill.position.set(-45, 30, -25);
    this.scene.add(fill);
  }

  createPond() {
    const { x, z, radius } = MAP.pond;
    const mat = new THREE.MeshStandardMaterial({
      color: 0x2d7f95,
      emissive: 0x0f4653,
      emissiveIntensity: 0.4,
      transparent: true,
      opacity: 0.9,
      roughness: 0.18,
      metalness: 0.15,
    });
    this.pondMaterial = mat;
    const water = new THREE.Mesh(new THREE.CircleGeometry(radius - 0.4, 40), mat);
    water.rotation.x = -Math.PI / 2;
    water.position.set(x, 0.07, z);
    this.scene.add(water);

    const inner = new THREE.Mesh(new THREE.CircleGeometry(radius * 0.7, 32), new THREE.MeshBasicMaterial({ color: 0x6ec6ce, transparent: true, opacity: 0.13, depthWrite: false }));
    inner.rotation.x = -Math.PI / 2;
    inner.position.set(x, 0.09, z);
    this.scene.add(inner);

    // Reeds and lily pads.
    const rnd = mulberry32(551);
    const reedMat = M(0x5a7a3b);
    const reedHead = M(0x6b4a2a);
    for (let i = 0; i < 22; i++) {
      const a = rnd() * Math.PI * 2;
      const r = radius - 0.8 + rnd() * 1.8;
      const px = x + Math.cos(a) * r;
      const pz = z + Math.sin(a) * r;
      add(this.scene, 'cyl6', reedMat, px, 0.55, pz, 0.035, 1.1, 0.035);
      if (i % 3 === 0) add(this.scene, 'cyl6', reedHead, px, 1.15, pz, 0.07, 0.3, 0.07);
    }
    const padMat = M(0x477a43, { roughness: 0.7 });
    for (let i = 0; i < 8; i++) {
      const a = rnd() * Math.PI * 2;
      const r = rnd() * (radius - 2);
      const pad = add(this.scene, 'cyl', padMat, x + Math.cos(a) * r, 0.12, z + Math.sin(a) * r, 0.8 + rnd() * 0.5, 0.03, 0.8 + rnd() * 0.5);
      pad.rotation.y = rnd() * 3;
    }
    // Shore rocks.
    for (let i = 0; i < 12; i++) {
      const a = i / 12 * Math.PI * 2 + 0.15;
      const r = radius + 0.4;
      add(this.scene, 'dodeca', M(0x7b786e), x + Math.cos(a) * r, 0.18, z + Math.sin(a) * r, 0.7 + rnd() * 0.8, 0.45, 0.6, rnd(), rnd() * 3, 0);
    }
  }

  createMountainRing() {
    const rnd = mulberry32(9001);
    const matA = new THREE.MeshStandardMaterial({ color: 0x6d898c, roughness: 1, flatShading: true });
    const matB = new THREE.MeshStandardMaterial({ color: 0x58747a, roughness: 1, flatShading: true });
    const snow = new THREE.MeshStandardMaterial({ color: 0xd9e6e7, roughness: 0.9, flatShading: true });
    for (let i = 0; i < 26; i++) {
      const a = i / 26 * Math.PI * 2 + rnd() * 0.18;
      const r = 105 + rnd() * 35;
      const h = 22 + rnd() * 30;
      const w = 20 + rnd() * 26;
      const m = add(this.scene, 'cone4', i % 2 ? matA : matB, Math.cos(a) * r, h / 2 - 2, Math.sin(a) * r, w, h, w, 0, rnd() * 3, 0, false);
      m.receiveShadow = false;
      if (h > 40) add(this.scene, 'cone4', snow, Math.cos(a) * r, h - 4, Math.sin(a) * r, w * 0.3, h * 0.18, w * 0.3, 0, m.rotation.y, 0, false);
    }
  }

  createClouds() {
    const mat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.38, depthWrite: false });
    const rnd = mulberry32(333);
    for (let i = 0; i < 10; i++) {
      const g = new THREE.Group();
      const n = 3 + Math.floor(rnd() * 3);
      for (let j = 0; j < n; j++) {
        const m = new THREE.Mesh(GEO.sphere, mat);
        m.position.set((j - n / 2) * 4 + rnd() * 2, rnd() * 1.5, rnd() * 2);
        m.scale.set(6 + rnd() * 5, 1.6 + rnd() * 1.5, 4 + rnd() * 3);
        g.add(m);
      }
      g.position.set(-80 + rnd() * 160, 40 + rnd() * 25, -80 + rnd() * 160);
      g.userData.speed = 0.35 + rnd() * 0.5;
      this.scene.add(g);
      this.clouds.push(g);
    }
  }

  createGroundDetail() {
    const rnd = mulberry32(4242);

    // Grass tufts, one instanced draw call.
    const grassGeo = new THREE.ConeGeometry(0.075, 0.42, 3);
    const grassMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95, flatShading: true });
    const grass = new THREE.InstancedMesh(grassGeo, grassMat, 1400);
    const dummy = new THREE.Object3D();
    const color = new THREE.Color();
    const palette = [0x6e9b50, 0x7fae58, 0x5d8746, 0x8db866, 0x668f4c];
    for (let i = 0; i < 1400; i++) {
      const a = rnd() * Math.PI * 2;
      const r = Math.sqrt(rnd()) * 60;
      dummy.position.set(Math.cos(a) * r, 0.19, Math.sin(a) * r);
      dummy.rotation.y = rnd() * Math.PI;
      const s = 0.55 + rnd() * 1.05;
      dummy.scale.set(s, s, s);
      dummy.updateMatrix();
      grass.setMatrixAt(i, dummy.matrix);
      color.setHex(palette[Math.floor(rnd() * palette.length)]);
      grass.setColorAt(i, color);
    }
    grass.instanceMatrix.needsUpdate = true;
    if (grass.instanceColor) grass.instanceColor.needsUpdate = true;
    grass.receiveShadow = true;
    this.scene.add(grass);

    // Flowers.
    const flowerGeo = new THREE.IcosahedronGeometry(0.075, 0);
    const flowerMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.7, emissive: 0x222211, emissiveIntensity: 0.2 });
    const flowers = new THREE.InstancedMesh(flowerGeo, flowerMat, 260);
    const petalColors = [0xffe07a, 0xf8f0d0, 0xc79bea, 0xf08b8b, 0xffb45e];
    for (let i = 0; i < 260; i++) {
      const a = rnd() * Math.PI * 2;
      const r = Math.sqrt(rnd()) * 58;
      dummy.position.set(Math.cos(a) * r, 0.11, Math.sin(a) * r);
      dummy.rotation.set(0, rnd() * 3, 0);
      const s = 0.7 + rnd() * 0.8;
      dummy.scale.set(s, s, s);
      dummy.updateMatrix();
      flowers.setMatrixAt(i, dummy.matrix);
      color.setHex(petalColors[Math.floor(rnd() * petalColors.length)]);
      flowers.setColorAt(i, color);
    }
    flowers.instanceMatrix.needsUpdate = true;
    if (flowers.instanceColor) flowers.instanceColor.needsUpdate = true;
    this.scene.add(flowers);

    // Pebbles.
    const pebbleGeo = new THREE.DodecahedronGeometry(0.18, 0);
    const pebbles = new THREE.InstancedMesh(pebbleGeo, new THREE.MeshStandardMaterial({ color: 0x8b8779, roughness: 1, flatShading: true }), 90);
    for (let i = 0; i < 90; i++) {
      const a = rnd() * Math.PI * 2;
      const r = Math.sqrt(rnd()) * 57;
      dummy.position.set(Math.cos(a) * r, 0.08, Math.sin(a) * r);
      dummy.rotation.set(rnd(), rnd() * 3, rnd());
      const s = 0.4 + rnd() * 0.9;
      dummy.scale.set(s, s * 0.55, s);
      dummy.updateMatrix();
      pebbles.setMatrixAt(i, dummy.matrix);
    }
    pebbles.instanceMatrix.needsUpdate = true;
    pebbles.receiveShadow = true;
    this.scene.add(pebbles);

    // Bushes.
    for (const b of this.layout.bushes) {
      const bush = createBush(b.scale);
      bush.position.set(b.x, 0.05, b.z);
      bush.rotation.y = b.rot;
      this.scene.add(bush);
    }
  }

  createPollen() {
    const count = 260;
    const positions = new Float32Array(count * 3);
    const rnd = mulberry32(101);
    for (let i = 0; i < count; i++) {
      positions[i * 3] = (rnd() - 0.5) * 120;
      positions[i * 3 + 1] = 1 + rnd() * 12;
      positions[i * 3 + 2] = (rnd() - 0.5) * 120;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({ color: 0xfff2c9, size: 0.16, transparent: true, opacity: 0.55, depthWrite: false, blending: THREE.AdditiveBlending });
    this.pollen = new THREE.Points(geo, mat);
    this.scene.add(this.pollen);
  }

  update(dt) {
    this.time += dt;
    if (this.pondMaterial) this.pondMaterial.emissiveIntensity = 0.32 + Math.sin(this.time * 1.4) * 0.1;
    for (const c of this.clouds) {
      c.position.x += c.userData.speed * dt;
      if (c.position.x > 105) c.position.x = -105;
    }
    if (this.pollen) this.pollen.rotation.y += dt * 0.008;
  }
}

import { MAP } from './map.js';

class MinHeap {
  constructor() { this.a = []; }
  push(node) {
    const a = this.a;
    a.push(node);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p].f <= a[i].f) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop() {
    const a = this.a;
    if (!a.length) return null;
    const top = a[0];
    const last = a.pop();
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = i * 2 + 1;
        const r = l + 1;
        let m = i;
        if (l < a.length && a[l].f < a[m].f) m = l;
        if (r < a.length && a[r].f < a[m].f) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
  get size() { return this.a.length; }
}

export class NavGrid {
  constructor(worldSize = 150, cell = 2) {
    this.min = -worldSize / 2;
    this.cell = cell;
    this.n = Math.floor(worldSize / cell);
    this.counts = new Int16Array(this.n * this.n);
    this.tmpG = new Float32Array(this.n * this.n);
    this.tmpCame = new Int32Array(this.n * this.n);
    this.tmpClosed = new Uint8Array(this.n * this.n);
    this.marked = [];
  }

  idx(cx, cz) { return cz * this.n + cx; }
  inBounds(cx, cz) { return cx >= 0 && cz >= 0 && cx < this.n && cz < this.n; }
  worldToCell(x, z) {
    return {
      cx: Math.max(0, Math.min(this.n - 1, Math.floor((x - this.min) / this.cell))),
      cz: Math.max(0, Math.min(this.n - 1, Math.floor((z - this.min) / this.cell))),
    };
  }
  cellToWorld(cx, cz) {
    return { x: this.min + (cx + 0.5) * this.cell, z: this.min + (cz + 0.5) * this.cell };
  }
  cellOf(ix, iz) { return this.counts[ix + iz * this.n] > 0; }
  isBlockedWorld(x, z) {
    const { cx, cz } = this.worldToCell(x, z);
    return !this.inBounds(cx, cz) || this.counts[this.idx(cx, cz)] > 0;
  }

  addCircle(x, z, radius) {
    const minX = Math.floor((x - radius - this.min) / this.cell);
    const maxX = Math.floor((x + radius - this.min) / this.cell);
    const minZ = Math.floor((z - radius - this.min) / this.cell);
    const maxZ = Math.floor((z + radius - this.min) / this.cell);
    for (let iz = minZ; iz <= maxZ; iz++) {
      for (let ix = minX; ix <= maxX; ix++) {
        if (!this.inBounds(ix, iz)) continue;
        const p = this.cellToWorld(ix, iz);
        if (Math.hypot(p.x - x, p.z - z) <= radius + this.cell * 0.18) {
          this.counts[this.idx(ix, iz)]++;
        }
      }
    }
  }

  removeCircle(x, z, radius) {
    const minX = Math.floor((x - radius - this.min) / this.cell);
    const maxX = Math.floor((x + radius - this.min) / this.cell);
    const minZ = Math.floor((z - radius - this.min) / this.cell);
    const maxZ = Math.floor((z + radius - this.min) / this.cell);
    for (let iz = minZ; iz <= maxZ; iz++) {
      for (let ix = minX; ix <= maxX; ix++) {
        if (!this.inBounds(ix, iz)) continue;
        const p = this.cellToWorld(ix, iz);
        if (Math.hypot(p.x - x, p.z - z) <= radius + this.cell * 0.18) {
          const i = this.idx(ix, iz);
          if (this.counts[i] > 0) this.counts[i]--;
        }
      }
    }
  }

  addRect(x, z, hw, hd) {
    const minX = Math.floor((x - hw - this.min) / this.cell);
    const maxX = Math.floor((x + hw - this.min) / this.cell);
    const minZ = Math.floor((z - hd - this.min) / this.cell);
    const maxZ = Math.floor((z + hd - this.min) / this.cell);
    for (let iz = minZ; iz <= maxZ; iz++) {
      for (let ix = minX; ix <= maxX; ix++) {
        if (!this.inBounds(ix, iz)) continue;
        this.counts[this.idx(ix, iz)]++;
      }
    }
  }

  removeRect(x, z, hw, hd) {
    const minX = Math.floor((x - hw - this.min) / this.cell);
    const maxX = Math.floor((x + hw - this.min) / this.cell);
    const minZ = Math.floor((z - hd - this.min) / this.cell);
    const maxZ = Math.floor((z + hd - this.min) / this.cell);
    for (let iz = minZ; iz <= maxZ; iz++) {
      for (let ix = minX; ix <= maxX; ix++) {
        if (!this.inBounds(ix, iz)) continue;
        const i = this.idx(ix, iz);
        if (this.counts[i] > 0) this.counts[i]--;
      }
    }
  }

  nearestFreeCell(cx, cz, maxRadius = 18) {
    if (this.inBounds(cx, cz) && this.counts[this.idx(cx, cz)] === 0) return { cx, cz };
    for (let r = 1; r <= maxRadius; r++) {
      for (let dz = -r; dz <= r; dz++) {
        for (let dx = -r; dx <= r; dx++) {
          if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue;
          const nx = cx + dx, nz = cz + dz;
          if (this.inBounds(nx, nz) && this.counts[this.idx(nx, nz)] === 0) return { cx: nx, cz: nz };
        }
      }
    }
    return { cx, cz };
  }

  nearestFreePoint(x, z, maxRadius = 30) {
    const c = this.worldToCell(x, z);
    const f = this.nearestFreeCell(c.cx, c.cz, maxRadius);
    return this.cellToWorld(f.cx, f.cz);
  }

  hasLine(a, b) {
    const dx = b.x - a.x;
    const dz = b.z - a.z;
    const dist = Math.hypot(dx, dz);
    const steps = Math.max(2, Math.ceil(dist / (this.cell * 0.6)));
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      if (this.isBlockedWorld(a.x + dx * t, a.z + dz * t)) return false;
    }
    return true;
  }

  findPath(sx, sz, tx, tz) {
    const start = this.worldToCell(sx, sz);
    let end = this.worldToCell(tx, tz);
    end = this.nearestFreeCell(end.cx, end.cz);
    if (start.cx === end.cx && start.cz === end.cz) {
      const p = this.cellToWorld(end.cx, end.cz);
      return [p];
    }
    const n = this.n;
    const g = this.tmpG;
    const came = this.tmpCame;
    const closed = this.tmpClosed;
    g.fill(Infinity);
    came.fill(-1);
    closed.fill(0);
    const startIdx = start.cx + start.cz * n;
    const endIdx = end.cx + end.cz * n;
    g[startIdx] = 0;
    const heap = new MinHeap();
    heap.push({ i: startIdx, f: Math.hypot(end.cx - start.cx, end.cz - start.cz) });
    let found = false;
    let guard = 0;
    while (heap.size && guard++ < 12000) {
      const node = heap.pop();
      const i = node.i;
      if (closed[i]) continue;
      if (i === endIdx) { found = true; break; }
      closed[i] = 1;
      const cx = i % n;
      const cz = (i / n) | 0;
      for (let dz = -1; dz <= 1; dz++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (!dx && !dz) continue;
          const nx = cx + dx, nz = cz + dz;
          if (!this.inBounds(nx, nz)) continue;
          if (this.counts[nx + nz * n] > 0) continue;
          if (dx && dz) {
            if (this.counts[(cx + dx) + cz * n] > 0 || this.counts[cx + (cz + dz) * n] > 0) continue;
          }
          const ni = nx + nz * n;
          if (closed[ni]) continue;
          const cost = g[i] + (dx && dz ? 1.4142 : 1);
          if (cost < g[ni]) {
            g[ni] = cost;
            came[ni] = i;
            const h = Math.hypot(end.cx - nx, end.cz - nz);
            heap.push({ i: ni, f: cost + h * 1.05 });
          }
        }
      }
    }
    if (!found) return [];
    const cells = [];
    let cur = endIdx;
    let guard2 = 0;
    while (cur !== -1 && guard2++ < 20000) {
      cells.push(cur);
      if (cur === startIdx) break;
      cur = came[cur];
    }
    cells.reverse();
    const pts = cells.map(i => this.cellToWorld(i % n, (i / n) | 0));
    // Smooth with line-of-sight checks.
    const out = [];
    let i = 0;
    out.push({ x: sx, z: sz });
    while (i < pts.length - 1) {
      let j = pts.length - 1;
      while (j > i + 1 && !this.hasLine(pts[i], pts[j])) j--;
      out.push(pts[j]);
      i = j;
    }
    // Remove the initial point (unit already stands there).
    if (out.length > 1) out.shift();
    // Also drop points that are extremely close to the unit.
    while (out.length > 1 && Math.hypot(out[0].x - sx, out[0].z - sz) < 1.4) out.shift();
    return out;
  }
}

export function buildStaticBlockers(nav, layout) {
  // Map border.
  for (let i = 0; i < nav.n; i++) {
    nav.counts[i] = 1;
    nav.counts[i + (nav.n - 1) * nav.n] = 1;
    nav.counts[i * nav.n] = 1;
    nav.counts[(nav.n - 1) + i * nav.n] = 1;
  }
  // Pond, fountain and the rich central mine get blocked by the game entities.
  nav.addCircle(MAP.pond.x, MAP.pond.z, MAP.pond.radius);
  for (const r of layout.rocks) nav.addCircle(r.x, r.z, 0.9 * r.scale + 0.3);
  for (const t of layout.trees) nav.addCircle(t.x, t.z, 0.52 * t.scale + 0.35);
  // Keep the very edge of the play area clear of pathing.
  const edge = MAP.playable + 1;
  for (let iz = 0; iz < nav.n; iz++) {
    for (let ix = 0; ix < nav.n; ix++) {
      const p = nav.cellToWorld(ix, iz);
      if (Math.abs(p.x) > edge || Math.abs(p.z) > edge) nav.counts[ix + iz * nav.n] = 1;
    }
  }
}

import * as THREE from '../vendor/three.module.js';
import { GEO, GLOW_TEX, M, C } from './materials.js';

const ARROW_MAT = M(0x8b6a3e);

export class Effects {
  constructor(scene, game) {
    this.scene = scene;
    this.game = game;
    this.projectiles = [];
    this.particles = [];
    this.rings = [];
    this.flashes = [];
  }

  projectile(source, target, kind, damage) {
    const g = new THREE.Group();
    const isMagic = kind === 'holy' || kind === 'shadow' || kind === 'lightning';
    if (isMagic) {
      const colors = { holy: 0xffd76a, shadow: 0x79ffb0, lightning: 0x8de8ff };
      const color = colors[kind] || 0xffffff;
      const orb = new THREE.Mesh(GEO.sphere, M(color, { emissive: color, emissiveIntensity: 2.4 }));
      orb.scale.setScalar(kind === 'shadow' ? 0.24 : 0.18);
      g.add(orb);
      const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: GLOW_TEX, color, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false }));
      glow.scale.set(1.2, 1.2, 1);
      g.add(glow);
    } else if (kind === 'spear') {
      const shaft = new THREE.Mesh(GEO.cyl6, ARROW_MAT);
      shaft.scale.set(0.045, 1.25, 0.045);
      shaft.rotation.x = Math.PI / 2;
      g.add(shaft);
      const tip = new THREE.Mesh(GEO.cone4, M(C.steel));
      tip.scale.set(0.09, 0.25, 0.09);
      tip.rotation.x = Math.PI / 2;
      tip.position.z = 0.72;
      g.add(tip);
      const feather = new THREE.Mesh(GEO.box, M(0xc9b27a));
      feather.scale.set(0.16, 0.16, 0.22);
      feather.position.z = -0.6;
      g.add(feather);
    } else {
      const shaft = new THREE.Mesh(GEO.cyl6, ARROW_MAT);
      shaft.scale.set(0.026, 0.82, 0.026);
      shaft.rotation.x = Math.PI / 2;
      g.add(shaft);
      const tip = new THREE.Mesh(GEO.cone4, M(kind === 'bone' ? 0xdcd5bb : C.steel));
      tip.scale.set(0.055, 0.16, 0.055);
      tip.rotation.x = Math.PI / 2;
      tip.position.z = 0.48;
      g.add(tip);
      const feather = new THREE.Mesh(GEO.box, M(kind === 'bone' ? 0x9f9781 : 0xe4d7b1));
      feather.scale.set(0.1, 0.1, 0.16);
      feather.position.z = -0.38;
      g.add(feather);
    }
    const start = new THREE.Vector3(source.pos.x, source.barHeight ? source.barHeight * 0.55 : 1.2, source.pos.z);
    g.position.copy(start);
    this.scene.add(g);
    this.projectiles.push({
      mesh: g,
      source,
      target,
      damage,
      kind,
      t: 0,
      duration: kind === 'spear' ? 0.34 : isMagic ? 0.42 : 0.28,
      end: new THREE.Vector3(target.pos.x, 1.0, target.pos.z),
      height: isMagic ? 0.6 : 1.1,
    });
  }

  hit(target, color = 0xffd78a, power = 1) {
    this.burst(target.pos.x, target.barHeight ? target.barHeight * 0.55 : 1.0, target.pos.z, color, Math.round(5 * power), 2.2 * power);
  }

  heal(target, color = 0x78ffb4) {
    const x = target.pos.x, z = target.pos.z;
    const y = target.barHeight ? target.barHeight * 0.5 : 1;
    for (let i = 0; i < 6; i++) {
      const s = this.makeSprite(color, 0.35 + Math.random() * 0.3, 1.2);
      s.position.set(x + (Math.random() - 0.5) * 0.8, 0.2 + Math.random() * 1.6, z + (Math.random() - 0.5) * 0.8);
      this.particles.push({ sprite: s, vx: (Math.random() - 0.5) * 0.4, vy: 1.2 + Math.random(), vz: 0, life: 0.9, maxLife: 0.9, grow: 0.3, fade: true, gravity: -0.2 });
    }
    this.ring(x, z, color, 1.3, 0.75, 0.5);
    this.burst(x, y, z, color, 5, 1.2);
  }

  burst(x, y, z, color = 0xffd78a, count = 6, power = 2) {
    for (let i = 0; i < count; i++) {
      const s = this.makeSprite(color, 0.18 + Math.random() * 0.22, 1.5);
      s.position.set(x, y, z);
      const a = Math.random() * Math.PI * 2;
      const up = 0.8 + Math.random() * 1.8;
      this.particles.push({
        sprite: s,
        vx: Math.cos(a) * power * (0.4 + Math.random()),
        vy: up * power * 0.35,
        vz: Math.sin(a) * power * (0.4 + Math.random()),
        life: 0.45 + Math.random() * 0.35,
        maxLife: 0.8,
        grow: 0.6,
        fade: true,
        gravity: -5,
      });
    }
  }

  dust(x, z, color = 0xb9a884, count = 8, radius = 1) {
    for (let i = 0; i < count; i++) {
      const s = this.makeSprite(color, 0.8 + Math.random() * 0.8, 0.8);
      const a = Math.random() * Math.PI * 2;
      const r = Math.random() * radius;
      s.position.set(x + Math.cos(a) * r, 0.25 + Math.random() * 0.4, z + Math.sin(a) * r);
      this.particles.push({
        sprite: s, vx: Math.cos(a) * 0.9, vy: 0.5 + Math.random() * 0.8, vz: Math.sin(a) * 0.9,
        life: 0.9 + Math.random() * 0.7, maxLife: 1.6, grow: 1.2, fade: true, gravity: -0.4,
      });
    }
  }

  ring(x, z, color = 0xffd27a, radius = 1.5, duration = 0.6, opacity = 0.8) {
    const geo = new THREE.RingGeometry(0.75, 1, 32);
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(x, 0.12, z);
    mesh.scale.setScalar(radius * 0.25);
    this.scene.add(mesh);
    this.rings.push({ mesh, t: 0, duration, radius, opacity });
  }

  buildComplete(x, z, color = 0xffd27a) {
    this.ring(x, z, color, 4, 1.1, 0.9);
    this.dust(x, z, 0xcabf9e, 14, 1.6);
    this.burst(x, 1, z, color, 14, 2.4);
  }

  makeSprite(color, scale = 0.4, opacity = 1) {
    const mat = new THREE.SpriteMaterial({ map: GLOW_TEX, color, transparent: true, opacity, blending: THREE.AdditiveBlending, depthWrite: false });
    const s = new THREE.Sprite(mat);
    s.scale.set(scale, scale, 1);
    this.scene.add(s);
    return s;
  }

  update(dt) {
    const game = this.game;

    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      if (!p.target || p.target.dead) {
        p.mesh.removeFromParent();
        this.projectiles.splice(i, 1);
        continue;
      }
      p.t += dt;
      const end = p.target.pos;
      p.end.set(end.x, p.target.barHeight ? p.target.barHeight * 0.55 : 1, end.z);
      const t = Math.min(1, p.t / p.duration);
      const sx = p.mesh.position.x, sz = p.mesh.position.z;
      const x = p.mesh.position.x + (p.end.x - p.mesh.position.x) * Math.min(1, dt / Math.max(0.02, p.duration - p.t + dt));
      // Simpler: recompute from the stored start is not available, so lerp toward end.
      p.mesh.position.x += (p.end.x - p.mesh.position.x) * Math.min(1, dt * 14);
      p.mesh.position.z += (p.end.z - p.mesh.position.z) * Math.min(1, dt * 14);
      p.mesh.position.y = 1 + Math.sin(t * Math.PI) * p.height + (p.end.y - 1) * t;
      const lookTarget = new THREE.Vector3(p.end.x, p.end.y, p.end.z);
      if (p.kind !== 'holy' && p.kind !== 'shadow' && p.kind !== 'lightning') {
        p.mesh.lookAt(lookTarget);
      } else {
        p.mesh.rotation.y += dt * 8;
      }
      if (t >= 1 || Math.hypot(p.mesh.position.x - p.end.x, p.mesh.position.z - p.end.z) < 0.5) {
        if (p.target && !p.target.dead) game.dealDamage(p.source, p.target, p.damage, p.kind);
        const color = p.kind === 'holy' ? 0xffe08a : p.kind === 'shadow' ? 0x76ffb5 : p.kind === 'bone' ? 0xdcd5bb : 0xffd18a;
        this.burst(p.end.x, p.end.y, p.end.z, color, 4, 1.2);
        p.mesh.removeFromParent();
        this.projectiles.splice(i, 1);
      }
      // Keep memory sane if something stalls.
      if (p.t > 3) {
        p.mesh.removeFromParent();
        this.projectiles.splice(i, 1);
      }
    }

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        p.sprite.material.dispose();
        p.sprite.removeFromParent();
        this.particles.splice(i, 1);
        continue;
      }
      p.vy += (p.gravity ?? 0) * dt;
      p.sprite.position.x += p.vx * dt;
      p.sprite.position.y += p.vy * dt;
      p.sprite.position.z += p.vz * dt;
      const k = 1 - p.life / p.maxLife;
      const s = p.sprite.scale.x * (1 + p.grow * dt);
      p.sprite.scale.set(s, s, 1);
      p.sprite.material.opacity = (1 - k) * 0.95;
    }

    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.t += dt;
      const k = Math.min(1, r.t / r.duration);
      const s = r.radius * (0.2 + k * 1.1);
      r.mesh.scale.set(s, s, 1);
      r.mesh.material.opacity = r.opacity * (1 - k);
      if (k >= 1) {
        r.mesh.geometry.dispose();
        r.mesh.material.dispose();
        r.mesh.removeFromParent();
        this.rings.splice(i, 1);
      }
    }
  }

  clear() {
    for (const p of this.projectiles) p.mesh.removeFromParent();
    for (const p of this.particles) { p.sprite.material.dispose(); p.sprite.removeFromParent(); }
    for (const r of this.rings) { r.mesh.geometry.dispose(); r.mesh.material.dispose(); r.mesh.removeFromParent(); }
    this.projectiles.length = 0;
    this.particles.length = 0;
    this.rings.length = 0;
  }
}

import * as THREE from '../vendor/three.module.js';
import { createUnitModel, createBuildingModel, createTree, createGoldMine, createFountain } from './models.js';
import { GEO } from './materials.js';
import { RACES } from './data.js';

const ringMats = new Map();
function ringMat(color) {
  if (!ringMats.has(color)) ringMats.set(color, new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.85, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending }));
  return ringMats.get(color);
}

class HealthBar {
  constructor(parent, width = 1.8, y = 2) {
    this.canvas = document.createElement('canvas');
    this.canvas.width = 128;
    this.canvas.height = 18;
    this.ctx = this.canvas.getContext('2d');
    this.texture = new THREE.CanvasTexture(this.canvas);
    this.texture.colorSpace = THREE.SRGBColorSpace;
    this.material = new THREE.SpriteMaterial({ map: this.texture, transparent: true, depthTest: false, depthWrite: false });
    this.sprite = new THREE.Sprite(this.material);
    this.sprite.scale.set(width, width * 0.14, 1);
    this.sprite.position.y = y;
    this.sprite.renderOrder = 30;
    this.sprite.visible = false;
    this.ratio = -1;
    this.color = '#4c8dff';
    this.construction = 0;
    this.width = width;
    parent.add(this.sprite);
  }
  set(ratio, color, construction = 0) {
    const r = Math.max(0, Math.min(1, ratio));
    const c = Math.round(construction * 100);
    if (Math.abs(r - this.ratio) < 0.004 && color === this.color && c === this.construction) return;
    this.ratio = r;
    this.color = color;
    this.construction = c;
    const ctx = this.ctx;
    const w = this.canvas.width;
    const h = this.canvas.height;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = 'rgba(5,9,13,.9)';
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(255,255,255,.55)';
    ctx.lineWidth = 2;
    ctx.strokeRect(1, 1, w - 2, h - 2);
    let fill = ratio > 0.55 ? '#58d06a' : ratio > 0.28 ? '#e8c34a' : '#ec5b4f';
    if (construction > 0 && construction < 100) fill = '#6ab8ff';
    ctx.fillStyle = fill;
    const innerW = (w - 6) * r;
    ctx.fillRect(3, 3, innerW, h - 6);
    if (construction > 0 && construction < 100) {
      ctx.fillStyle = 'rgba(255,255,255,.75)';
      ctx.fillRect(3, 13, (w - 6) * Math.min(1, construction / 100), 2);
    }
    this.texture.needsUpdate = true;
  }
  dispose() {
    this.texture.dispose();
    this.material.dispose();
  }
}

class BaseView {
  constructor(game, entity, model, height) {
    this.game = game;
    this.entity = entity;
    this.model = model;
    this.root = new THREE.Group();
    this.root.position.set(entity.pos.x, 0, entity.pos.z);
    this.root.add(model);
    this.height = height;
    this.phase = Math.random() * 10;
    this.time = 0;
    this.selected = false;
    this.deathT = 0;
    game.scene.add(this.root);
    this.ring = null;
    this.bar = null;
    model.traverse((o) => {
      if (o.isMesh) o.userData.entityId = entity.id;
    });
  }
  addRing(radius, color) {
    const r = new THREE.Mesh(GEO.ring, ringMat(color));
    r.rotation.x = -Math.PI / 2;
    r.position.y = 0.07;
    r.scale.setScalar(radius);
    r.visible = false;
    r.renderOrder = 12;
    this.root.add(r);
    this.ring = r;
  }
  setSelected(v) {
    this.selected = v;
    if (this.ring) this.ring.visible = v;
  }
  updateBar() {
    if (!this.bar) return;
    const e = this.entity;
    const damaged = e.hp < e.maxHp - 0.01;
    this.bar.sprite.visible = this.selected || damaged || (e.construction !== undefined && e.construction < 1);
    if (this.bar.sprite.visible) {
      const ratio = e.construction !== undefined && e.construction < 1 ? e.construction : e.hp / e.maxHp;
      this.bar.set(ratio, e.teamColor, e.construction !== undefined ? e.construction : 0);
    }
  }
  syncCommon() {
    this.root.position.x = this.entity.pos.x;
    this.root.position.z = this.entity.pos.z;
    if (this.entity.facing !== undefined) this.root.rotation.y = this.entity.facing;
    this.updateBar();
  }
  remove() {
    this.bar?.dispose();
    this.root.removeFromParent();
  }
}

export class UnitView extends BaseView {
  constructor(game, entity) {
    const model = createUnitModel(entity.race, entity.role, entity.teamColor);
    const height = model.userData.anim?.height || 2;
    super(game, entity, model, height);
    this.anim = model.userData.anim || {};
    this.walkPhase = Math.random() * 6;
    this.attackT = 0;
    this.workT = 0;
    this.facing = entity.facing || 0;
    this.addRing(Math.max(0.8, entity.radius * 1.7), entity.team === 0 ? 0x8fc2ff : 0xff6a5c);
    this.bar = new HealthBar(this.root, Math.max(1.2, entity.radius * 3.2), height + 0.35);
    this.bar.set(1, entity.teamColor);
    this.model.traverse((o) => { if (o.isMesh) o.userData.entityId = entity.id; });
  }
  update(dt) {
    const e = this.entity;
    this.time += dt;
    if (this.attackT > 0) this.attackT = Math.max(0, this.attackT - dt);
    const moving = e.moving && !e.dead;
    const working = e.working && !e.dead;
    if (e.dead) {
      this.deathT += dt;
      this.model.rotation.z = Math.min(1.5, this.deathT * 2.4);
      this.model.position.y = -Math.min(0.35, this.deathT * 0.12);
      this.ring.visible = false;
      this.bar.sprite.visible = false;
      this.syncCommon();
      return;
    }
    this.syncCommon();
    // Smooth turning toward the entity's facing direction.
    let target = e.facing || 0;
    let diff = target - this.facing;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    this.facing += diff * Math.min(1, dt * 12);
    this.root.rotation.y = this.facing;

    const anim = this.anim;
    if (moving) this.walkPhase += dt * (e.role === 'heavy' ? 11 : 13);
    const swing = moving ? Math.sin(this.walkPhase) : Math.sin(this.time * 2 + this.phase) * 0.05;
    const legAmp = e.role === 'heavy' ? 0.55 : 0.62;
    if (anim.legs) {
      if (e.role === 'heavy') {
        anim.legs.forEach((leg, i) => {
          const off = i < 2 ? 0 : Math.PI;
          leg.rotation.x = swing * legAmp + off;
        });
      } else {
        anim.legs.forEach((leg, i) => { leg.rotation.x = swing * legAmp * (i ? -1 : 1); });
      }
    }
    // Arms: attack swing takes priority, then working, then walking.
    const attackK = this.attackT > 0 ? Math.sin((1 - this.attackT / 0.32) * Math.PI) : 0;
    if (anim.arms) {
      anim.arms.forEach((arm, i) => {
        let x = moving ? -swing * 0.35 * (i ? -1 : 1) : 0;
        if (i === 1 && attackK > 0) x = -1.35 * attackK;
        if (i === 1 && working) x = -0.9 + Math.sin(this.time * 15) * 0.55;
        arm.rotation.x = x;
      });
      if (anim.arms[0]) anim.arms[0].rotation.z = e.role === 'caster' ? -0.18 : 0.04;
    }
    // Whole-body gait bob.
    this.model.position.y = moving ? Math.abs(Math.sin(this.walkPhase)) * (e.role === 'heavy' ? 0.05 : 0.07) : Math.sin(this.time * 2.2 + this.phase) * 0.012;
    if (anim.glow) {
      const k = 1 + Math.sin(this.time * 5 + this.phase) * 0.16;
      anim.glow.scale.setScalar(1 * k);
    }
    if (anim.runes) {
      anim.runes.rotation.y += dt * 0.7;
    }
    if (anim.eyes) {
      const k = 1.4 + Math.sin(this.time * 3 + this.phase) * 0.4;
      anim.eyes.forEach(eye => { eye.material.emissiveIntensity = k; });
    }
    if (anim.mount) {
      this.model.position.y += Math.abs(Math.sin(this.walkPhase)) * 0.02;
    }
  }
}

export class BuildingView extends BaseView {
  constructor(game, entity) {
    const model = createBuildingModel(entity.race, entity.role, entity.teamColor);
    const size = entity.size;
    model.scale.setScalar(size);
    const box = new THREE.Box3().setFromObject(model);
    const height = box.max.y;
    super(game, entity, model, height);
    this.size = size;
    this.anim = model.userData.anim || {};
    this.baseScale = size;
    this.addRing(size * 1.15, entity.team === 0 ? 0x8fc2ff : 0xff6a5c);
    this.bar = new HealthBar(this.root, Math.min(4.6, size * 1.35), height + 0.55);
    this.bar.set(1, entity.teamColor);
    this.model.traverse((o) => { if (o.isMesh) o.userData.entityId = entity.id; });
  }
  update(dt) {
    const e = this.entity;
    this.time += dt;
    this.syncCommon();
    if (e.dead) {
      this.deathT += dt;
      this.root.rotation.z = Math.min(0.35, this.deathT * 0.6);
      this.root.position.y = -Math.min(0.8, this.deathT * 0.4);
      this.ring.visible = false;
      this.bar.sprite.visible = false;
      return;
    }
    const construction = e.construction !== undefined ? e.construction : 1;
    if (construction < 1) {
      const k = 0.35 + construction * 0.65;
      this.model.scale.set(this.baseScale * k, this.baseScale * (0.15 + construction * 0.85), this.baseScale * k);
      this.model.position.y = 0;
    } else if (Math.abs(this.model.scale.x - this.baseScale) > 0.001) {
      this.model.scale.setScalar(this.baseScale);
    }
    if (this.anim.flags) {
      this.anim.flags.forEach((flag) => {
        flag.rotation.y = Math.sin(this.time * 2.2 + (flag.userData.phase || 0)) * 0.24;
      });
    }
    if (this.anim.fire) {
      this.anim.fire.forEach((f) => {
        const s = 0.9 + Math.sin(this.time * 9 + this.phase) * 0.15;
        f.scale.set(f.scale.x, s, f.scale.z);
      });
    }
    if (this.anim.glow) {
      this.anim.glow.forEach((g) => {
        if (g.material) g.material.emissiveIntensity = 1.6 + Math.sin(this.time * 3 + this.phase) * 0.4;
      });
    }
  }
}

export class ResourceView extends BaseView {
  constructor(game, entity) {
    let model;
    if (entity.resourceType === 'gold') model = createGoldMine();
    else if (entity.resourceType === 'lumber') model = createTree(entity.variant || 0, entity.scale || 1);
    else model = createFountain();
    const box = new THREE.Box3().setFromObject(model);
    const height = box.max.y;
    super(game, entity, model, height);
    this.kind = entity.resourceType;
    this.baseY = 0;
    this.anim = model.userData.anim || {};
    this.fountainWater = model.userData.water;
    this.fountainCrystal = model.userData.crystal;
    this.model.traverse((o) => { if (o.isMesh) o.userData.entityId = entity.id; });
  }
  update(dt) {
    this.time += dt;
    this.syncCommon();
    if (this.kind === 'lumber') {
      this.model.rotation.z = Math.sin(this.time * 0.9 + this.phase) * 0.012;
    }
    if (this.kind === 'fountain') {
      if (this.fountainCrystal) {
        this.fountainCrystal.rotation.y += dt * 0.8;
        this.fountainCrystal.position.y = 2.3 + Math.sin(this.time * 1.8) * 0.1;
      }
      if (this.fountainWater) {
        this.fountainWater.material.emissiveIntensity = 0.55 + Math.sin(this.time * 2.2) * 0.18;
      }
    }
    if (this.bar) this.updateBar();
  }
}

export function createView(game, entity) {
  if (entity.kind === 'unit') return new UnitView(game, entity);
  if (entity.kind === 'building') return new BuildingView(game, entity);
  return new ResourceView(game, entity);
}

// ---------------------------------------------------------------------------
// Offscreen 3D thumbnails for the command card and the live portrait.
// ---------------------------------------------------------------------------
class ThumbRenderer {
  constructor() {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true });
    this.renderer.setPixelRatio(1.5);
    this.renderer.setSize(128, 128, false);
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.1;
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(32, 1, 0.01, 100);
    this.scene.add(new THREE.HemisphereLight(0xdcecff, 0x53452e, 1.6));
    const key = new THREE.DirectionalLight(0xfff0d2, 2.6);
    key.position.set(2.5, 4, 3.5);
    this.scene.add(key);
    const rim = new THREE.DirectionalLight(0x7fb2ff, 1.2);
    rim.position.set(-3, 2, -2);
    this.scene.add(rim);
    this.cache = new Map();
    this.backup = new THREE.Group();
    this.scene.add(this.backup);
  }
  fill(model, cameraAngle = 0.5) {
    this.backup.clear();
    const box = new THREE.Box3().setFromObject(model);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());
    const maxDim = Math.max(size.x, size.y, size.z);
    model.position.sub(center);
    const holder = new THREE.Group();
    holder.add(model);
    holder.rotation.y = cameraAngle;
    this.backup.add(holder);
    const dist = maxDim * 2.3;
    this.camera.position.set(0, maxDim * 0.45, dist);
    this.camera.lookAt(0, 0, 0);
    this.camera.near = Math.max(0.01, dist - maxDim * 2);
    this.camera.far = dist + maxDim * 4;
    this.camera.updateProjectionMatrix();
  }
  thumbnail(race, role, isBuilding, teamColor) {
    const key = `${race}:${role}:${isBuilding ? 'b' : 'u'}`;
    if (this.cache.has(key)) return this.cache.get(key);
    const model = isBuilding ? createBuildingModel(race, role, teamColor) : createUnitModel(race, role, teamColor);
    if (isBuilding) model.scale.setScalar(1.7);
    this.fill(model, isBuilding ? 0.62 : 0.4);
    this.renderer.render(this.scene, this.camera);
    const url = this.renderer.domElement.toDataURL('image/png');
    this.backup.clear();
    this.cache.set(key, url);
    return url;
  }
}

export const iconRenderer = new ThumbRenderer();

export class PortraitRenderer {
  constructor(holder) {
    this.holder = holder;
    this.renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    this.renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.15;
    this.renderer.setClearColor(0x000000, 0);
    this.canvas = this.renderer.domElement;
    this.canvas.className = 'portrait-canvas';
    holder.appendChild(this.canvas);
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(30, 1, 0.01, 100);
    this.scene.add(new THREE.HemisphereLight(0xd8ebff, 0x5b4a32, 1.5));
    this.key = new THREE.DirectionalLight(0xffe8c4, 2.8);
    this.key.position.set(2, 4, 3);
    this.scene.add(this.key);
    this.rim = new THREE.DirectionalLight(0x7fb2ff, 1.6);
    this.rim.position.set(-3, 2.5, -2);
    this.scene.add(this.rim);
    this.holderGroup = new THREE.Group();
    this.scene.add(this.holderGroup);
    this.entity = null;
    this.model = null;
    this.time = 0;
    this.spin = 0.25;
    this.resize();
    window.addEventListener('resize', () => this.resize());
  }
  resize() {
    const rect = this.holder.getBoundingClientRect();
    const w = Math.max(64, Math.floor(rect.width || 160));
    const h = Math.max(64, Math.floor(rect.height || 160));
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    this.camera.updateProjectionMatrix();
  }
  show(entity) {
    this.entity = entity;
    this.holderGroup.clear();
    this.model = null;
    if (!entity) { this.renderer.clear(); return; }
    const race = entity.race;
    let model;
    if (entity.kind === 'building') {
      model = createBuildingModel(race, entity.role, entity.teamColor);
      model.scale.setScalar(1.8);
    } else if (entity.kind === 'unit') {
      model = createUnitModel(race, entity.role, entity.teamColor);
    } else {
      return;
    }
    this.model = model;
    this.holderGroup.add(model);
    const box = new THREE.Box3().setFromObject(model);
    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());
    const maxDim = Math.max(size.x, size.y, size.z);
    model.position.sub(center);
    model.position.y += maxDim * 0.06;
    const dist = maxDim * 1.85;
    this.camera.position.set(0, maxDim * 0.35, dist);
    this.camera.lookAt(0, 0, 0);
    this.camera.near = Math.max(0.01, dist - maxDim * 2);
    this.camera.far = dist + maxDim * 4;
    this.camera.updateProjectionMatrix();
    const color = entity.teamColor || 0x4c8dff;
    this.rim.color.set(color);
    this.time = 0;
    this.spin = entity.kind === 'building' ? 0.18 : 0.4;
    this.renderer.render(this.scene, this.camera);
  }
  update(dt) {
    if (!this.model) return;
    this.time += dt;
    if (this.model) {
      this.holderGroup.rotation.y = Math.sin(this.time * this.spin) * 0.35;
      if (this.entity?.kind === 'unit') {
        this.holderGroup.position.y = Math.sin(this.time * 2) * 0.015;
      }
    }
    this.renderer.render(this.scene, this.camera);
  }
}

import * as THREE from '../vendor/three.module.js';
import { unitDef, buildingDef } from './data.js';

let NEXT_ID = 1;

export class Entity {
  constructor(game, opts) {
    this.game = game;
    this.id = NEXT_ID++;
    this.kind = opts.kind;
    this.team = opts.team ?? -1;
    this.race = opts.race ?? null;
    this.role = opts.role ?? null;
    this.pos = new THREE.Vector3(opts.x, 0, opts.z);
    this.facing = opts.facing ?? 0;
    this.hp = opts.hp ?? 1;
    this.maxHp = opts.hp ?? 1;
    this.radius = opts.radius ?? 0.5;
    this.dead = false;
    this.removeT = 0;
    this.teamColor = opts.teamColor ?? 0xd8b45a;
    this.barHeight = opts.barHeight ?? 1.5;
    this.selected = false;
  }
  distanceTo(x, z) {
    return Math.hypot(this.pos.x - x, this.pos.z - z);
  }
  distanceToEntity(e) {
    return Math.hypot(this.pos.x - e.pos.x, this.pos.z - e.pos.z);
  }
  faceTo(x, z) {
    const dx = x - this.pos.x;
    const dz = z - this.pos.z;
    if (Math.abs(dx) + Math.abs(dz) > 0.001) this.facing = Math.atan2(dx, dz);
  }
}

export class Unit extends Entity {
  constructor(game, team, role, x, z, opts = {}) {
    const def = unitDef(team.race, role);
    super(game, {
      kind: 'unit', team: team.id, race: team.race, role,
      x, z, hp: def.hp, radius: def.radius, teamColor: team.color3d,
      facing: opts.facing ?? 0,
    });
    this.def = def;
    this.speed = def.speed;
    this.damage = def.damage;
    this.armor = def.armor;
    this.range = def.range;
    this.attackSpeed = def.attackSpeed;
    this.projectile = def.projectile || null;
    this.heal = def.heal || 0;
    this.healRange = def.healRange || 0;
    this.healCooldown = def.healCooldown || 6;
    this.supply = def.supply;
    this.state = 'idle';
    this.path = [];
    this.dest = null;
    this.target = null;
    this.attackMoveDest = null;
    this.gatherNode = null;
    this.gatherType = null;
    this.carry = 0;
    this.carryType = null;
    this.buildTarget = null;
    this.cooldown = Math.random() * 0.3;
    this.think = Math.random() * 0.4;
    this.repath = 0;
    this.healTimer = Math.random() * 2;
    this.attackAnim = 0;
    this.working = false;
    this.moving = false;
    this.lastAttacker = null;
    this.orderOrigin = null;
    this.barHeight = def.role === 'heavy' ? 2.6 : 2.1;
    this.spawnT = game.time;
  }

  setPathTo(x, z) {
    const p = this.game.nav.findPath(this.pos.x, this.pos.z, x, z);
    this.path = p;
    if (!p.length) {
      const free = this.game.nav.nearestFreePoint(x, z, 30);
      this.path = [{ x: free.x, z: free.z }];
    }
  }

  clearOrder() {
    this.state = 'idle';
    this.path = [];
    this.dest = null;
    this.target = null;
    this.attackMoveDest = null;
    this.gatherNode = null;
    this.gatherType = null;
    this.buildTarget = null;
    this.working = false;
    this.moving = false;
    this.carry = 0;
    this.carryType = null;
    this.orderOrigin = null;
  }

  moveAlongPath(dt, speedMul = 1) {
    if (!this.path.length) {
      this.moving = false;
      return true;
    }
    let point = this.path[0];
    let dx = point.x - this.pos.x;
    let dz = point.z - this.pos.z;
    let dist = Math.hypot(dx, dz);
    if (dist < 0.42) {
      this.path.shift();
      if (!this.path.length) {
        this.moving = false;
        return true;
      }
      point = this.path[0];
      dx = point.x - this.pos.x;
      dz = point.z - this.pos.z;
      dist = Math.hypot(dx, dz);
    }
    if (dist < 0.001) return false;
    this.faceTo(point.x, point.z);
    const step = Math.min(dist, this.speed * speedMul * dt);
    const nx = this.pos.x + (dx / dist) * step;
    const nz = this.pos.z + (dz / dist) * step;
    const nav = this.game.nav;
    if (!nav.isBlockedWorld(nx, nz)) {
      this.pos.x = nx;
      this.pos.z = nz;
    } else if (!nav.isBlockedWorld(nx, this.pos.z)) {
      this.pos.x = nx;
    } else if (!nav.isBlockedWorld(this.pos.x, nz)) {
      this.pos.z = nz;
    } else {
      this.path = [];
      this.moving = false;
      return true;
    }
    this.moving = true;
    return false;
  }

  gatherSpot(node) {
    const jitter = ((this.id % 7) - 3) * 0.18;
    const base = Math.atan2(this.pos.z - node.pos.z, this.pos.x - node.pos.x) + jitter;
    const r = node.radius + 1.05;
    let x = node.pos.x + Math.cos(base) * r;
    let z = node.pos.z + Math.sin(base) * r;
    if (this.game.nav.isBlockedWorld(x, z)) {
      const p = this.game.nav.nearestFreePoint(x, z, 12);
      x = p.x; z = p.z;
    }
    return { x, z };
  }

  dropoffSpot(building) {
    const angle = Math.atan2(this.pos.z - building.pos.z, this.pos.x - building.pos.x) + ((this.id % 5) - 2) * 0.2;
    const r = building.size * 0.9 + 1.15;
    let x = building.pos.x + Math.cos(angle) * r;
    let z = building.pos.z + Math.sin(angle) * r;
    if (this.game.nav.isBlockedWorld(x, z)) {
      const p = this.game.nav.nearestFreePoint(x, z, 14);
      x = p.x; z = p.z;
    }
    return { x, z };
  }

  nearEntity(e, extra = 0) {
    return this.distanceToEntity(e) <= e.radius + extra;
  }
}

export class Building extends Entity {
  constructor(game, team, role, x, z, opts = {}) {
    const def = buildingDef(team.race, role);
    super(game, {
      kind: 'building', team: team.id, race: team.race, role,
      x, z, hp: opts.complete === false ? def.hp * 0.18 : def.hp,
      radius: def.size * 0.9, teamColor: team.color3d,
      facing: opts.facing ?? 0,
    });
    this.def = def;
    this.size = def.size;
    this.maxHp = def.hp;
    this.construction = opts.complete === false ? 0 : 1;
    this.completed = this.construction >= 1;
    this.queue = [];
    this.rally = new THREE.Vector2(x, z);
    this.rallyResource = null;
    this.cooldown = Math.random() * 0.5;
    this.target = null;
    this.think = Math.random() * 0.4;
    this.barHeight = def.size * 2;
    this.underAttackT = 0;
    this.builderCount = 0;
    if (opts.rally) this.rally.set(opts.rally.x, opts.rally.z);
  }

  get isHall() { return this.role === 'hall'; }
  get isProduction() { return !!(this.def.trains && this.def.trains.length); }

  addSupply() {
    if (this.completed && this.def.supply) this.game.teamOf(this.team).supplyCap += this.def.supply;
  }
}

export class Resource extends Entity {
  constructor(game, type, x, z, opts = {}) {
    super(game, {
      kind: 'resource', team: -1, race: null, role: type,
      x, z, hp: opts.amount ?? 1, radius: opts.radius ?? 1,
      teamColor: 0xd8b45a, facing: opts.rot ?? 0,
      barHeight: opts.barHeight ?? 2,
    });
    this.resourceType = type;
    this.amount = opts.amount ?? Infinity;
    this.maxAmount = this.amount;
    this.variant = opts.variant ?? 0;
    this.scale = opts.scale ?? 1;
    this.navRadius = opts.navRadius ?? this.radius;
    this.exhausted = false;
    this.phase = Math.random() * Math.PI * 2;
  }
}

import * as THREE from '../vendor/three.module.js';
import { RACES, unitDef, buildingDef, TEAM_COLORS, DIFFICULTY } from './data.js';
import { MAP, generateLayout } from './map.js';
import { NavGrid, buildStaticBlockers } from './nav.js';
import { World } from './world.js';
import { Effects } from './effects.js';
import { Unit, Building, Resource } from './entities.js';
import { createView } from './render.js';
import { createRock } from './models.js';
import { AIController } from './ai.js';
import { updateUnit, updateBuilding, updateFountain } from './combat.js';

export class Game {
  constructor(scene, options = {}) {
    this.scene = scene;
    this.options = options;
    this.playerRace = options.playerRace || 'human';
    this.aiRace = options.aiRace || 'orc';
    this.difficulty = DIFFICULTY[options.difficulty] || DIFFICULTY.normal;
    this.time = 0;
    this.over = false;
    this.paused = false;
    this.winner = null;
    this.layout = generateLayout();
    this.world = new World(scene, this.layout);
    this.effects = new Effects(scene, this);
    this.nav = new NavGrid(150, 2);
    buildStaticBlockers(this.nav, this.layout);
    this.entities = [];
    this.units = [];
    this.buildings = [];
    this.resources = [];
    this.selection = [];
    this.factory = {};
    this.onSelectionChanged = null;
    this.onNotify = null;
    this.onFloatText = null;
    this.onGameOver = null;
    this.onStats = null;
    this.notifyCooldowns = new Map();
    this.recalcT = 0;
    this.pingT = 0;
    this.teams = [
      this.makeTeam(0, this.playerRace, false),
      this.makeTeam(1, this.aiRace, true),
    ];
    this.createRallyMarker();
    this.populateMap();
    this.createStartBase(this.teams[0]);
    this.createStartBase(this.teams[1]);
    this.recalcSupply();
    this.startWorkers();
    this.ai = new AIController(this, 1, this.difficulty);
    this.updateRallyMarker();
  }

  makeTeam(id, race, isAI) {
    return {
      id, race, isAI,
      color: id === 0 ? TEAM_COLORS.player : TEAM_COLORS.enemy,
      color3d: id === 0 ? TEAM_COLORS.player3d : TEAM_COLORS.enemy3d,
      gold: 520,
      lumber: 260,
      supplyCap: 0,
      supplyUsed: 0,
      alive: true,
      stats: { goldGathered: 0, lumberGathered: 0, trained: 0, killed: 0, lost: 0, buildingsBuilt: 0 },
    };
  }

  teamOf(id) {
    return this.teams[id];
  }

  otherTeam(id) {
    return id === 0 ? 1 : 0;
  }

  notify(text, type = 'info', cooldown = 0) {
    if (!this.onNotify) return;
    if (cooldown) {
      const last = this.notifyCooldowns.get(text) || -999;
      if (this.time - last < cooldown) return;
      this.notifyCooldowns.set(text, this.time);
    }
    this.onNotify(text, type);
  }

  floatText(pos, text, color = '#ffd166') {
    if (this.onFloatText) this.onFloatText(pos, text, color);
  }

  // -------------------------------------------------------------------------
  // Map population
  // -------------------------------------------------------------------------
  populateMap() {
    for (const t of this.layout.trees) {
      this.spawnResource('lumber', t.x, t.z, {
        amount: 120, radius: 0.62 * t.scale + 0.28, navRadius: 0.52 * t.scale + 0.35,
        variant: t.variant, scale: t.scale, rot: t.rot, barHeight: 4 * t.scale,
        addNav: false,
      });
    }
    for (const r of this.layout.rocks) {
      const model = createRock(r.scale, r.variant);
      model.position.set(r.x, 0, r.z);
      model.rotation.y = r.rot;
      this.scene.add(model);
    }
    for (let i = 0; i < MAP.mines.length; i++) {
      const m = MAP.mines[i];
      this.spawnResource('gold', m.x, m.z, {
        amount: m.amount, radius: 2.5, navRadius: 2.5, barHeight: 2.2,
        variant: i, rich: m.rich,
      });
    }
    this.spawnResource('fountain', MAP.fountain.x, MAP.fountain.z, {
      amount: Infinity, radius: 4.2, navRadius: 4.4, barHeight: 3,
    });
  }

  spawnResource(type, x, z, opts = {}) {
    const r = new Resource(this, type, x, z, opts);
    this.resources.push(r);
    this.entities.push(r);
    if (opts.addNav !== false && type !== 'lumber') {
      this.nav.addCircle(x, z, r.navRadius);
    }
    r.view = createView(this, r);
    r.view.root.rotation.y = r.facing;
    r.barHeight = r.view.height;
    return r;
  }

  createRallyMarker() {
    const g = new THREE.Group();
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 1.6, 6), new THREE.MeshStandardMaterial({ color: 0x6b4a2a }));
    pole.position.y = 0.8;
    g.add(pole);
    const flag = new THREE.Mesh(new THREE.PlaneGeometry(0.7, 0.45), new THREE.MeshBasicMaterial({ color: this.teams[0].color3d, side: THREE.DoubleSide }));
    flag.position.set(0.35, 1.35, 0);
    g.add(flag);
    this.rallyFlag = flag;
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.45, 0.62, 24), new THREE.MeshBasicMaterial({ color: this.teams[0].color3d, transparent: true, opacity: 0.8, side: THREE.DoubleSide, depthWrite: false }));
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.05;
    g.add(ring);
    g.visible = false;
    this.rallyMarker = g;
    this.scene.add(g);
  }

  createStartBase(team) {
    const base = team.id === 0 ? MAP.playerBase : MAP.enemyBase;
    const toward = team.id === 0 ? MAP.enemyBase : MAP.playerBase;
    const facing = Math.atan2(toward.x - base.x, toward.z - base.z);
    const hall = this.spawnBuilding(team, 'hall', base.x, base.z, { complete: true, facing });
    const mine = this.findNearestResource(team, 'gold', base.x, base.z);
    if (mine) {
      hall.rally.set(mine.pos.x, mine.pos.z);
      hall.rallyResource = mine;
    }
    // Starting army.
    const angleToCenter = Math.atan2(-base.z, -base.x);
    for (let i = 0; i < 4; i++) {
      const a = angleToCenter + (i - 1.5) * 0.32;
      const x = base.x + Math.cos(a) * 7.4;
      const z = base.z + Math.sin(a) * 7.4;
      this.spawnUnit(team, 'worker', x, z, { facing: facing + Math.PI });
    }
    for (let i = 0; i < 2; i++) {
      const a = angleToCenter + 1.8 + i * 0.32;
      const x = base.x + Math.cos(a) * 7.2;
      const z = base.z + Math.sin(a) * 7.2;
      const u = this.spawnUnit(team, 'melee', x, z, { facing: facing + Math.PI });
      u.homePos = { x, z };
    }
    this.recalcSupply();
    return hall;
  }

  startWorkers() {
    for (const team of this.teams) {
      const workers = this.unitsOf(team.id).filter(u => u.role === 'worker');
      const mines = this.resources.filter(r => r.resourceType === 'gold' && r.amount > 0);
      const trees = this.resources.filter(r => r.resourceType === 'lumber' && r.amount > 0);
      workers.forEach((w, i) => {
        if (i < 2) {
          const node = this.nearestFrom(w, mines);
          if (node) this.assignGather(w, node);
        } else {
          const node = this.nearestFrom(w, trees);
          if (node) this.assignGather(w, node);
        }
      });
    }
  }

  nearestFrom(unit, list) {
    let best = null;
    let bestD = Infinity;
    for (const e of list) {
      if (e.dead || e.amount <= 0) continue;
      const d = unit.distanceToEntity(e);
      if (d < bestD) { bestD = d; best = e; }
    }
    return best;
  }

  spawnUnit(team, role, x, z, opts = {}) {
    if (this.nav.isBlockedWorld(x, z)) {
      const p = this.nav.nearestFreePoint(x, z, 20);
      x = p.x; z = p.z;
    }
    const u = new Unit(this, team, role, x, z, opts);
    this.units.push(u);
    this.entities.push(u);
    u.view = createView(this, u);
    u.barHeight = u.view.height;
    u.view.root.rotation.y = u.facing;
    if (opts.homePos) u.homePos = opts.homePos;
    this.recalcSupply();
    return u;
  }

  spawnBuilding(team, role, x, z, opts = {}) {
    const def = buildingDef(team.race, role);
    const b = new Building(this, team, role, x, z, opts);
    this.buildings.push(b);
    this.entities.push(b);
    this.nav.addRect(x, z, def.size * 0.86, def.size * 0.86);
    b.view = createView(this, b);
    b.barHeight = b.view.height;
    b.view.root.rotation.y = b.facing;
    if (b.completed) this.recalcSupply();
    return b;
  }

  canPlaceAt(x, z, size) {
    const half = size * 0.88;
    if (Math.abs(x) + half > MAP.playable - 1 || Math.abs(z) + half > MAP.playable - 1) return false;
    const nav = this.nav;
    const minX = Math.floor((x - half - nav.min) / nav.cell);
    const maxX = Math.floor((x + half - nav.min) / nav.cell);
    const minZ = Math.floor((z - half - nav.min) / nav.cell);
    const maxZ = Math.floor((z + half - nav.min) / nav.cell);
    for (let iz = minZ; iz <= maxZ; iz++) {
      for (let ix = minX; ix <= maxX; ix++) {
        if (!nav.inBounds(ix, iz)) return false;
        if (nav.counts[ix + iz * nav.n] > 0) return false;
      }
    }
    // Do not let a building sit right on top of a unit.
    for (const u of this.units) {
      if (u.dead) continue;
      if (Math.hypot(u.pos.x - x, u.pos.z - z) < half + 0.65) return false;
    }
    return true;
  }

  startBuilding(team, role, x, z, worker = null) {
    const def = buildingDef(team.race, role);
    if (!this.canAfford(team, def.cost)) {
      if (!team.isAI) this.notify(`Не хватает ресурсов: ${this.costMissing(team, def.cost)}`, 'warn');
      return { ok: false, reason: 'resources' };
    }
    if (!this.canPlaceAt(x, z, def.size)) {
      if (!team.isAI) this.notify('Здесь нельзя строить', 'warn');
      return { ok: false, reason: 'blocked' };
    }
    this.pay(team, def.cost);
    const b = this.spawnBuilding(team, role, x, z, { complete: false });
    if (worker) this.orderBuild([worker], b);
    if (!team.isAI) this.notify(`${def.name}: заложен фундамент`, 'info');
    return { ok: true, building: b };
  }

  canAfford(team, cost) {
    return (team.gold >= (cost.gold || 0)) && (team.lumber >= (cost.lumber || 0));
  }

  costMissing(team, cost) {
    const parts = [];
    if (team.gold < (cost.gold || 0)) parts.push(`${(cost.gold || 0) - team.gold} зол.`);
    if (team.lumber < (cost.lumber || 0)) parts.push(`${(cost.lumber || 0) - team.lumber} древ.`);
    return parts.join(', ');
  }

  pay(team, cost) {
    team.gold -= cost.gold || 0;
    team.lumber -= cost.lumber || 0;
  }

  refund(team, cost) {
    team.gold += cost.gold || 0;
    team.lumber += cost.lumber || 0;
  }

  findBuildSpot(team, size, minR = 6.5, maxR = 15) {
    const hall = this.getHall(team.id);
    if (!hall) return null;
    const rnd = Math.random() * Math.PI * 2;
    for (let r = minR; r <= maxR; r += 1.1) {
      for (let i = 0; i < 18; i++) {
        const a = rnd + (i / 18) * Math.PI * 2 + r * 0.15;
        const x = hall.pos.x + Math.cos(a) * r;
        const z = hall.pos.z + Math.sin(a) * r;
        if (Math.hypot(x, z) > MAP.playable - 3) continue;
        if (this.canPlaceAt(x, z, size)) return { x, z };
      }
    }
    return null;
  }

  // -------------------------------------------------------------------------
  // Unit production
  // -------------------------------------------------------------------------
  totalQueuedSupply(teamId) {
    let sum = 0;
    for (const b of this.buildings) {
      if (b.team !== teamId || b.dead) continue;
      for (const q of b.queue) sum += q.supply;
    }
    return sum;
  }

  enqueueUnit(building, role, silent = false) {
    if (!building || building.dead || building.construction < 1) return false;
    if (building.queue.length >= 5) {
      if (!silent) this.notify('Очередь обучения заполнена', 'warn', 2);
      return false;
    }
    const team = this.teams[building.team];
    const def = unitDef(team.race, role);
    if (!this.canAfford(team, def.cost)) {
      if (!silent) this.notify(`Не хватает ресурсов: ${this.costMissing(team, def.cost)}`, 'warn', 2);
      return false;
    }
    const reserved = team.supplyUsed + this.totalQueuedSupply(team.id) + def.supply;
    if (reserved > team.supplyCap) {
      if (!silent) this.notify('Нужно больше снабжения — постройте ферму', 'warn', 3);
      return false;
    }
    this.pay(team, def.cost);
    building.queue.push({ role, time: 0, total: def.train, cost: { ...def.cost }, supply: def.supply });
    if (!silent && !team.isAI) this.notify(`${def.name}: обучение начато`, 'info');
    return true;
  }

  cancelQueue(building, index) {
    if (index < 0 || index >= building.queue.length) return;
    const team = this.teams[building.team];
    const q = building.queue[index];
    this.refund(team, q.cost);
    building.queue.splice(index, 1);
    if (!team.isAI) this.notify('Обучение отменено, ресурсы возвращены', 'info');
  }

  spawnFromBuilding(building) {
    const team = this.teams[building.team];
    const q = building.queue[0];
    if (!q) return;
    const def = unitDef(team.race, q.role);
    if (team.supplyUsed + def.supply > team.supplyCap) {
      if (!team.isAI) this.notify('Нужно больше снабжения — постройте ферму', 'warn', 4);
      return;
    }
    const rally = building.rally;
    let dx = rally.x - building.pos.x;
    let dz = rally.y - building.pos.z;
    let len = Math.hypot(dx, dz);
    if (len < 0.1) { dx = 0; dz = 1; len = 1; }
    const spawnR = building.size * 0.95 + 1.15;
    const baseAngle = Math.atan2(dz, dx) + (Math.random() - 0.5) * 0.8;
    let x = building.pos.x + Math.cos(baseAngle) * spawnR;
    let z = building.pos.z + Math.sin(baseAngle) * spawnR;
    if (this.nav.isBlockedWorld(x, z)) {
      const p = this.nav.nearestFreePoint(x, z, 16);
      x = p.x; z = p.z;
    }
    const unit = this.spawnUnit(team, q.role, x, z, { facing: Math.atan2(dx, dz) });
    unit.homePos = { x, z };
    building.queue.shift();
    team.stats.trained++;
    team.supplyUsed += def.supply;
    this.recalcSupply();
    if (unit.role === 'worker' && building.rallyResource && !building.rallyResource.dead && building.rallyResource.amount > 0) {
      this.assignGather(unit, building.rallyResource);
    } else if (Math.hypot(rally.x - unit.pos.x, rally.y - unit.pos.z) > 2) {
      this.orderMove([unit], { x: rally.x, z: rally.y }, { formation: false });
    }
    this.effects.dust(x, z, 0xd8c9a5, 5, 0.7);
    this.effects.ring(x, z, team.color3d, 1.4, 0.6, 0.55);
    if (!team.isAI) this.notify(`${def.name} готов к бою`, 'success');
  }

  // -------------------------------------------------------------------------
  // Orders
  // -------------------------------------------------------------------------
  ownUnitsSelected() {
    return this.selection.filter(e => !e.dead && e.kind === 'unit' && e.team === 0);
  }

  orderMove(units, point, opts = {}) {
    if (!units.length) return;
    const formation = opts.formation !== false;
    const spots = formation ? this.formationSpots(units, point) : units.map(() => ({ x: point.x, z: point.z }));
    units.forEach((u, i) => {
      if (u.dead) return;
      u.clearOrder();
      u.state = opts.attackMove ? 'attackMove' : 'move';
      const free = this.nav.isBlockedWorld(spots[i].x, spots[i].z) ? this.nav.nearestFreePoint(spots[i].x, spots[i].z, 20) : spots[i];
      u.dest = { x: free.x, z: free.z };
      u.attackMoveDest = opts.attackMove ? { x: point.x, z: point.z } : null;
      u.orderOrigin = { x: u.pos.x, z: u.pos.z };
      u.setPathTo(free.x, free.z);
    });
    this.effects.ring(point.x, point.z, opts.attackMove ? 0xff8a5c : 0x8fc2ff, 1.5, 0.55, 0.7);
  }

  formationSpots(units, point) {
    if (units.length === 1) return [{ x: point.x, z: point.z }];
    const n = units.length;
    const cols = Math.ceil(Math.sqrt(n));
    const spacing = 1.7;
    const rows = Math.ceil(n / cols);
    // Face the formation towards its movement direction.
    let cx = 0, cz = 0;
    for (const u of units) { cx += u.pos.x; cz += u.pos.z; }
    cx /= n; cz /= n;
    const ang = Math.atan2(point.x - cx, point.z - cz);
    const cos = Math.cos(ang), sin = Math.sin(ang);
    // Rows are perpendicular to the direction of travel.
    const spots = [];
    for (let i = 0; i < n; i++) {
      const row = Math.floor(i / cols);
      const col = i % cols;
      const lateral = (col - (cols - 1) / 2) * spacing;
      const forward = -row * spacing;
      spots.push({
        x: point.x + lateral * cos + forward * sin,
        z: point.z - lateral * sin + forward * cos,
      });
    }
    return spots;
  }

  orderAttack(units, target) {
    if (!units.length || !target || target.dead) return;
    for (const u of units) {
      if (u.dead) continue;
      u.clearOrder();
      u.state = 'attack';
      u.target = target;
      u.orderOrigin = { x: u.pos.x, z: u.pos.z };
      u.repath = 0;
      const spot = this.targetApproach(u, target);
      u.setPathTo(spot.x, spot.z);
    }
    this.effects.ring(target.pos.x, target.pos.z, 0xff5a4a, Math.max(1.5, target.radius), 0.6, 0.8);
  }

  targetApproach(u, target) {
    const r = target.radius + Math.max(0.5, u.def.range * 0.65);
    const a = Math.atan2(u.pos.z - target.pos.z, u.pos.x - target.pos.x);
    let x = target.pos.x + Math.cos(a) * r;
    let z = target.pos.z + Math.sin(a) * r;
    if (this.nav.isBlockedWorld(x, z)) {
      const p = this.nav.nearestFreePoint(x, z, 16);
      x = p.x; z = p.z;
    }
    return { x, z };
  }

  assignGather(worker, node) {
    if (!worker || worker.dead || worker.role !== 'worker' || !node || node.dead || node.amount <= 0) return;
    worker.clearOrder();
    worker.state = 'toResource';
    worker.gatherNode = node;
    worker.gatherType = node.resourceType;
    worker.orderOrigin = { x: worker.pos.x, z: worker.pos.z };
    const spot = worker.gatherSpot(node);
    worker.dest = spot;
    worker.setPathTo(spot.x, spot.z);
    worker.faceTo(node.pos.x, node.pos.z);
  }

  orderGather(workers, node) {
    const list = workers.filter(w => w.role === 'worker' && !w.dead);
    if (!list.length) {
      this.notify('Для добычи нужен рабочий', 'warn', 2);
      return;
    }
    list.forEach(w => this.assignGather(w, node));
    this.effects.ring(node.pos.x, node.pos.z, node.resourceType === 'gold' ? 0xffd166 : 0x8fd06a, 1.8, 0.55, 0.7);
  }

  orderBuild(workers, building) {
    if (!building || building.dead) return;
    for (const w of workers) {
      if (w.dead || w.role !== 'worker') continue;
      w.clearOrder();
      w.state = 'build';
      w.buildTarget = building;
      w.orderOrigin = { x: w.pos.x, z: w.pos.z };
      const spot = w.dropoffSpot(building);
      w.dest = spot;
      w.setPathTo(spot.x, spot.z);
    }
  }

  orderStop(units) {
    for (const u of units) {
      if (u.dead) continue;
      u.clearOrder();
      u.state = 'idle';
    }
    this.notify('Отряд остановлен', 'info', 1);
  }

  setRally(building, point, node = null) {
    building.rally.set(point.x, point.z);
    building.rallyResource = node;
    if (node) {
      this.notify(`Точка сбора: ${node.resourceType === 'gold' ? 'золотая шахта' : 'лес'}`, 'info');
    } else {
      this.notify('Точка сбора установлена', 'info');
    }
    this.updateRallyMarker();
  }

  findNearestResource(team, type, x, z) {
    let best = null;
    let bestD = Infinity;
    for (const r of this.resources) {
      if (r.dead || r.amount <= 0 || r.resourceType !== type) continue;
      const d = Math.hypot(r.pos.x - x, r.pos.z - z);
      if (d < bestD) { bestD = d; best = r; }
    }
    return best;
  }

  findNearestDropoff(team, x, z) {
    let best = null;
    let bestD = Infinity;
    for (const b of this.buildings) {
      if (b.dead || b.team !== team.id || !b.completed || !b.def.dropoff) continue;
      const d = Math.hypot(b.pos.x - x, b.pos.z - z);
      if (d < bestD) { bestD = d; best = b; }
    }
    return best;
  }

  clearOrderForTarget(entity) {
    for (const u of this.units) {
      if (u.dead) continue;
      if (u.target === entity) { u.target = null; if (u.state === 'attack') u.state = u.attackMoveDest ? 'attackMove' : 'idle'; }
      if (u.gatherNode === entity) { u.gatherNode = null; u.state = 'idle'; u.path = []; }
      if (u.buildTarget === entity) { u.buildTarget = null; u.state = 'idle'; u.path = []; }
    }
  }

  // -------------------------------------------------------------------------
  // Selection
  // -------------------------------------------------------------------------
  setSelection(list) {
    const filtered = [];
    for (const e of list) {
      if (!e || e.dead) continue;
      if (!filtered.includes(e)) filtered.push(e);
    }
    for (const e of this.selection) {
      e.selected = false;
      e.view?.setSelected(false);
    }
    this.selection = filtered;
    for (const e of filtered) {
      e.selected = true;
      e.view?.setSelected(true);
    }
    this.updateRallyMarker();
    if (this.onSelectionChanged) this.onSelectionChanged(filtered);
  }

  deselect() {
    this.setSelection([]);
  }

  primary() {
    return this.selection[0] || null;
  }

  updateRallyMarker() {
    if (!this.rallyMarker) return;
    const b = this.selection.length === 1 ? this.selection[0] : null;
    if (!b || b.kind !== 'building' || b.team !== 0 || b.dead) {
      this.rallyMarker.visible = false;
      return;
    }
    this.rallyMarker.visible = true;
    this.rallyMarker.position.set(b.rally.x, 0, b.rally.y);
    this.rallyFlag.material.color.setHex(this.teams[0].color3d);
    this.rallyMarker.children[2].material.color.setHex(this.teams[0].color3d);
    const s = 0.9 + Math.sin(this.time * 3) * 0.06;
    this.rallyFlag.scale.set(s, 1, 1);
    this.rallyFlag.rotation.y = Math.sin(this.time * 2.4) * 0.3;
  }

  // -------------------------------------------------------------------------
  // Damage and death
  // -------------------------------------------------------------------------
  dealDamage(source, target, amount, type = 'physical') {
    if (!target || target.dead || target.kind === 'resource') return 0;
    const magic = type === 'holy' || type === 'shadow' || type === 'lightning';
    const armor = target.armor || 0;
    let dmg = amount - armor * (magic ? 0.35 : 0.7);
    dmg = Math.max(1, dmg);
    target.hp -= dmg;
    target.lastAttacker = source;
    if (target.kind === 'building') target.underAttackT = 4;
    this.effects.hit(target, magic ? 0x9fffe0 : 0xffd18a, magic ? 1.1 : 0.9);
    if (target.kind === 'unit' && target.role !== 'worker' && target.state === 'idle' && source && source.team !== target.team) {
      if (target.distanceToEntity(source) < 14) {
        target.state = 'attack';
        target.target = source;
        target.orderOrigin = { x: target.pos.x, z: target.pos.z };
      }
    }
    if (source && source.team !== undefined && source.team >= 0) {
      const st = this.teams[source.team]?.stats;
      if (st) st.damage = (st.damage || 0) + dmg;
    }
    if (target.hp <= 0) this.killEntity(target, source);
    return dmg;
  }

  killEntity(e, source = null) {
    if (e.dead) return;
    e.dead = true;
    e.hp = 0;
    e.removeT = 0;
    if (e.kind === 'unit') {
      this.effects.dust(e.pos.x, e.pos.z, 0xb9a884, 7, 0.5);
      this.effects.burst(e.pos.x, 1.0, e.pos.z, e.team === 0 ? 0x8fb9ff : 0xff8a7a, 6, 1.4);
      this.teams[e.team].stats.lost++;
      if (source && source.team !== undefined && source.team >= 0) this.teams[source.team].stats.killed++;
      if (e.selected) this.setSelection(this.selection.filter(s => s !== e));
      this.recalcSupply();
    } else if (e.kind === 'building') {
      this.effects.dust(e.pos.x, e.pos.z, 0xcabf9e, 20, e.size * 0.8);
      this.effects.burst(e.pos.x, 1.4, e.pos.z, e.team === 0 ? 0x8fb9ff : 0xff8a7a, 18, 2.6);
      this.nav.removeRect(e.pos.x, e.pos.z, e.def.size * 0.86, e.def.size * 0.86);
      this.clearOrderForTarget(e);
      if (e.selected) this.setSelection(this.selection.filter(s => s !== e));
      if (e.team >= 0) {
        this.teams[e.team].stats.lost++;
        if (source && source.team !== undefined && source.team >= 0) this.teams[source.team].stats.killed++;
      }
      this.recalcSupply();
      const teamName = RACES[e.race].name;
      if (!this.teams[e.team]?.isAI) this.notify(`${e.def.name} уничтожен!`, 'danger');
      else this.notify(`Вражеское здание уничтожено: ${e.def.name}`, 'success');
      this.checkVictory(e.team);
    } else if (e.kind === 'resource') {
      this.nav.removeCircle(e.pos.x, e.pos.z, e.navRadius);
      this.effects.dust(e.pos.x, e.pos.z, 0x8a6b3a, 10, 1.2);
    }
  }

  removeEntity(e) {
    const vi = this.selection.indexOf(e);
    if (vi >= 0) {
      this.selection.splice(vi, 1);
      if (this.onSelectionChanged) this.onSelectionChanged(this.selection);
    }
    e.view?.remove();
    const ei = this.entities.indexOf(e);
    if (ei >= 0) this.entities.splice(ei, 1);
    const ui = this.units.indexOf(e);
    if (ui >= 0) this.units.splice(ui, 1);
    const bi = this.buildings.indexOf(e);
    if (bi >= 0) this.buildings.splice(bi, 1);
    const ri = this.resources.indexOf(e);
    if (ri >= 0) this.resources.splice(ri, 1);
  }

  exhaustResource(node) {
    if (node.resourceType === 'lumber') {
      this.killEntity(node, null);
      node.removeT = 99;
      this.removeEntity(node);
    } else {
      node.exhausted = true;
      node.amount = 0;
      if (node.view) node.view.root.traverse((o) => {
        if (o.isMesh && o.material && o.material.emissive) o.material.emissiveIntensity = 0;
      });
    }
  }

  checkVictory(lostTeam) {
    if (this.over) return;
    const halls = this.buildings.filter(b => b.team === lostTeam && b.role === 'hall' && !b.dead);
    if (halls.length === 0) {
      this.teams[lostTeam].alive = false;
      this.endGame(this.otherTeam(lostTeam));
    }
  }

  endGame(winner) {
    if (this.over) return;
    this.over = true;
    this.winner = winner;
    this.effects.clear();
    if (this.onGameOver) this.onGameOver(winner, this.teams, this.time);
  }

  // -------------------------------------------------------------------------
  // Supply and helpers
  // -------------------------------------------------------------------------
  recalcSupply() {
    for (const team of this.teams) {
      let cap = 0;
      let used = 0;
      for (const b of this.buildings) {
        if (b.team === team.id && !b.dead && b.completed && b.def.supply) cap += b.def.supply;
      }
      for (const u of this.units) {
        if (u.team === team.id && !u.dead) used += u.supply;
      }
      team.supplyCap = Math.min(60, cap);
      team.supplyUsed = used;
    }
  }

  getHall(teamId) {
    return this.buildings.find(b => b.team === teamId && !b.dead && b.role === 'hall');
  }

  unitsOf(teamId) {
    return this.units.filter(u => u.team === teamId && !u.dead);
  }

  buildingsOf(teamId) {
    return this.buildings.filter(b => b.team === teamId && !b.dead);
  }

  enemiesNear(teamId, x, z, radius) {
    const out = [];
    for (const u of this.units) {
      if (u.dead || u.team === teamId) continue;
      if (Math.hypot(u.pos.x - x, u.pos.z - z) <= radius) out.push(u);
    }
    return out;
  }

  // -------------------------------------------------------------------------
  // Main loop
  // -------------------------------------------------------------------------
  update(dt) {
    dt = Math.min(dt, 0.05);
    this.time += dt;
    this.world.update(dt);
    if (!this.paused && !this.over) {
      for (const u of [...this.units]) if (!u.dead) updateUnit(this, u, dt);
      for (const b of [...this.buildings]) if (!b.dead) updateBuilding(this, b, dt);
      updateFountain(this, dt);
      this.ai.update(dt);
      this.resolveCollisions(dt);
      this.recalcT -= dt;
      if (this.recalcT <= 0) { this.recalcT = 0.4; this.recalcSupply(); }
      this.updateRallyMarker();
      this.pingT += dt;
    }
    for (const e of this.entities) {
      if (e.view) e.view.update(dt);
    }
    this.effects.update(dt);
    for (const e of [...this.entities]) {
      if (!e.dead) continue;
      e.removeT = (e.removeT || 0) + dt;
      const limit = e.kind === 'building' ? 3.4 : e.kind === 'resource' ? 0.1 : 2.3;
      if (e.removeT >= limit) this.removeEntity(e);
    }
  }

  resolveCollisions(dt) {
    const list = this.units;
    for (let i = 0; i < list.length; i++) {
      const a = list[i];
      if (a.dead) continue;
      for (let j = i + 1; j < list.length; j++) {
        const b = list[j];
        if (b.dead) continue;
        let dx = b.pos.x - a.pos.x;
        let dz = b.pos.z - a.pos.z;
        let d = Math.hypot(dx, dz);
        const min = (a.radius + b.radius) * 0.92;
        if (d >= min || d < 0.0001) continue;
        const push = (min - d) * 0.5;
        dx /= d; dz /= d;
        const ax = a.pos.x - dx * push;
        const az = a.pos.z - dz * push;
        const bx = b.pos.x + dx * push;
        const bz = b.pos.z + dz * push;
        if (!this.nav.isBlockedWorld(ax, az)) { a.pos.x = ax; a.pos.z = az; }
        if (!this.nav.isBlockedWorld(bx, bz)) { b.pos.x = bx; b.pos.z = bz; }
      }
    }
  }
}

import { unitDef } from './data.js';

function findEnemy(game, unit, radius) {
  let best = null;
  let bestD = radius;
  for (const e of game.entities) {
    if (e.dead || e.kind === 'resource' || e.team === unit.team || e.team < 0) continue;
    const d = Math.hypot(e.pos.x - unit.pos.x, e.pos.z - unit.pos.z) - e.radius * 0.5;
    if (d < bestD) { bestD = d; best = e; }
  }
  return best;
}

function inAttackRange(unit, target) {
  const d = Math.hypot(target.pos.x - unit.pos.x, target.pos.z - unit.pos.z);
  return d <= unit.range + target.radius + 0.25;
}

function tryAttack(game, unit, target) {
  if (!target || target.dead) return;
  unit.faceTo(target.pos.x, target.pos.z);
  unit.moving = false;
  if (!inAttackRange(unit, target)) return;
  if (unit.cooldown > 0) return;
  unit.cooldown = unit.attackSpeed;
  unit.attackAnim = 0.32;
  if (unit.projectile) {
    game.effects.projectile(unit, target, unit.projectile, unit.damage);
  } else {
    game.dealDamage(unit, target, unit.damage, 'physical');
  }
}

function chase(game, unit, target, dt) {
  unit.repath -= dt;
  const dist = Math.hypot(target.pos.x - unit.pos.x, target.pos.z - unit.pos.z);
  if (unit.repath <= 0 || unit.path.length === 0) {
    unit.repath = 0.65 + Math.random() * 0.35;
    const spot = game.targetApproach(unit, target);
    unit.path = [];
    unit.setPathTo(spot.x, spot.z);
  }
  unit.moveAlongPath(dt);
}

function handleIdle(game, unit, dt) {
  unit.moving = false;
  unit.working = false;
  if (unit.role === 'worker') return;
  unit.think -= dt;
  if (unit.think <= 0) {
    unit.think = 0.4 + Math.random() * 0.3;
    const target = findEnemy(game, unit, 8.2);
    if (target) {
      unit.state = 'attack';
      unit.target = target;
      unit.autoAcquired = true;
      unit.orderOrigin = { x: unit.pos.x, z: unit.pos.z };
      unit.repath = 0;
    }
  }
}

function handleAttack(game, unit, dt) {
  const target = unit.target;
  if (!target || target.dead) {
    unit.target = null;
    if (unit.attackMoveDest) {
      unit.state = 'attackMove';
      unit.repath = 0;
    } else {
      unit.state = 'idle';
    }
    return;
  }
  if (unit.autoAcquired && unit.orderOrigin) {
    const d = Math.hypot(unit.pos.x - unit.orderOrigin.x, unit.pos.z - unit.orderOrigin.z);
    if (d > 17) {
      unit.target = null;
      unit.state = 'idle';
      return;
    }
  }
  if (inAttackRange(unit, target)) {
    unit.moving = false;
    unit.path = [];
    tryAttack(game, unit, target);
  } else {
    chase(game, unit, target, dt);
  }
}

function handleAttackMove(game, unit, dt) {
  unit.think -= dt;
  if (unit.target && unit.target.dead) unit.target = null;
  if (!unit.target && unit.think <= 0) {
    unit.think = 0.45;
    const target = findEnemy(game, unit, 9.2);
    if (target) {
      unit.target = target;
      unit.autoAcquired = false;
      unit.repath = 0;
    }
  }
  if (unit.target) {
    handleAttack(game, unit, dt);
    return;
  }
  const dest = unit.attackMoveDest;
  if (!dest) { unit.state = 'idle'; return; }
  if (unit.path.length === 0) {
    const d = Math.hypot(unit.pos.x - dest.x, unit.pos.z - dest.z);
    if (d < 2.4) {
      unit.state = 'idle';
      unit.attackMoveDest = null;
      unit.moving = false;
      const target = findEnemy(game, unit, 9.5);
      if (target) {
        unit.state = 'attack';
        unit.target = target;
        unit.autoAcquired = true;
        unit.orderOrigin = { x: unit.pos.x, z: unit.pos.z };
      }
      return;
    }
    unit.setPathTo(dest.x, dest.z);
  }
  unit.moveAlongPath(dt);
}

function handleMove(unit, dt) {
  if (unit.path.length === 0) {
    unit.state = 'idle';
    unit.moving = false;
    return;
  }
  unit.moveAlongPath(dt);
}

function dropCarry(game, unit) {
  const team = game.teams[unit.team];
  if (!unit.carry) return;
  if (unit.carryType === 'gold') {
    team.gold += unit.carry;
    team.stats.goldGathered += unit.carry;
    game.floatText({ x: unit.pos.x, z: unit.pos.z, y: 2.1 }, `+${unit.carry}`, '#ffd166');
  } else {
    team.lumber += unit.carry;
    team.stats.lumberGathered += unit.carry;
    game.floatText({ x: unit.pos.x, z: unit.pos.z, y: 2.1 }, `+${unit.carry}`, '#b6e07a');
  }
  unit.carry = 0;
  unit.carryType = null;
}

function handleGather(game, unit, dt) {
  if (unit.state === 'toResource') {
    let node = unit.gatherNode;
    if (!node || node.dead || node.amount <= 0) {
      node = game.findNearestResource(game.teams[unit.team], unit.gatherType || 'gold', unit.pos.x, unit.pos.z);
      if (!node) { unit.state = 'idle'; return; }
      unit.gatherNode = node;
      unit.gatherType = node.resourceType;
      const spot = unit.gatherSpot(node);
      unit.dest = spot;
      unit.setPathTo(spot.x, spot.z);
      return;
    }
    const d = unit.distanceToEntity(node);
    if (d <= node.radius + 1.55) {
      unit.state = 'gathering';
      unit.workT = 0;
      unit.moving = false;
      unit.working = true;
      unit.path = [];
      return;
    }
    if (unit.moveAlongPath(dt) || unit.path.length === 0) {
      const spot = unit.gatherSpot(node);
      unit.setPathTo(spot.x, spot.z);
    }
    return;
  }
  if (unit.state === 'gathering') {
    const node = unit.gatherNode;
    unit.moving = false;
    unit.working = true;
    if (!node || node.dead || node.amount <= 0) {
      node && game.exhaustResource(node);
      unit.gatherNode = null;
      unit.state = 'idle';
      return;
    }
    unit.faceTo(node.pos.x, node.pos.z);
    unit.workT = (unit.workT || 0) + dt;
    unit.gatherFx = (unit.gatherFx || 0) + dt;
    if (unit.gatherFx > 0.55) {
      unit.gatherFx = 0;
      game.effects.dust(node.pos.x, node.pos.z, node.resourceType === 'gold' ? 0xffd166 : 0x9c6d3e, 2, 0.7);
    }
    if (unit.workT >= (node.resourceType === 'gold' ? 2.1 : 2.35)) {
      unit.workT = 0;
      const take = Math.min(12, node.amount);
      node.amount -= take;
      unit.carry = take;
      unit.carryType = node.resourceType;
      if (node.amount <= 0) game.exhaustResource(node);
      const hall = game.findNearestDropoff(game.teams[unit.team], unit.pos.x, unit.pos.z);
      if (!hall) {
        unit.state = 'idle';
        unit.working = false;
        return;
      }
      unit.state = 'toDropoff';
      unit.dropoff = hall;
      unit.working = false;
      const spot = unit.dropoffSpot(hall);
      unit.dest = spot;
      unit.setPathTo(spot.x, spot.z);
    }
    return;
  }
  if (unit.state === 'toDropoff') {
    let hall = unit.dropoff;
    if (!hall || hall.dead) {
      hall = game.findNearestDropoff(game.teams[unit.team], unit.pos.x, unit.pos.z);
      if (!hall) { unit.state = 'idle'; return; }
      unit.dropoff = hall;
      const spot = unit.dropoffSpot(hall);
      unit.dest = spot;
      unit.setPathTo(spot.x, spot.z);
    }
    const d = unit.distanceToEntity(hall);
    if (d <= hall.size * 0.9 + 2.1) {
      dropCarry(game, unit);
      game.effects.ring(hall.pos.x, hall.pos.z, 0xffe19a, hall.size * 0.9, 0.4, 0.5);
      unit.state = 'toResource';
      let node = unit.gatherNode;
      if (!node || node.dead || node.amount <= 0) {
        node = game.findNearestResource(game.teams[unit.team], unit.gatherType || 'gold', unit.pos.x, unit.pos.z);
        unit.gatherNode = node;
      }
      if (node) {
        unit.gatherType = node.resourceType;
        const spot = unit.gatherSpot(node);
        unit.dest = spot;
        unit.setPathTo(spot.x, spot.z);
      } else {
        unit.state = 'idle';
      }
      return;
    }
    if (unit.moveAlongPath(dt) || unit.path.length === 0) {
      const spot = unit.dropoffSpot(hall);
      unit.setPathTo(spot.x, spot.z);
    }
    return;
  }
}

function handleBuild(game, unit, dt) {
  const b = unit.buildTarget;
  if (!b || b.dead || b.completed) {
    unit.buildTarget = null;
    unit.state = 'idle';
    unit.working = false;
    return;
  }
  const d = unit.distanceToEntity(b);
  if (d > b.size * 0.9 + 2.0) {
    unit.working = false;
    if (unit.moveAlongPath(dt) || unit.path.length === 0) {
      const spot = unit.dropoffSpot(b);
      unit.setPathTo(spot.x, spot.z);
    }
  } else {
    unit.moving = false;
    unit.working = true;
    unit.path = [];
    unit.faceTo(b.pos.x, b.pos.z);
    unit.buildFx = (unit.buildFx || 0) + dt;
    if (unit.buildFx > 0.8) {
      unit.buildFx = 0;
      game.effects.dust(b.pos.x + (Math.random() - 0.5) * b.size, b.pos.z + (Math.random() - 0.5) * b.size, 0xcabf9e, 2, 0.7);
    }
  }
}

function healAllies(game, unit, dt) {
  if (!unit.heal) return;
  unit.healTimer -= dt;
  if (unit.healTimer > 0) return;
  let best = null;
  let bestRatio = 0.86;
  for (const e of game.units) {
    if (e.dead || e.team !== unit.team) continue;
    const d = unit.distanceToEntity(e);
    if (d > unit.healRange) continue;
    const ratio = e.hp / e.maxHp;
    if (ratio < bestRatio) { bestRatio = ratio; best = e; }
  }
  if (best) {
    best.hp = Math.min(best.maxHp, best.hp + unit.heal);
    unit.healTimer = unit.healCooldown;
    game.effects.heal(best);
  } else {
    unit.healTimer = 0.8;
  }
}

export function updateUnit(game, unit, dt) {
  if (unit.dead) return;
  unit.cooldown = Math.max(0, unit.cooldown - dt);
  unit.attackAnim = Math.max(0, unit.attackAnim - dt);
  healAllies(game, unit, dt);

  switch (unit.state) {
    case 'move': handleMove(unit, dt); break;
    case 'attack': handleAttack(game, unit, dt); break;
    case 'attackMove': handleAttackMove(game, unit, dt); break;
    case 'toResource':
    case 'gathering':
    case 'toDropoff': handleGather(game, unit, dt); break;
    case 'build': handleBuild(game, unit, dt); break;
    default: handleIdle(game, unit, dt); break;
  }
}

export function updateBuilding(game, building, dt) {
  if (building.dead) return;
  if (building.underAttackT > 0) building.underAttackT -= dt;
  if (building.construction < 1) {
    let builders = 0;
    for (const u of game.units) {
      if (u.dead || u.team !== building.team || u.role !== 'worker' || u.buildTarget !== building) continue;
      if (u.distanceToEntity(building) <= building.size * 0.9 + 2.3) builders++;
    }
    building.builderCount = builders;
    if (builders > 0) {
      const rate = (1 / building.def.build) * (1 + (builders - 1) * 0.55);
      building.construction = Math.min(1, building.construction + rate * dt);
      building.hp = Math.max(building.hp, building.maxHp * (0.18 + 0.82 * building.construction));
      if (building.construction >= 1) game.completeBuilding(building);
    }
    return;
  }
  if (building.def.trains && building.queue.length) {
    const q = building.queue[0];
    q.time = Math.min(q.total, q.time + dt);
    if (q.time >= q.total) {
      game.spawnFromBuilding(building);
    }
  }
  if (building.def.attack) {
    building.think -= dt;
    if (building.think <= 0) {
      building.think = 0.3;
      let best = null;
      let bestD = building.def.attack.range + 1;
      for (const e of game.entities) {
        if (e.dead || e.kind === 'resource' || e.team === building.team || e.team < 0) continue;
        const d = Math.hypot(e.pos.x - building.pos.x, e.pos.z - building.pos.z) - e.radius * 0.4;
        if (d < bestD) { bestD = d; best = e; }
      }
      building.target = best;
    }
    if (building.target && building.target.dead) building.target = null;
    if (building.target) {
      const t = building.target;
      building.faceTo(t.pos.x, t.pos.z);
      building.cooldown = Math.max(0, building.cooldown - dt);
      if (building.cooldown <= 0) {
        const dist = Math.hypot(t.pos.x - building.pos.x, t.pos.z - building.pos.z);
        if (dist <= building.def.attack.range + t.radius) {
          building.cooldown = building.def.attack.cooldown;
          if (building.def.attack.projectile) game.effects.projectile(building, t, building.def.attack.projectile, building.def.attack.damage);
          else game.dealDamage(building, t, building.def.attack.damage);
        }
      }
    }
  }
}

export function updateFountain(game, dt) {
  const fountain = game.resources.find(r => r.resourceType === 'fountain');
  if (!fountain) return;
  game.fountainFx = (game.fountainFx || 0) + dt;
  const doFx = game.fountainFx > 1.4;
  if (doFx) game.fountainFx = 0;
  for (const u of game.units) {
    if (u.dead) continue;
    const d = Math.hypot(u.pos.x - fountain.pos.x, u.pos.z - fountain.pos.z);
    if (d <= fountain.radius + 3.0 && u.hp < u.maxHp) {
      u.hp = Math.min(u.maxHp, u.hp + 5.5 * dt);
      if (doFx) game.effects.heal(u, 0x8ff5e0);
    }
  }
}

import { MAP } from './map.js';
import { unitDef } from './data.js';

// A compact macro-oriented AI: it keeps workers busy, maintains supply,
// builds a composition, defends its hall and sends growing attack waves.
export class AIController {
  constructor(game, teamId, difficulty) {
    this.game = game;
    this.teamId = teamId;
    this.diff = difficulty;
    this.timer = 1.5;
    this.lastAttack = -20;
    this.wave = 0;
    this.attackRally = null;
    this.trigger = difficulty.aiArmy;
    this.baseUnderAttack = 0;
    this.notifyDefense = 0;
  }

  update(dt) {
    if (this.game.over) return;
    this.timer -= dt;
    if (this.timer > 0) return;
    this.timer = this.diff.aiThink;
    try { this.think(); } catch (err) { console.error('AI error', err); }
  }

  think() {
    const game = this.game;
    const team = game.teams[this.teamId];
    const hall = game.getHall(this.teamId);
    if (!hall) return;
    const workers = game.unitsOf(this.teamId).filter(u => u.role === 'worker');
    const army = game.unitsOf(this.teamId).filter(u => u.role !== 'worker');
    const buildings = game.buildingsOf(this.teamId);

    this.defend(hall, army);

    this.manageWorkers(hall, workers);
    this.manageBuildings(hall, buildings, workers);
    this.manageArmy(buildings, team);
    this.manageAttack(hall, army);
  }

  defend(hall, army) {
    const game = this.game;
    const threats = game.enemiesNear(this.teamId, hall.pos.x, hall.pos.z, 26);
    if (!threats.length) {
      this.baseUnderAttack = 0;
      return;
    }
    this.baseUnderAttack = game.time;
    if (game.time - this.notifyDefense > 18) {
      this.notifyDefense = game.time;
      game.notify(`База ${game.teams[this.teamId].isAI ? 'врага' : ''} под атакой!`, 'danger');
    }
    if (!army.length) return;
    let nearest = threats[0];
    let best = Infinity;
    for (const t of threats) {
      const d = Math.hypot(t.pos.x - hall.pos.x, t.pos.z - hall.pos.z);
      if (d < best) { best = d; nearest = t; }
    }
    // Only re-issue orders occasionally, so defending units can finish fights.
    if (!this.defendTarget || this.defendTarget.dead || this.defendTarget !== nearest) {
      this.defendTarget = nearest;
      game.orderAttack(army, nearest);
    }
  }

  manageWorkers(hall, workers) {
    const game = this.game;
    const team = game.teams[this.teamId];
    const queuedWorkers = hall.queue.filter(q => q.role === 'worker').length;
    if (workers.length + queuedWorkers < this.diff.aiWorkers) {
      const needSupply = team.supplyUsed + game.totalQueuedSupply(this.teamId) + 1 > team.supplyCap;
      if (!needSupply) game.enqueueUnit(hall, 'worker', true);
    }
    const golders = workers.filter(w =>
      w.gatherType === 'gold' && (w.state === 'toResource' || w.state === 'gathering' || w.state === 'toDropoff')).length;
    const lumberers = workers.filter(w =>
      w.gatherType === 'lumber' && (w.state === 'toResource' || w.state === 'gathering' || w.state === 'toDropoff')).length;
    const targetLumber = Math.max(2, Math.round(workers.length * 0.42));
    const targetGold = Math.max(2, workers.length - targetLumber);
    const free = workers.filter(w => w.state === 'idle' || (!w.gatherType && w.state !== 'build'));
    for (const w of free) {
      let type = 'gold';
      if (lumberers < targetLumber) type = 'lumber';
      else if (golders >= targetGold) type = 'lumber';
      const node = game.findNearestResource(team, type, w.pos.x, w.pos.z)
        || game.findNearestResource(team, type === 'gold' ? 'lumber' : 'gold', w.pos.x, w.pos.z);
      if (node) game.assignGather(w, node);
    }
  }

  manageBuildings(hall, buildings, workers) {
    const game = this.game;
    const team = game.teams[this.teamId];
    const count = (role) => buildings.filter(b => b.role === role).length;
    const constructing = buildings.filter(b => !b.completed);
    const farms = count('farm');
    const barracks = count('barracks');
    const special = count('special');
    const towers = count('tower');
    const desiredFarms = Math.min(7, 2 + Math.floor(game.time / 150));
    const supplyGap = team.supplyCap - team.supplyUsed - game.totalQueuedSupply(this.teamId);

    let role = null;
    if (barracks === 0) role = 'barracks';
    else if (supplyGap <= 7 && farms < desiredFarms) role = 'farm';
    else if (farms < 1) role = 'farm';
    else if (special === 0 && game.time > 105) role = 'special';
    else if (towers < 1 && game.time > 130) role = 'tower';
    else if (farms < desiredFarms && supplyGap <= 14) role = 'farm';
    else if (towers < 2 && game.time > 260 && count('barracks') > 0) role = 'tower';
    else if (farms < desiredFarms - 1 && game.time > 320) role = 'farm';
    if (!role) return;
    if (constructing.length >= (role === 'farm' ? 2 : 1)) return;

    const def = team.race ? requireBuilding(team.race, role) : null;
    if (!def) return;
    if (!game.canAfford(team, def.cost)) return;
    const spot = game.findBuildSpot(team, def.size, 6.2, 14.5);
    if (!spot) return;
    // Keep one spare worker near the hall for construction.
    const builder = workers
      .filter(w => w.state !== 'build')
      .sort((a, b) => {
        const da = Math.hypot(a.pos.x - hall.pos.x, a.pos.z - hall.pos.z);
        const db = Math.hypot(b.pos.x - hall.pos.x, b.pos.z - hall.pos.z);
        return da - db;
      })[0];
    if (!builder) return;
    game.startBuilding(team, role, spot.x, spot.z, builder);
  }

  manageArmy(buildings, team) {
    const game = this.game;
    const prod = buildings.filter(b => b.completed && b.def.trains && b.def.trains.some(r => r !== 'worker'));
    for (const b of prod) {
      if (b.queue.length >= 2) continue;
      let role;
      if (b.role === 'special') {
        role = (this.wave + b.queue.length) % 2 === 0 ? 'heavy' : 'caster';
      } else {
        const r = Math.random();
        role = r < 0.58 ? 'melee' : 'ranged';
      }
      const def = unitDef(team.race, role);
      if (team.gold < (def.cost.gold || 0) + 25) continue;
      if (team.lumber < (def.cost.lumber || 0)) continue;
      if (team.supplyUsed + game.totalQueuedSupply(this.teamId) + def.supply > team.supplyCap) continue;
      game.enqueueUnit(b, role, true);
    }
  }

  manageAttack(hall, army) {
    const game = this.game;
    if (this.defendTarget && !this.defendTarget.dead && game.time - this.baseUnderAttack < 8) return;
    if (army.length < this.trigger) return;
    if (game.time - this.lastAttack < this.diff.aiAttackDelay) return;
    const playerHall = game.getHall(0);
    const target = playerHall || game.buildingsOf(0)[0];
    if (!target) return;
    const combat = army.filter(u => u.role !== 'worker');
    if (!combat.length) return;
    this.lastAttack = game.time;
    this.wave++;
    this.trigger = this.diff.aiArmy + Math.min(8, this.wave * 2);
    game.orderMove(combat, { x: target.pos.x, z: target.pos.z }, { attackMove: true });
    // New units gather at the front, then follow the wave.
    const p = { x: target.pos.x, z: target.pos.z };
    for (const b of game.buildingsOf(this.teamId)) {
      if (b.role === 'barracks' || b.role === 'special') {
        b.rally.set(p.x, p.z);
        b.rallyResource = null;
      }
    }
    game.notify(`${game.teams[this.teamId].race === 'orc' ? 'Орда' : game.teams[this.teamId].race === 'undead' ? 'Плеть' : 'Альянс'} начинает наступление!`, 'danger');
  }
}

function requireBuilding(race, role) {
  // Lazy import avoidance: data is already imported by the game, but importing
  // here keeps the AI self-contained.
  const mod = modCache;
  return mod[race]?.[role];
}

import { RACES } from './data.js';
const modCache = Object.fromEntries(Object.entries(RACES).map(([id, r]) => [id, r.buildings]));

