301:     if (!hall) return null;
302:     const rnd = Math.random() * Math.PI * 2;
303:     for (let r = minR; r <= maxR; r += 1.1) {
304:       for (let i = 0; i < 18; i++) {
305:         const a = rnd + (i / 18) * Math.PI * 2 + r * 0.15;
306:         const x = hall.pos.x + Math.cos(a) * r;
307:         const z = hall.pos.z + Math.sin(a) * r;
308:         if (Math.hypot(x, z) > MAP.playable - 3) continue;
309:         if (this.canPlaceAt(x, z, size)) return { x, z };
310:       }
311:     }
312:     return null;
313:   }
314: 
315:   // -------------------------------------------------------------------------
316:   // Unit production
317:   // -------------------------------------------------------------------------
318:   totalQueuedSupply(teamId) {
319:     let sum = 0;
320:     for (const b of this.buildings) {
321:       if (b.team !== teamId || b.dead) continue;
322:       for (const q of b.queue) sum += q.supply;
323:     }
324:     return sum;
325:   }
326: 
327:   enqueueUnit(building, role, silent = false) {
328:     if (!building || building.dead || building.construction < 1) return false;
329:     if (building.queue.length >= 5) {
330:       if (!silent) this.notify('Очередь обучения заполнена', 'warn', 2);
331:       return false;
332:     }
333:     const team = this.teams[building.team];
334:     const def = unitDef(team.race, role);
335:     if (!this.canAfford(team, def.cost)) {
336:       if (!silent) this.notify(`Не хватает ресурсов: ${this.costMissing(team, def.cost)}`, 'warn', 2);
337:       return false;
338:     }
339:     const reserved = team.supplyUsed + this.totalQueuedSupply(team.id) + def.supply;
340:     if (reserved > team.supplyCap) {
341:       if (!silent) this.notify('Нужно больше снабжения — постройте ферму', 'warn', 3);
342:       return false;
343:     }
344:     this.pay(team, def.cost);
345:     building.queue.push({ role, time: 0, total: def.train, cost: { ...def.cost }, supply: def.supply });
346:     if (!silent && !team.isAI) this.notify(`${def.name}: обучение начато`, 'info');
347:     return true;
348:   }
349: 
350:   cancelQueue(building, index) {
351:     if (index < 0 || index >= building.queue.length) return;
352:     const team = this.teams[building.team];
353:     const q = building.queue[index];
354:     this.refund(team, q.cost);
355:     building.queue.splice(index, 1);
356:     if (!team.isAI) this.notify('Обучение отменено, ресурсы возвращены', 'info');
357:   }
358: 
359:   spawnFromBuilding(building) {
360:     const team = this.teams[building.team];
361:     const q = building.queue[0];
362:     if (!q) return;
363:     const def = unitDef(team.race, q.role);
364:     if (team.supplyUsed + def.supply > team.supplyCap) {
365:       if (!team.isAI) this.notify('Нужно больше снабжения — постройте ферму', 'warn', 4);
366:       return;
367:     }
368:     const rally = building.rally;
369:     let dx = rally.x - building.pos.x;
370:     let dz = rally.y - building.pos.z;
371:     let len = Math.hypot(dx, dz);
372:     if (len < 0.1) { dx = 0; dz = 1; len = 1; }
373:     const spawnR = building.size * 0.95 + 1.15;
374:     const baseAngle = Math.atan2(dz, dx) + (Math.random() - 0.5) * 0.8;
375:     let x = building.pos.x + Math.cos(baseAngle) * spawnR;
376:     let z = building.pos.z + Math.sin(baseAngle) * spawnR;
377:     if (this.nav.isBlockedWorld(x, z)) {
378:       const p = this.nav.nearestFreePoint(x, z, 16);
379:       x = p.x; z = p.z;
380:     }
381:     const unit = this.spawnUnit(team, q.role, x, z, { facing: Math.atan2(dx, dz) });
382:     unit.homePos = { x, z };
383:     building.queue.shift();
384:     team.stats.trained++;
385:     team.supplyUsed += def.supply;
386:     this.recalcSupply();
387:     if (unit.role === 'worker' && building.rallyResource && !building.rallyResource.dead && building.rallyResource.amount > 0) {
388:       this.assignGather(unit, building.rallyResource);
389:     } else if (Math.hypot(rally.x - unit.pos.x, rally.y - unit.pos.z) > 2) {
390:       this.orderMove([unit], { x: rally.x, z: rally.y }, { formation: false });
391:     }
392:     this.effects.dust(x, z, 0xd8c9a5, 5, 0.7);
393:     this.effects.ring(x, z, team.color3d, 1.4, 0.6, 0.55);
394:     if (!team.isAI) this.notify(`${def.name} готов к бою`, 'success');
395:   }
396: 
397:   completeBuilding(b) {
398:     if (!b || b.dead || b.completed) return;
399:     b.construction = 1;
400:     b.completed = true;
401:     b.hp = b.maxHp;
402:     this.teams[b.team].stats.buildingsBuilt++;
403:     this.recalcSupply();
404:     this.effects.buildComplete(b.pos.x, b.pos.z, this.teams[b.team].color3d);
405:     if (!this.teams[b.team].isAI) {
406:       this.notify(`${b.def.name} готова!`, 'success');
407:     }
408:     for (const u of this.units) {
409:       if (u.buildTarget === b) {
410:         u.buildTarget = null;
411:         u.state = 'idle';
412:         u.working = false;
413:       }
414:     }
415:   }
416: 
417:   // -------------------------------------------------------------------------
418:   // Orders
419:   // -------------------------------------------------------------------------
420:   ownUnitsSelected() {    return this.selection.filter(e => !e.dead && e.kind === 'unit' && e.team === 0);
421:   }
422: 
423:   orderMove(units, point, opts = {}) {
424:     if (!units.length) return;
425:     const formation = opts.formation !== false;
426:     const spots = formation ? this.formationSpots(units, point) : units.map(() => ({ x: point.x, z: point.z }));
427:     units.forEach((u, i) => {
428:       if (u.dead) return;
429:       u.clearOrder();
430:       u.state = opts.attackMove ? 'attackMove' : 'move';
431:       const free = this.nav.isBlockedWorld(spots[i].x, spots[i].z) ? this.nav.nearestFreePoint(spots[i].x, spots[i].z, 20) : spots[i];
432:       u.dest = { x: free.x, z: free.z };
433:       u.attackMoveDest = opts.attackMove ? { x: point.x, z: point.z } : null;
434:       u.orderOrigin = { x: u.pos.x, z: u.pos.z };
435:       u.setPathTo(free.x, free.z);
436:     });
437:     this.effects.ring(point.x, point.z, opts.attackMove ? 0xff8a5c : 0x8fc2ff, 1.5, 0.55, 0.7);
438:   }
439: 
440:   formationSpots(units, point) {
441:     if (units.length === 1) return [{ x: point.x, z: point.z }];
442:     const n = units.length;
443:     const cols = Math.ceil(Math.sqrt(n));
444:     const spacing = 1.7;
445:     const rows = Math.ceil(n / cols);
446:     // Face the formation towards its movement direction.
447:     let cx = 0, cz = 0;
448:     for (const u of units) { cx += u.pos.x; cz += u.pos.z; }
449:     cx /= n; cz /= n;
450:     const ang = Math.atan2(point.x - cx, point.z - cz);
451:     const cos = Math.cos(ang), sin = Math.sin(ang);
452:     // Rows are perpendicular to the direction of travel.
453:     const spots = [];
454:     for (let i = 0; i < n; i++) {
455:       const row = Math.floor(i / cols);
456:       const col = i % cols;
457:       const lateral = (col - (cols - 1) / 2) * spacing;
458:       const forward = -row * spacing;
459:       spots.push({
460:         x: point.x + lateral * cos + forward * sin,
461:         z: point.z - lateral * sin + forward * cos,
462:       });
463:     }
464:     return spots;
465:   }
466: 
467:   orderAttack(units, target) {
468:     if (!units.length || !target || target.dead) return;
469:     for (const u of units) {
470:       if (u.dead) continue;
471:       u.clearOrder();
472:       u.state = 'attack';
473:       u.target = target;
474:       u.orderOrigin = { x: u.pos.x, z: u.pos.z };
475:       u.repath = 0;
476:       const spot = this.targetApproach(u, target);
477:       u.setPathTo(spot.x, spot.z);
478:     }
479:     this.effects.ring(target.pos.x, target.pos.z, 0xff5a4a, Math.max(1.5, target.radius), 0.6, 0.8);
480:   }
481: 
482:   targetApproach(u, target) {
483:     const r = target.radius + Math.max(0.5, u.def.range * 0.65);
484:     const a = Math.atan2(u.pos.z - target.pos.z, u.pos.x - target.pos.x);
485:     let x = target.pos.x + Math.cos(a) * r;
486:     let z = target.pos.z + Math.sin(a) * r;
487:     if (this.nav.isBlockedWorld(x, z)) {
488:       const p = this.nav.nearestFreePoint(x, z, 16);
489:       x = p.x; z = p.z;
490:     }
491:     return { x, z };
492:   }
493: 
494:   assignGather(worker, node) {
495:     if (!worker || worker.dead || worker.role !== 'worker' || !node || node.dead || node.amount <= 0) return;
496:     worker.clearOrder();
497:     worker.state = 'toResource';
498:     worker.gatherNode = node;
499:     worker.gatherType = node.resourceType;
500:     worker.orderOrigin = { x: worker.pos.x, z: worker.pos.z };
501:     const spot = worker.gatherSpot(node);
502:     worker.dest = spot;
503:     worker.setPathTo(spot.x, spot.z);
504:     worker.faceTo(node.pos.x, node.pos.z);
505:   }
506: 
507:   orderGather(workers, node) {
508:     const list = workers.filter(w => w.role === 'worker' && !w.dead);
509:     if (!list.length) {
510:       this.notify('Для добычи нужен рабочий', 'warn', 2);
511:       return;
512:     }
513:     list.forEach(w => this.assignGather(w, node));
514:     this.effects.ring(node.pos.x, node.pos.z, node.resourceType === 'gold' ? 0xffd166 : 0x8fd06a, 1.8, 0.55, 0.7);
515:   }
516: 
517:   orderBuild(workers, building) {
518:     if (!building || building.dead) return;
519:     for (const w of workers) {
520:       if (w.dead || w.role !== 'worker') continue;
521:       w.clearOrder();
522:       w.state = 'build';
523:       w.buildTarget = building;
524:       w.orderOrigin = { x: w.pos.x, z: w.pos.z };
525:       const spot = w.dropoffSpot(building);
526:       w.dest = spot;
527:       w.setPathTo(spot.x, spot.z);
528:     }
529:   }
530: 
531:   orderStop(units) {
532:     for (const u of units) {
533:       if (u.dead) continue;
534:       u.clearOrder();
535:       u.state = 'idle';
536:     }
537:     this.notify('Отряд остановлен', 'info', 1);
538:   }
539: 
540:   setRally(building, point, node = null) {
541:     building.rally.set(point.x, point.z);
542:     building.rallyResource = node;
543:     if (node) {
544:       this.notify(`Точка сбора: ${node.resourceType === 'gold' ? 'золотая шахта' : 'лес'}`, 'info');
545:     } else {
546:       this.notify('Точка сбора установлена', 'info');
547:     }
548:     this.updateRallyMarker();
549:   }
550: 
551:   findNearestResource(team, type, x, z) {
552:     let best = null;
553:     let bestD = Infinity;
554:     for (const r of this.resources) {
555:       if (r.dead || r.amount <= 0 || r.resourceType !== type) continue;
556:       const d = Math.hypot(r.pos.x - x, r.pos.z - z);
557:       if (d < bestD) { bestD = d; best = r; }
558:     }
559:     return best;
560:   }
561: 
562:   findNearestDropoff(team, x, z) {
563:     let best = null;
564:     let bestD = Infinity;
565:     for (const b of this.buildings) {
566:       if (b.dead || b.team !== team.id || !b.completed || !b.def.dropoff) continue;
567:       const d = Math.hypot(b.pos.x - x, b.pos.z - z);
568:       if (d < bestD) { bestD = d; best = b; }
569:     }
570:     return best;
571:   }
572: 
573:   clearOrderForTarget(entity) {
574:     for (const u of this.units) {
575:       if (u.dead) continue;
576:       if (u.target === entity) { u.target = null; if (u.state === 'attack') u.state = u.attackMoveDest ? 'attackMove' : 'idle'; }
577:       if (u.gatherNode === entity) { u.gatherNode = null; u.state = 'idle'; u.path = []; }
578:       if (u.buildTarget === entity) { u.buildTarget = null; u.state = 'idle'; u.path = []; }
579:     }
580:   }
581: 
582:   // -------------------------------------------------------------------------
583:   // Selection
584:   // -------------------------------------------------------------------------
585:   setSelection(list) {
586:     const filtered = [];
587:     for (const e of list) {
588:       if (!e || e.dead) continue;
589:       if (!filtered.includes(e)) filtered.push(e);
590:     }
591:     for (const e of this.selection) {
592:       e.selected = false;
593:       e.view?.setSelected(false);
594:     }
595:     this.selection = filtered;
596:     for (const e of filtered) {
597:       e.selected = true;
598:       e.view?.setSelected(true);
599:     }
600:     this.updateRallyMarker();
601:     if (this.onSelectionChanged) this.onSelectionChanged(filtered);
602:   }
603: 
604:   deselect() {
605:     this.setSelection([]);
606:   }
607: 
608:   primary() {
609:     return this.selection[0] || null;
610:   }
611: 
612:   updateRallyMarker() {
613:     if (!this.rallyMarker) return;
614:     const b = this.selection.length === 1 ? this.selection[0] : null;
615:     if (!b || b.kind !== 'building' || b.team !== 0 || b.dead) {
616:       this.rallyMarker.visible = false;
617:       return;
618:     }
619:     this.rallyMarker.visible = true;
620:     this.rallyMarker.position.set(b.rally.x, 0, b.rally.y);
621:     this.rallyFlag.material.color.setHex(this.teams[0].color3d);
622:     this.rallyMarker.children[2].material.color.setHex(this.teams[0].color3d);
623:     const s = 0.9 + Math.sin(this.time * 3) * 0.06;
624:     this.rallyFlag.scale.set(s, 1, 1);
625:     this.rallyFlag.rotation.y = Math.sin(this.time * 2.4) * 0.3;
626:   }
627: 
628:   // -------------------------------------------------------------------------
629:   // Damage and death
630:   // -------------------------------------------------------------------------
631:   dealDamage(source, target, amount, type = 'physical') {
632:     if (!target || target.dead || target.kind === 'resource') return 0;
633:     const magic = type === 'holy' || type === 'shadow' || type === 'lightning';
634:     const armor = target.armor || 0;
635:     let dmg = amount - armor * (magic ? 0.35 : 0.7);
636:     dmg = Math.max(1, dmg);
637:     target.hp -= dmg;
638:     target.lastAttacker = source;
639:     if (target.kind === 'building') target.underAttackT = 4;
640:     this.effects.hit(target, magic ? 0x9fffe0 : 0xffd18a, magic ? 1.1 : 0.9);
641:     if (target.kind === 'unit' && target.role !== 'worker' && target.state === 'idle' && source && source.team !== target.team) {
642:       if (target.distanceToEntity(source) < 14) {
643:         target.state = 'attack';
644:         target.target = source;
645:         target.orderOrigin = { x: target.pos.x, z: target.pos.z };
646:       }
647:     }
648:     if (source && source.team !== undefined && source.team >= 0) {
649:       const st = this.teams[source.team]?.stats;
650:       if (st) st.damage = (st.damage || 0) + dmg;
651:     }
652:     if (target.hp <= 0) this.killEntity(target, source);
653:     return dmg;
654:   }
655: 
656:   killEntity(e, source = null) {
657:     if (e.dead) return;
658:     e.dead = true;
659:     e.hp = 0;
660:     e.removeT = 0;
661:     if (e.kind === 'unit') {
662:       this.effects.dust(e.pos.x, e.pos.z, 0xb9a884, 7, 0.5);
663:       this.effects.burst(e.pos.x, 1.0, e.pos.z, e.team === 0 ? 0x8fb9ff : 0xff8a7a, 6, 1.4);
664:       this.teams[e.team].stats.lost++;
665:       if (source && source.team !== undefined && source.team >= 0) this.teams[source.team].stats.killed++;
666:       if (e.selected) this.setSelection(this.selection.filter(s => s !== e));
667:       this.recalcSupply();
668:     } else if (e.kind === 'building') {
669:       this.effects.dust(e.pos.x, e.pos.z, 0xcabf9e, 20, e.size * 0.8);
670:       this.effects.burst(e.pos.x, 1.4, e.pos.z, e.team === 0 ? 0x8fb9ff : 0xff8a7a, 18, 2.6);
671:       this.nav.removeRect(e.pos.x, e.pos.z, e.def.size * 0.86, e.def.size * 0.86);
672:       this.clearOrderForTarget(e);
673:       if (e.selected) this.setSelection(this.selection.filter(s => s !== e));
674:       if (e.team >= 0) {
675:         this.teams[e.team].stats.lost++;
676:         if (source && source.team !== undefined && source.team >= 0) this.teams[source.team].stats.killed++;
677:       }
678:       this.recalcSupply();
679:       const teamName = RACES[e.race].name;
680:       if (!this.teams[e.team]?.isAI) this.notify(`${e.def.name} уничтожен!`, 'danger');
681:       else this.notify(`Вражеское здание уничтожено: ${e.def.name}`, 'success');
682:       this.checkVictory(e.team);
683:     } else if (e.kind === 'resource') {
684:       this.nav.removeCircle(e.pos.x, e.pos.z, e.navRadius);
685:       this.effects.dust(e.pos.x, e.pos.z, 0x8a6b3a, 10, 1.2);
686:     }
687:   }
688: 
689:   removeEntity(e) {
690:     const vi = this.selection.indexOf(e);
691:     if (vi >= 0) {
692:       this.selection.splice(vi, 1);
693:       if (this.onSelectionChanged) this.onSelectionChanged(this.selection);
694:     }
695:     e.view?.remove();
696:     const ei = this.entities.indexOf(e);
697:     if (ei >= 0) this.entities.splice(ei, 1);
698:     const ui = this.units.indexOf(e);
699:     if (ui >= 0) this.units.splice(ui, 1);
700:     const bi = this.buildings.indexOf(e);
701:     if (bi >= 0) this.buildings.splice(bi, 1);
702:     const ri = this.resources.indexOf(e);
703:     if (ri >= 0) this.resources.splice(ri, 1);
704:   }
705: 
706:   exhaustResource(node) {
707:     if (node.resourceType === 'lumber') {
708:       this.killEntity(node, null);
709:       node.removeT = 99;
710:       this.removeEntity(node);
711:     } else {
712:       node.exhausted = true;
713:       node.amount = 0;
714:       if (node.view) node.view.root.traverse((o) => {
715:         if (o.isMesh && o.material && o.material.emissive) o.material.emissiveIntensity = 0;
716:       });
717:     }
718:   }
719: 
720:   checkVictory(lostTeam) {
721:     if (this.over) return;
722:     const halls = this.buildings.filter(b => b.team === lostTeam && b.role === 'hall' && !b.dead);
723:     if (halls.length === 0) {
724:       this.teams[lostTeam].alive = false;
725:       this.endGame(this.otherTeam(lostTeam));
726:     }
727:   }
728: 
729:   endGame(winner) {
730:     if (this.over) return;
731:     this.over = true;
732:     this.winner = winner;
733:     this.effects.clear();
734:     if (this.onGameOver) this.onGameOver(winner, this.teams, this.time);
735:   }
736: 
737:   // -------------------------------------------------------------------------
738:   // Supply and helpers
739:   // -------------------------------------------------------------------------
740:   recalcSupply() {
741:     for (const team of this.teams) {
742:       let cap = 0;
743:       let used = 0;
744:       for (const b of this.buildings) {
745:         if (b.team === team.id && !b.dead && b.completed && b.def.supply) cap += b.def.supply;
746:       }
747:       for (const u of this.units) {
748:         if (u.team === team.id && !u.dead) used += u.supply;
749:       }
750:       team.supplyCap = Math.min(60, cap);
751:       team.supplyUsed = used;
752:     }
753:   }
754: 
755:   getHall(teamId) {
756:     return this.buildings.find(b => b.team === teamId && !b.dead && b.role === 'hall');
757:   }
758: 
759:   unitsOf(teamId) {
760:     return this.units.filter(u => u.team === teamId && !u.dead);
761:   }
762: 
763:   buildingsOf(teamId) {
764:     return this.buildings.filter(b => b.team === teamId && !b.dead);
765:   }
766: 
767:   enemiesNear(teamId, x, z, radius) {
768:     const out = [];
769:     for (const u of this.units) {
770:       if (u.dead || u.team === teamId) continue;
771:       if (Math.hypot(u.pos.x - x, u.pos.z - z) <= radius) out.push(u);
772:     }
773:     return out;
774:   }
775: 
776:   // -------------------------------------------------------------------------
777:   // Main loop
778:   // -------------------------------------------------------------------------
779:   update(dt) {
780:     dt = Math.min(dt, 0.05);
781:     this.time += dt;
782:     this.world.update(dt);
783:     if (!this.paused && !this.over) {
784:       for (const u of [...this.units]) if (!u.dead) updateUnit(this, u, dt);
785:       for (const b of [...this.buildings]) if (!b.dead) updateBuilding(this, b, dt);
786:       updateFountain(this, dt);
787:       this.ai.update(dt);
788:       this.resolveCollisions(dt);
789:       this.recalcT -= dt;
790:       if (this.recalcT <= 0) { this.recalcT = 0.4; this.recalcSupply(); }
791:       this.updateRallyMarker();
792:       this.pingT += dt;
793:     }
794:     for (const e of this.entities) {
795:       if (e.view) e.view.update(dt);
796:     }
797:     this.effects.update(dt);
798:     for (const e of [...this.entities]) {
799:       if (!e.dead) continue;
800:       e.removeT = (e.removeT || 0) + dt;
801:       const limit = e.kind === 'building' ? 3.4 : e.kind === 'resource' ? 0.1 : 2.3;
802:       if (e.removeT >= limit) this.removeEntity(e);
803:     }
804:   }
805: 
806:   resolveCollisions(dt) {
807:     const list = this.units;
808:     for (let i = 0; i < list.length; i++) {
809:       const a = list[i];
810:       if (a.dead) continue;
811:       for (let j = i + 1; j < list.length; j++) {
812:         const b = list[j];
813:         if (b.dead) continue;
814:         let dx = b.pos.x - a.pos.x;
815:         let dz = b.pos.z - a.pos.z;
816:         let d = Math.hypot(dx, dz);
817:         const min = (a.radius + b.radius) * 0.92;
818:         if (d >= min || d < 0.0001) continue;
819:         const push = (min - d) * 0.5;
820:         dx /= d; dz /= d;
821:         const ax = a.pos.x - dx * push;
