/* ==========================================================================
   Эпоха Тронов — interface style
   Dark-fantasy glass, aged gold and cold steel. No external assets or fonts.
   ========================================================================== */

@import url("./menu.css");
@import url("./hud.css");
@import url("./modals.css");

:root {
  --bg: #060a0f;
  --panel: rgba(9, 14, 20, 0.88);
  --panel-solid: #0c131b;
  --panel-2: rgba(15, 22, 31, 0.92);
  --line: rgba(224, 189, 118, 0.2);
  --line-strong: rgba(236, 199, 122, 0.46);
  --gold: #e5bb68;
  --gold-light: #f8dfa3;
  --gold-deep: #a67b36;
  --blue: #4c8dff;
  --blue-soft: #8fc2ff;
  --red: #ef5350;
  --red-soft: #ff8b80;
  --green: #8bd47d;
  --text: #e9e2d2;
  --text-soft: #c9c2b2;
  --muted: #8e9aa6;
  --shadow: 0 24px 70px rgba(0, 0, 0, 0.58);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --serif: "Palatino Linotype", "Book Antiqua", Georgia, "Times New Roman", serif;
}

* { box-sizing: border-box; }

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}

body {
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

button {
  appearance: none;
  border: 0;
  margin: 0;
  padding: 0;
  background: none;
  color: inherit;
  font: inherit;
  cursor: pointer;
}

button:focus-visible {
  outline: 2px solid var(--gold-light);
  outline-offset: 3px;
}

img,
svg { display: block; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 58% 44%, rgba(45, 72, 93, 0.34), transparent 58%),
    var(--bg);
}

#stage {
  position: absolute;
  inset: 0;
  z-index: 0;
}

#stage canvas,
.stage-canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
  touch-action: none;
}

.hidden { display: none !important; }

.ico {
  width: 1em;
  height: 1em;
  flex: 0 0 auto;
}

.crest {
  width: 100%;
  height: 100%;
  color: currentColor;
  filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.5));
}

/* Thin ornamental separators and shared shine effects. */
.gold-rule {
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--line-strong), transparent);
}

.glass {
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.035), transparent 38%),
    linear-gradient(180deg, rgba(14, 21, 29, 0.95), rgba(7, 11, 16, 0.93));
  border: 1px solid var(--line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.045), var(--shadow);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

/* Golden corner ticks used on the most important panels. */
.cornered { position: relative; }
.cornered::before,
.cornered::after {
  content: "";
  position: absolute;
  width: 16px;
  height: 16px;
  pointer-events: none;
  border-color: var(--gold);
  opacity: 0.62;
}
.cornered::before {
  top: -1px;
  left: -1px;
  border-top: 1px solid;
  border-left: 1px solid;
}
.cornered::after {
  right: -1px;
  bottom: -1px;
  border-right: 1px solid;
  border-bottom: 1px solid;
}

/* Scrollbars only in help/menu overflow areas. */
* {
  scrollbar-width: thin;
  scrollbar-color: rgba(229, 187, 104, 0.32) rgba(0, 0, 0, 0.18);
}
*::-webkit-scrollbar { width: 7px; height: 7px; }
*::-webkit-scrollbar-track { background: rgba(0, 0, 0, 0.18); }
*::-webkit-scrollbar-thumb {
  background: rgba(229, 187, 104, 0.3);
  border-radius: 6px;
}

::selection {
  background: rgba(229, 187, 104, 0.28);
  color: #fff;
}

@keyframes fade-up {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes soft-pulse {
  0%, 100% { opacity: 0.45; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.08); }
}

@keyframes sheen {
  0% { transform: translateX(-130%) skewX(-18deg); }
  100% { transform: translateX(260%) skewX(-18deg); }
}

@keyframes float-drift {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

@keyframes spin-slow {
  to { transform: rotate(360deg); }
}

/* ==========================================================================
   Main menu + loading screen
   ========================================================================== */

.menu {
  position: absolute;
  inset: 0;
  z-index: 20;
  overflow: hidden;
  animation: fade-in 0.55s ease both;
}

.menu-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(3, 6, 10, 0.97) 0%, rgba(3, 6, 10, 0.93) 32%, rgba(4, 8, 12, 0.64) 53%, rgba(4, 8, 12, 0.1) 77%, rgba(4, 8, 12, 0.32) 100%),
    radial-gradient(ellipse at 72% 42%, transparent 0%, transparent 35%, rgba(3, 6, 10, 0.25) 72%, rgba(3, 6, 10, 0.72) 100%),
    linear-gradient(0deg, rgba(3, 6, 10, 0.84) 0%, transparent 28%, transparent 82%, rgba(3, 6, 10, 0.38) 100%);
}

.menu-shade::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0.28;
  background-image:
    linear-gradient(rgba(229, 187, 104, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(229, 187, 104, 0.05) 1px, transparent 1px);
  background-size: 90px 90px;
  mask-image: radial-gradient(ellipse at 25% 48%, #000 0%, transparent 68%);
  -webkit-mask-image: radial-gradient(ellipse at 25% 48%, #000 0%, transparent 68%);
}

.menu-content {
  position: relative;
  z-index: 2;
  display: flex;
  width: 100%;
  height: 100%;
  padding: clamp(22px, 4.6vh, 54px) clamp(20px, 5vw, 78px) clamp(18px, 3.6vh, 38px);
  gap: 30px;
}

.menu-left {
  width: min(760px, 58vw);
  min-width: 0;
  max-height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: clamp(12px, 2vh, 22px);
  overflow-y: auto;
  padding-right: 4px;
}

/* --- Brand ---------------------------------------------------------------- */
.brand {
  position: relative;
  animation: fade-up 0.65s 0.08s ease both;
}

.brand-kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--gold);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  opacity: 0.86;
  margin-bottom: 8px;
}
.brand-kicker span {
  display: block;
  width: 34px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold));
}
.brand-kicker span:last-child {
  background: linear-gradient(90deg, var(--gold), transparent);
}

.brand h1 {
  position: relative;
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(56px, 7.6vw, 112px);
  font-weight: 400;
  line-height: 0.78;
  letter-spacing: 0.035em;
  text-shadow: 0 12px 40px rgba(0, 0, 0, 0.55);
}

.brand h1 span {
  display: block;
  font-size: 0.57em;
  font-weight: 400;
  letter-spacing: 0.34em;
  color: transparent;
  background: linear-gradient(180deg, #f7e2ac 6%, #d6ac5c 55%, #9b712f 100%);
  -webkit-background-clip: text;
  background-clip: text;
  padding-left: 0.08em;
}

.brand h1 strong {
  display: block;
  font-weight: 700;
  letter-spacing: 0.035em;
  color: #f2ecdc;
  text-shadow:
    0 2px 0 rgba(255, 255, 255, 0.08),
    0 16px 45px rgba(0, 0, 0, 0.65),
    0 0 80px rgba(229, 187, 104, 0.12);
}

.brand-sub {
  margin: 13px 0 0;
  font-family: var(--serif);
  font-style: italic;
  font-size: clamp(15px, 1.3vw, 19px);
  letter-spacing: 0.13em;
  color: var(--gold-light);
}

.brand-lore {
  max-width: 560px;
  margin: 11px 0 0;
  padding-left: 16px;
  border-left: 1px solid rgba(229, 187, 104, 0.36);
  color: var(--text-soft);
  font-size: clamp(11.5px, 0.9vw, 13.5px);
  line-height: 1.62;
}

/* --- Race selection ------------------------------------------------------- */
.race-section {
  animation: fade-up 0.65s 0.16s ease both;
}

.section-label {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  margin-bottom: 11px;
}
.section-label span {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border: 1px solid var(--line-strong);
  border-radius: 50%;
  color: var(--gold);
  font-family: var(--serif);
  font-size: 11px;
  letter-spacing: 0;
}
.section-label::after {
  content: "";
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, var(--line), transparent);
}
.section-label.small { margin-bottom: 8px; }

.race-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
}

.race-card {
  --race: var(--blue);
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  min-height: 146px;
  padding: 14px 14px 12px;
  text-align: left;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 8px;
  background:
    radial-gradient(circle at 12% 4%, color-mix(in srgb, var(--race) 12%, transparent), transparent 48%),
    linear-gradient(155deg, rgba(31, 42, 54, 0.7), rgba(8, 12, 17, 0.88));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05), 0 12px 30px rgba(0, 0, 0, 0.22);
  transition: transform 0.22s ease, border-color 0.22s ease, box-shadow 0.22s ease, background 0.22s ease;
  animation: fade-up 0.55s ease both;
}
.race-card[data-race="human"] { --race: #5a9bff; animation-delay: 0.2s; }
.race-card[data-race="orc"] { --race: #ee7a45; animation-delay: 0.26s; }
.race-card[data-race="undead"] { --race: #ab77ff; animation-delay: 0.32s; }

.race-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 12%;
  right: 12%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--race), transparent);
  opacity: 0.55;
  transition: opacity 0.22s ease;
}

.race-card:hover {
  transform: translateY(-4px);
  border-color: color-mix(in srgb, var(--race) 65%, transparent);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 18px 40px rgba(0, 0, 0, 0.42),
    0 0 32px -8px color-mix(in srgb, var(--race) 72%, transparent);
}

.race-card.active {
  border-color: color-mix(in srgb, var(--race) 78%, white 8%);
  background:
    radial-gradient(circle at 12% 4%, color-mix(in srgb, var(--race) 24%, transparent), transparent 54%),
    linear-gradient(155deg, rgba(35, 47, 61, 0.9), rgba(8, 12, 17, 0.94));
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.09),
    0 18px 46px rgba(0, 0, 0, 0.48),
    0 0 34px -9px var(--race);
}
.race-card.active::before { opacity: 1; }

.race-card:active { transform: translateY(-1px) scale(0.99); }

.race-card-shine {
  position: absolute;
  top: -60%;
  bottom: -60%;
  left: 0;
  width: 26%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.13), transparent);
  transform: translateX(-130%) skewX(-18deg);
  pointer-events: none;
  opacity: 0;
}
.race-card:hover .race-card-shine { opacity: 1; animation: sheen 0.85s ease; }

.race-emblem {
  position: relative;
  width: 38px;
  height: 38px;
  margin-bottom: 9px;
  color: var(--race);
  filter: drop-shadow(0 0 10px color-mix(in srgb, var(--race) 50%, transparent));
}
.race-emblem::after {
  content: "";
  position: absolute;
  inset: -5px;
  border: 1px solid color-mix(in srgb, var(--race) 35%, transparent);
  border-radius: 50%;
  opacity: 0.65;
}

.race-name {
  font-family: var(--serif);
  font-size: clamp(18px, 1.5vw, 22px);
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #f5efdf;
  line-height: 1.05;
}
.race-tag {
  position: absolute;
  top: 13px;
  right: 12px;
  color: color-mix(in srgb, var(--race) 75%, white);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  opacity: 0.8;
}
.race-desc {
  margin-top: 3px;
