  letter-spacing: 0.03em;
}
.race-bonus {
  margin-top: auto;
  padding-top: 8px;
  color: color-mix(in srgb, var(--race) 68%, white);
  font-size: 9.5px;
  line-height: 1.25;
  letter-spacing: 0.02em;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  width: 100%;
}

.race-detail {
  position: relative;
  margin-top: 9px;
  min-height: 82px;
  padding: 11px 14px 11px 16px;
  border: 1px solid rgba(229, 187, 104, 0.16);
  border-left: 2px solid rgba(229, 187, 104, 0.62);
  border-radius: 4px 8px 8px 4px;
  background:
    linear-gradient(90deg, rgba(229, 187, 104, 0.045), transparent 55%),
    rgba(7, 11, 16, 0.56);
  animation: fade-in 0.35s ease both;
}

.detail-top {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}
.detail-emblem {
  width: 30px;
  height: 30px;
  flex: 0 0 auto;
  color: var(--gold);
  opacity: 0.82;
}
.detail-copy { min-width: 0; flex: 1; }
.detail-tagline {
  font-family: var(--serif);
  font-size: 14px;
  letter-spacing: 0.08em;
  color: var(--gold-light);
}
.detail-lore {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.45;
}
.detail-bonuses {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 12px;
  margin-top: 8px;
  padding-top: 7px;
  border-top: 1px solid rgba(255, 255, 255, 0.055);
}
.detail-bonus {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--text-soft);
  font-size: 9.5px;
  letter-spacing: 0.02em;
}
.detail-bonus::before {
  content: "";
  width: 4px;
  height: 4px;
  transform: rotate(45deg);
  background: var(--gold);
  opacity: 0.75;
}

/* --- Difficulty + start --------------------------------------------------- */
.menu-controls {
  display: flex;
  align-items: flex-end;
  gap: clamp(16px, 2.4vw, 34px);
  animation: fade-up 0.65s 0.34s ease both;
}
.difficulty-block { min-width: 250px; }

.segmented {
  display: flex;
  gap: 3px;
  padding: 3px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 6px;
  background: rgba(6, 10, 14, 0.68);
}
.segmented button {
  position: relative;
  flex: 1;
  padding: 8px 9px 7px;
  border-radius: 4px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  transition: color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}
.segmented button:hover { color: var(--text); background: rgba(255, 255, 255, 0.045); }
.segmented button.active {
  color: #191307;
  background: linear-gradient(180deg, var(--gold-light), var(--gold));
  box-shadow: 0 3px 12px rgba(229, 187, 104, 0.24), inset 0 1px 0 #fff4cd;
}

.start-btn {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: clamp(196px, 19vw, 270px);
  min-height: 66px;
  padding: 10px 26px;
  border: 1px solid #f5dfa5;
  border-radius: 5px;
  background:
    linear-gradient(180deg, #f8e3a8 0%, #e6bd69 48%, #b98634 100%);
  color: #1b1408;
  box-shadow:
    0 14px 36px rgba(0, 0, 0, 0.4),
    0 0 38px -12px rgba(229, 187, 104, 0.68),
    inset 0 1px 0 #fff6d5,
    inset 0 -2px 0 rgba(97, 61, 12, 0.38);
  transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
}
.start-btn::before,
.start-btn::after {
  content: "";
  position: absolute;
  width: 9px;
  height: 9px;
  border-color: #fff0c3;
  opacity: 0.85;
  pointer-events: none;
}
.start-btn::before {
  top: 5px;
  left: 5px;
  border-top: 1px solid;
  border-left: 1px solid;
}
.start-btn::after {
  right: 5px;
  bottom: 5px;
  border-right: 1px solid;
  border-bottom: 1px solid;
}
.start-btn:hover {
  transform: translateY(-2px);
  filter: brightness(1.06);
  box-shadow:
    0 20px 46px rgba(0, 0, 0, 0.46),
    0 0 52px -10px rgba(229, 187, 104, 0.9),
    inset 0 1px 0 #fff6d5,
    inset 0 -2px 0 rgba(97, 61, 12, 0.38);
}
.start-btn:active { transform: translateY(0) scale(0.99); }
.start-btn:disabled { opacity: 0.5; cursor: wait; }

.start-label {
  position: relative;
  z-index: 2;
  font-family: var(--serif);
  font-size: 25px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.22em;
  padding-left: 0.22em;
}
.start-sub {
  position: relative;
  z-index: 2;
  margin-top: 5px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.19em;
  text-transform: uppercase;
  opacity: 0.68;
}
.start-glow {
  position: absolute;
  z-index: 1;
  inset: -20%;
  background: radial-gradient(circle at 50% 45%, rgba(255, 255, 255, 0.55), transparent 52%);
  opacity: 0;
  transition: opacity 0.18s ease;
  animation: soft-pulse 3.4s ease-in-out infinite;
}
.start-btn:hover .start-glow { opacity: 0.38; }

.menu-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px 18px;
  color: rgba(201, 194, 178, 0.58);
  font-size: 9.5px;
  letter-spacing: 0.04em;
  animation: fade-up 0.65s 0.42s ease both;
}
.menu-footer span { display: flex; align-items: center; gap: 5px; }
.menu-footer b {
  display: inline-grid;
  place-items: center;
  min-width: 21px;
  height: 18px;
  padding: 0 5px;
  border: 1px solid rgba(229, 187, 104, 0.28);
  border-radius: 3px;
  color: var(--gold-light);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.04em;
}

/* --- Right-hand live diorama --------------------------------------------- */
.menu-right {
  position: relative;
  flex: 1;
  min-width: 0;
  pointer-events: none;
}

.live-tag {
  position: absolute;
  top: 0;
  right: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 11px;
  border: 1px solid rgba(229, 187, 104, 0.23);
  border-radius: 3px;
  background: rgba(6, 10, 14, 0.38);
  color: rgba(233, 226, 210, 0.64);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.25em;
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
}
.live-tag span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #ff6b5e;
  box-shadow: 0 0 9px #ff6b5e;
  animation: soft-pulse 1.4s ease-in-out infinite;
}

.menu-right-copy {
  position: absolute;
  right: 0;
  bottom: 4.5vh;
  font-family: var(--serif);
  font-size: clamp(36px, 4.5vw, 74px);
  font-weight: 700;
  line-height: 0.93;
  letter-spacing: 0.035em;
  text-align: right;
  color: rgba(243, 234, 212, 0.14);
  text-shadow: 0 2px 30px rgba(0, 0, 0, 0.25);
  border-right: 1px solid rgba(229, 187, 104, 0.22);
  padding-right: 22px;
}
.menu-right-copy::after {
  content: "долина трёх ветров";
  display: block;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: rgba(229, 187, 104, 0.45);
}

/* --- Loading -------------------------------------------------------------- */
.loading {
  position: absolute;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 15px;
  background:
    radial-gradient(circle at 50% 44%, rgba(30, 46, 61, 0.45), transparent 50%),
    #060a0f;
  animation: fade-in 0.25s ease both;
}
.loading-crest {
  width: 68px;
  height: 68px;
  color: var(--gold);
  filter: drop-shadow(0 0 18px rgba(229, 187, 104, 0.35));
  animation: soft-pulse 2.2s ease-in-out infinite;
}
.loading-title {
  font-family: var(--serif);
  font-size: 16px;
  letter-spacing: 0.18em;
  color: var(--gold-light);
  text-transform: uppercase;
}
.loading-bar {
  position: relative;
  width: min(260px, 62vw);
  height: 2px;
  overflow: hidden;
  background: rgba(229, 187, 104, 0.14);
}
.loading-bar span {
  position: absolute;
  inset: 0;
  width: 42%;
  background: linear-gradient(90deg, transparent, var(--gold-light), transparent);
  animation: loading-sweep 1.1s ease-in-out infinite;
}
@keyframes loading-sweep {
  0% { transform: translateX(-120%); }
  100% { transform: translateX(340%); }
}

/* ==========================================================================
   In-game HUD: top bar, objective, portrait, commands and minimap
   ========================================================================== */

.hud {
  position: absolute;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  animation: fade-in 0.35s ease both;
}
.hud button,
.hud .bottom-hud,
.hud .topbar,
.hud .objective { pointer-events: auto; }

/* --- Top bar -------------------------------------------------------------- */
.topbar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 3;
  height: 62px;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 16px 0 13px;
  background:
    linear-gradient(180deg, rgba(5, 9, 14, 0.93), rgba(6, 11, 16, 0.66) 76%, rgba(6, 11, 16, 0));
  border-bottom: 1px solid rgba(229, 187, 104, 0.13);
}
.topbar::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(229, 187, 104, 0.45) 16%, rgba(229, 187, 104, 0.08) 60%, transparent);
  pointer-events: none;
}

.player-id {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.player-crest {
  position: relative;
  width: 41px;
  height: 41px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  padding: 6px;
  color: var(--blue-soft);
  border: 1px solid rgba(76, 141, 255, 0.42);
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 30%, rgba(76, 141, 255, 0.24), transparent 70%),
    rgba(7, 12, 18, 0.8);
  box-shadow: inset 0 0 12px rgba(76, 141, 255, 0.16), 0 0 18px -5px rgba(76, 141, 255, 0.4);
}
.player-crest .crest { width: 27px; height: 27px; }
.player-id-text { min-width: 0; }
.player-race {
  font-family: var(--serif);
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #f1ead9;
  line-height: 1.05;
  white-space: nowrap;
}
.player-side {
  margin-top: 2px;
  color: rgba(143, 194, 255, 0.66);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.23em;
}

.resource-bar {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 4px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 7px;
  background: rgba(5, 9, 14, 0.5);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.resource {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 82px;
  height: 30px;
  padding: 0 10px;
  border-radius: 5px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.008));
  color: #f2ebdb;
  font-size: 12.5px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.03em;
  white-space: nowrap;
}
.resource + .resource { border-left: 1px solid rgba(255, 255, 255, 0.055); border-radius: 0 5px 5px 0; }
.resource .res-icon { width: 18px; height: 18px; color: var(--gold); }
.resource .res-icon[data-icon="lumber"] { color: #a9d47e; }
.resource .res-icon[data-icon="supply"] { color: #c7d4e5; }
.resource.supply { min-width: 76px; color: #cfd9e4; }
.resource.time { min-width: 73px; color: rgba(233, 226, 210, 0.74); font-size: 11.5px; }
.resource.time .res-icon { display: none; }
.resource.supply.low { color: var(--red-soft); }
.resource.supply.low .res-icon { color: var(--red-soft); }
.clock-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 8px rgba(229, 187, 104, 0.7);
  animation: soft-pulse 2.4s ease-in-out infinite;
}

.top-actions {
  display: flex;
  gap: 5px;
  margin-left: auto;
}
.icon-btn {
  position: relative;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 5px;
  background: rgba(8, 13, 19, 0.55);
  color: rgba(233, 226, 210, 0.7);
  transition: color 0.16s ease, border-color 0.16s ease, background 0.16s ease;
}
.icon-btn .ico { width: 18px; height: 18px; }
.icon-btn:hover {
  color: var(--gold-light);
  border-color: rgba(229, 187, 104, 0.4);
  background: rgba(229, 187, 104, 0.08);
}
.icon-btn:active { transform: translateY(1px); }

/* --- Objective ------------------------------------------------------------ */
.objective {
  position: absolute;
  top: 77px;
  left: 15px;
  z-index: 2;
  width: 254px;
  padding: 9px 11px 10px;
  border: 1px solid rgba(229, 187, 104, 0.17);
  border-left: 2px solid rgba(239, 83, 80, 0.7);
  border-radius: 3px 7px 7px 3px;
  background:
    linear-gradient(90deg, rgba(239, 83, 80, 0.06), transparent 60%),
    rgba(5, 9, 14, 0.56);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: none;
}
.objective-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
  color: rgba(255, 139, 128, 0.72);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.24em;
}
.objective-pulse {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--red);
  box-shadow: 0 0 8px var(--red);
  animation: soft-pulse 1.7s ease-in-out infinite;
}
.objective-body {
  display: flex;
  align-items: center;
  gap: 9px;
}
.objective-crest {
  width: 27px;
  height: 27px;
  flex: 0 0 auto;
  padding: 4px;
  color: var(--red-soft);
  border: 1px solid rgba(239, 83, 80, 0.34);
  border-radius: 50%;
  background: rgba(239, 83, 80, 0.08);
}
.objective-title {
  color: #eee7d7;
  font-family: var(--serif);
  font-size: 12px;
  letter-spacing: 0.02em;
  line-height: 1.15;
}
.objective-name {
  margin-top: 2px;
  color: rgba(255, 139, 128, 0.78);
  font-size: 9px;
  letter-spacing: 0.05em;
}

/* --- Toasts and floating combat text ------------------------------------- */
.toasts {
  position: absolute;
  top: 72px;
  left: 50%;
  z-index: 8;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  width: min(460px, 70vw);
  transform: translateX(-50%);
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 100%;
  padding: 7px 13px 7px 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-left: 2px solid var(--gold);
  border-radius: 3px;
  background: rgba(6, 10, 15, 0.9);
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.32);
  color: var(--text-soft);
  font-size: 11px;
  line-height: 1.25;
  letter-spacing: 0.015em;
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  animation: toast-in 0.24s ease both;
}
.toast .ico { width: 14px; height: 14px; color: var(--gold); }
.toast.leaving { animation: toast-out 0.28s ease both; }
.toast.success { border-left-color: #72c985; }
.toast.success .ico { color: #86d697; }
.toast.warn { border-left-color: #e6a64a; }
.toast.warn .ico { color: #efb45c; }
.toast.danger { border-left-color: #e35d52; background: rgba(28, 9, 9, 0.88); }
.toast.danger .ico { color: #ff8a7f; }
@keyframes toast-in {
  from { opacity: 0; transform: translateY(-8px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes toast-out {
  to { opacity: 0; transform: translateY(-7px) scale(0.98); }
}

.float-layer {
  position: fixed;
  inset: 0;
  z-index: 30;
  overflow: hidden;
  pointer-events: none;
}
.float-text {
  position: absolute;
  left: 0;
  top: 0;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.02em;
  text-shadow: 0 2px 5px rgba(0, 0, 0, 0.9), 0 0 12px rgba(0, 0, 0, 0.5);
  will-change: transform, opacity;
  white-space: nowrap;
}
.float-text.plus { color: #9de08d; }
.float-text.minus { color: #ff8d7f; }

/* --- Bottom HUD ----------------------------------------------------------- */
.bottom-hud {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 4;
  display: grid;
  grid-template-columns: 304px minmax(220px, 1fr) 348px 234px;
  gap: 8px;
  padding: 9px 11px calc(9px + var(--safe-b));
  background:
    linear-gradient(180deg, rgba(6, 10, 15, 0.34), rgba(6, 10, 15, 0.9) 18%, rgba(5, 8, 13, 0.97)),
    radial-gradient(ellipse at 50% 120%, rgba(63, 92, 119, 0.22), transparent 64%);
  border-top: 1px solid rgba(229, 187, 104, 0.14);
  box-shadow: 0 -18px 50px rgba(0, 0, 0, 0.26);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.bottom-hud::before {
  content: "";
  position: absolute;
  top: -1px;
  left: 8%;
  right: 8%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(229, 187, 104, 0.46), transparent);
  pointer-events: none;
}

.portrait-block,
.info-block,
.command-block,
.minimap-block {
  position: relative;
  min-width: 0;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 6px;
  background:
    linear-gradient(150deg, rgba(255, 255, 255, 0.025), transparent 40%),
    rgba(9, 14, 20, 0.7);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.035);
}

/* Portrait + details ------------------------------------------------------ */
.portrait-block {
  display: flex;
  gap: 10px;
  padding: 9px;
  min-height: 116px;
}
.portrait-holder {
  position: relative;
  width: 106px;
  height: 106px;
  flex: 0 0 auto;
  overflow: hidden;
  border: 1px solid rgba(229, 187, 104, 0.32);
  border-radius: 4px;
  background:
    radial-gradient(circle at 50% 34%, rgba(69, 105, 138, 0.32), transparent 70%),
    linear-gradient(180deg, #121c25, #080c11);
  box-shadow: inset 0 0 26px rgba(0, 0, 0, 0.7);
}
.portrait-holder::before {
  content: "";
  position: absolute;
  inset: 4px;
  z-index: 2;
  border: 1px solid rgba(229, 187, 104, 0.13);
  pointer-events: none;
}
.portrait-frame-glow {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background: radial-gradient(circle at 50% 20%, transparent 42%, rgba(0, 0, 0, 0.34) 100%);
  box-shadow: inset 0 -24px 25px -20px rgba(229, 187, 104, 0.5);
}
.portrait-canvas {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100% !important;
  height: 100% !important;
}
.portrait-fallback {
  position: absolute;
  inset: 16px;
  z-index: 0;
  display: grid;
  place-items: center;
  color: rgba(229, 187, 104, 0.6);
  filter: drop-shadow(0 0 14px rgba(229, 187, 104, 0.2));
}
.portrait-fallback svg { width: 100%; height: 100%; }
.portrait-count {
  position: absolute;
  top: 13px;
  left: 13px;
  z-index: 4;
  min-width: 21px;
  height: 21px;
  padding: 0 5px;
  display: none;
  place-items: center;
  border: 1px solid rgba(229, 187, 104, 0.44);
  border-radius: 3px;
  background: rgba(4, 7, 10, 0.78);
  color: var(--gold-light);
  font-size: 10px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.portrait-count.show { display: grid; }
.portrait-meta {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 4px 2px 3px 0;
}
.portrait-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #f3ecdb;
  font-family: var(--serif);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.1;
}
.portrait-sub {
  margin-top: 3px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}
.hp-track {
  position: relative;
  height: 8px;
  margin-top: 11px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 2px;
  background: rgba(0, 0, 0, 0.5);
}
.hp-track span {
  display: block;
  width: 0%;
  height: 100%;
  background: linear-gradient(180deg, #8cf09a, #4dbb63);
  box-shadow: 0 0 10px rgba(95, 215, 115, 0.32);
  transition: width 0.18s linear, background 0.2s linear;
}
.hp-track span.enemy { background: linear-gradient(180deg, #ff8b80, #d24f46); box-shadow: 0 0 10px rgba(239, 83, 80, 0.32); }
.hp-track span.building { background: linear-gradient(180deg, #9fcfff, #4c8dff); box-shadow: 0 0 10px rgba(76, 141, 255, 0.32); }
.portrait-hp-text {
  margin-top: 5px;
  color: rgba(233, 226, 210, 0.56);
  font-size: 9px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
}

/* Info panel -------------------------------------------------------------- */
.info-block {
  padding: 11px 14px 10px;
  overflow: hidden;
}
.info-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #f2ebdb;
  font-family: var(--serif);
  font-size: 18px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: 0.02em;
}
.info-sub {
  margin-top: 3px;
  color: var(--gold);
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}
.info-desc {
  margin-top: 8px;
  max-height: 46px;
  overflow: hidden;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.45;
}
.stat-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 4px;
  margin-top: auto;
  padding-top: 8px;
}
.stat {
  min-width: 0;
  padding: 5px 6px 4px;
  border: 1px solid rgba(255, 255, 255, 0.055);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.022);
}
.stat-label {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: rgba(142, 154, 166, 0.72);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}
.stat-value {
  display: block;
  margin-top: 1px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #ddd6c6;
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.stat.gold .stat-value { color: var(--gold-light); }
.stat.blue .stat-value { color: var(--blue-soft); }
.stat.red .stat-value { color: var(--red-soft); }
.stat.green .stat-value { color: #9de08d; }

/* Command card ------------------------------------------------------------ */
.command-block {
  display: flex;
  flex-direction: column;
  padding: 8px;
  min-height: 116px;
}
.command-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 0 2px 6px;
}
#command-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--gold-light);
  font-family: var(--serif);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
}
#command-hint {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: rgba(142, 154, 166, 0.7);
  font-size: 8px;
  letter-spacing: 0.04em;
}
.command-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 4px;
  align-content: start;
}
.cmd-btn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-width: 0;
  min-height: 53px;
  padding: 4px 3px 3px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 4px;
  background:
    radial-gradient(circle at 50% 20%, rgba(255, 255, 255, 0.055), transparent 68%),
    linear-gradient(180deg, rgba(29, 40, 52, 0.7), rgba(8, 13, 19, 0.84));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
  color: var(--text-soft);
  transition: border-color 0.14s ease, background 0.14s ease, transform 0.1s ease, color 0.14s ease;
}
.cmd-btn:hover {
  border-color: rgba(229, 187, 104, 0.46);
  background:
    radial-gradient(circle at 50% 20%, rgba(229, 187, 104, 0.12), transparent 68%),
    linear-gradient(180deg, rgba(41, 51, 61, 0.86), rgba(11, 17, 24, 0.92));
  color: #f7efdd;
}
.cmd-btn:active { transform: scale(0.97); }
.cmd-btn.disabled {
  opacity: 0.38;
  filter: saturate(0.35);
  cursor: not-allowed;
}
.cmd-btn.disabled:hover { border-color: rgba(255, 255, 255, 0.1); transform: none; }
.cmd-icon {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  color: var(--gold);
}
.cmd-icon .ico { width: 23px; height: 23px; }
.cmd-icon img {
  width: 30px;
  height: 30px;
  object-fit: contain;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.55));
}
.cmd-name {
  width: 100%;
  padding: 0 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: center;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.015em;
  line-height: 1.1;
}
.cmd-cost {
  position: absolute;
  left: 3px;
  bottom: 2px;
  display: flex;
  gap: 3px;
  color: rgba(229, 187, 104, 0.82);
  font-size: 7px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 1px 3px #000;
}
.cmd-cost .lumber { color: #a9d47e; }
.cmd-key {
  position: absolute;
  top: 2px;
  right: 3px;
  color: rgba(255, 255, 255, 0.3);
  font-size: 7px;
  font-weight: 700;
}
.cmd-empty {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 56px;
  padding: 8px;
  border: 1px dashed rgba(255, 255, 255, 0.09);
  border-radius: 4px;
  color: rgba(142, 154, 166, 0.55);
  font-size: 9px;
  letter-spacing: 0.05em;
  text-align: center;
}

.queue-row {
  display: flex;
  gap: 3px;
  min-height: 20px;
  margin-top: 6px;
  overflow: hidden;
}
.queue-row:empty { min-height: 0; margin-top: 0; }
.queue-item {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  height: 20px;
  padding: 3px 4px 3px 5px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.035);
  color: rgba(233, 226, 210, 0.72);
  font-size: 7.5px;
  line-height: 1.15;
  white-space: nowrap;
  text-overflow: ellipsis;
  text-align: left;
  transition: border-color 0.15s ease, background 0.15s ease;
}
.queue-item:hover { border-color: rgba(239, 83, 80, 0.5); background: rgba(239, 83, 80, 0.08); }
.queue-fill {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  background: var(--gold);
  box-shadow: 0 0 6px rgba(229, 187, 104, 0.5);
}
.queue-label {
  position: relative;
  z-index: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  display: block;
}

/* Minimap ----------------------------------------------------------------- */
.minimap-block {
  display: flex;
  flex-direction: column;
  padding: 7px;
  overflow: hidden;
}
.minimap-head {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  padding: 0 2px 5px;
  color: rgba(229, 187, 104, 0.64);
  font-size: 6.8px;
  font-weight: 700;
  letter-spacing: 0.14em;
  white-space: nowrap;
}
.minimap-head span:last-child {
  color: rgba(233, 226, 210, 0.4);
  font-variant-numeric: tabular-nums;
}
#minimap {
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1;
  height: auto;
  flex: 1 1 auto;
  min-height: 0;
  border: 1px solid rgba(229, 187, 104, 0.22);
  border-radius: 3px;
  background: #35452e;
  cursor: crosshair;
  image-rendering: auto;
}
.minimap-hint {
  margin-top: 4px;
  text-align: center;
  color: rgba(142, 154, 166, 0.45);
  font-size: 6.5px;
  letter-spacing: 0.06em;
  white-space: nowrap;
}

/* Selection marquee ------------------------------------------------------- */
.marquee {
  position: fixed !important;
  z-index: 60;
  display: none;
  border: 1px solid rgba(143, 194, 255, 0.85);
  background:
    linear-gradient(135deg, rgba(76, 141, 255, 0.16), rgba(76, 141, 255, 0.04));
  box-shadow: inset 0 0 18px rgba(76, 141, 255, 0.1), 0 0 1px rgba(143, 194, 255, 0.6);
  pointer-events: none;
}

#stage canvas.build-cursor { cursor: crosshair; }
#stage canvas.attack-cursor { cursor: crosshair; }

/* Small screens that still keep the desktop information panel. */
@media (max-width: 1240px) {
  .bottom-hud { grid-template-columns: 278px minmax(150px, 1fr) 326px 205px; }
  .stat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .info-desc { max-height: 32px; }
  .minimap-hint { display: none; }
}

/* ==========================================================================
   Overlays: pause, help, victory / defeat, plus responsive layout
   ========================================================================== */

.modal {
  position: absolute;
  inset: 0;
  z-index: 70;
  display: grid;
  place-items: center;
  padding: 18px;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(18, 27, 37, 0.35), transparent 55%),
    rgba(3, 6, 10, 0.74);
  backdrop-filter: blur(9px);
  -webkit-backdrop-filter: blur(9px);
  animation: fade-in 0.22s ease both;
}
.modal.hidden { display: none !important; }

.modal-panel {
  position: relative;
  width: min(560px, 100%);
  padding: 30px 32px 28px;
  border: 1px solid rgba(229, 187, 104, 0.28);
  border-radius: 8px;
  background:
    radial-gradient(circle at 50% 0%, rgba(229, 187, 104, 0.08), transparent 38%),
    linear-gradient(155deg, rgba(19, 28, 38, 0.98), rgba(7, 11, 16, 0.99));
  box-shadow: 0 34px 100px rgba(0, 0, 0, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  text-align: center;
  animation: modal-in 0.28s cubic-bezier(0.2, 0.8, 0.25, 1) both;
}
.modal-panel::before,
.modal-panel::after {
  content: "";
  position: absolute;
  width: 22px;
  height: 22px;
  pointer-events: none;
  border-color: rgba(229, 187, 104, 0.62);
}
.modal-panel::before {
  top: 7px;
  left: 7px;
  border-top: 1px solid;
  border-left: 1px solid;
}
.modal-panel::after {
  right: 7px;
  bottom: 7px;
  border-right: 1px solid;
  border-bottom: 1px solid;
}
@keyframes modal-in {
  from { opacity: 0; transform: translateY(15px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.modal-kicker {
  color: var(--gold);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.31em;
  text-transform: uppercase;
}
.modal-panel h2 {
  margin: 6px 0 5px;
  font-family: var(--serif);
  font-size: 42px;
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.1em;
  color: #f2ead7;
  text-shadow: 0 12px 34px rgba(0, 0, 0, 0.4);
}
.modal-panel p {
  margin: 0 auto;
  max-width: 390px;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.55;
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 7px;
  margin-top: 23px;
}
.modal-actions button {
  min-width: 126px;
  padding: 11px 18px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.035);
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  transition: background 0.16s ease, border-color 0.16s ease, color 0.16s ease, transform 0.16s ease;
}
.modal-actions button:hover {
  border-color: rgba(229, 187, 104, 0.44);
  background: rgba(229, 187, 104, 0.08);
  color: var(--gold-light);
}
.modal-actions button:active { transform: translateY(1px); }
.modal-actions button.primary {
  border-color: #efd697;
  background: linear-gradient(180deg, #f6dda0, #d5a94f);
  color: #191206;
  box-shadow: inset 0 1px 0 #fff2c8, 0 6px 18px rgba(229, 187, 104, 0.2);
}
.modal-actions button.primary:hover {
  filter: brightness(1.06);
  color: #151005;
}

.modal-close {
  position: absolute;
  top: 11px;
  right: 13px;
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 50%;
  color: var(--muted);
  font-size: 20px;
  line-height: 1;
  transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease;
}
.modal-close:hover {
  color: var(--gold-light);
  border-color: rgba(229, 187, 104, 0.44);
  background: rgba(229, 187, 104, 0.07);
}

/* Help -------------------------------------------------------------------- */
.help-panel {
  width: min(780px, 100%);
  padding: 28px 32px 25px;
  text-align: left;
}
.help-panel .modal-kicker,
.help-panel h2 { text-align: center; }
.help-panel h2 { margin-bottom: 19px; }

.help-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.08);
}
.help-grid > div {
  display: flex;
  gap: 11px;
  align-items: flex-start;
  padding: 10px 12px;
  background: rgba(8, 13, 19, 0.93);
}
.help-grid b {
  flex: 0 0 88px;
  padding-top: 1px;
  color: var(--gold-light);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  line-height: 1.4;
}
.help-grid span {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.4;
}
.help-tip,
.help-touch {
  margin-top: 13px;
  padding: 10px 13px;
  border-left: 2px solid rgba(229, 187, 104, 0.5);
  background: rgba(229, 187, 104, 0.045);
  color: var(--text-soft);
  font-size: 10px;
  line-height: 1.45;
}
.help-touch {
  border-left-color: rgba(76, 141, 255, 0.55);
  background: rgba(76, 141, 255, 0.045);
}
.help-touch b { color: var(--blue-soft); }

/* Victory / defeat -------------------------------------------------------- */
.end-screen {
  background:
    radial-gradient(ellipse at 50% 38%, rgba(229, 187, 104, 0.13), transparent 48%),
    radial-gradient(ellipse at 50% 110%, rgba(239, 83, 80, 0.1), transparent 56%),
    rgba(2, 5, 8, 0.86);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.end-screen.defeat {
  background:
    radial-gradient(ellipse at 50% 38%, rgba(239, 83, 80, 0.12), transparent 48%),
    rgba(2, 5, 8, 0.88);
}

.end-panel {
  position: relative;
  width: min(640px, 100%);
  padding: 30px 34px 28px;
  border: 1px solid rgba(229, 187, 104, 0.3);
  border-radius: 8px;
  background:
    radial-gradient(circle at 50% -10%, rgba(229, 187, 104, 0.12), transparent 44%),
    linear-gradient(155deg, rgba(20, 29, 39, 0.98), rgba(6, 10, 14, 0.99));
  box-shadow: 0 34px 110px rgba(0, 0, 0, 0.72), inset 0 1px 0 rgba(255, 255, 255, 0.055);
  text-align: center;
  animation: modal-in 0.36s cubic-bezier(0.2, 0.8, 0.25, 1) both;
}
.end-panel::before,
.end-panel::after {
  content: "";
  position: absolute;
  width: 29px;
  height: 29px;
  border-color: rgba(229, 187, 104, 0.7);
}
.end-panel::before {
  top: 8px;
  left: 8px;
  border-top: 1px solid;
  border-left: 1px solid;
}
.end-panel::after {
  right: 8px;
  bottom: 8px;
  border-right: 1px solid;
  border-bottom: 1px solid;
}

.end-crest {
  width: 72px;
  height: 72px;
  margin: 0 auto 8px;
  padding: 10px;
  color: var(--gold-light);
  border: 1px solid rgba(229, 187, 104, 0.34);
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 35%, rgba(229, 187, 104, 0.22), transparent 70%),
    rgba(5, 9, 14, 0.8);
  box-shadow: 0 0 40px -8px rgba(229, 187, 104, 0.65), inset 0 0 18px rgba(229, 187, 104, 0.11);
}
.end-screen.defeat .end-crest {
  color: var(--red-soft);
  border-color: rgba(239, 83, 80, 0.38);
  background:
    radial-gradient(circle at 50% 35%, rgba(239, 83, 80, 0.19), transparent 70%),
    rgba(5, 9, 14, 0.82);
  box-shadow: 0 0 40px -8px rgba(239, 83, 80, 0.58), inset 0 0 18px rgba(239, 83, 80, 0.1);
}

.end-kicker {
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.42em;
  text-transform: uppercase;
}
.end-screen.defeat .end-kicker { color: var(--red-soft); }
.end-panel h2 {
  margin: 7px 0 6px;
  font-family: var(--serif);
  font-size: 45px;
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.08em;
  color: #f4ecda;
}
.end-sub {
  margin: 0 auto;
  max-width: 430px;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.5;
}

.end-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  margin-top: 20px;
  text-align: left;
}
.end-stat {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.026);
}
.end-stat .ico {
  width: 16px;
  height: 16px;
  flex: 0 0 auto;
  color: var(--gold);
  opacity: 0.8;
}
.end-stat-copy { min-width: 0; }
.end-stat-label {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: rgba(142, 154, 166, 0.76);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.end-stat-value {
  display: block;
  margin-top: 1px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #e9e2d2;
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

/* ==========================================================================
   Responsive
   ========================================================================== */

@media (max-width: 1120px) {
  .menu-left { width: min(700px, 64vw); }
  .menu-right-copy { font-size: clamp(30px, 4vw, 56px); }
  .bottom-hud { grid-template-columns: 266px minmax(130px, 1fr) 312px 192px; }
  .portrait-holder { width: 94px; height: 94px; }
  .stat-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}

@media (max-width: 900px) {
  .menu-content { padding: 20px 18px 16px; }
  .menu-left {
    width: 100%;
    justify-content: flex-start;
    padding-top: 20px;
    gap: 14px;
  }
  .menu-shade {
    background:
      linear-gradient(180deg, rgba(3, 6, 10, 0.8) 0%, rgba(3, 6, 10, 0.72) 24%, rgba(3, 6, 10, 0.86) 66%, rgba(3, 6, 10, 0.97) 100%),
      linear-gradient(90deg, rgba(3, 6, 10, 0.55), transparent);
  }
  .menu-shade::after { opacity: 0.18; mask-image: radial-gradient(ellipse at 50% 30%, #000, transparent 75%); -webkit-mask-image: radial-gradient(ellipse at 50% 30%, #000, transparent 75%); }
  .menu-right { position: absolute; inset: 0; z-index: -1; }
  .menu-right-copy { display: none; }
  .live-tag { top: 18px; right: 18px; }
  .brand { padding-top: 26px; }
  .brand h1 { font-size: clamp(50px, 13vw, 84px); }
  .brand-lore { display: none; }
  .race-card { min-height: 132px; padding: 12px 11px 10px; }
  .race-emblem { width: 32px; height: 32px; margin-bottom: 6px; }
  .race-name { font-size: 18px; }
  .race-tag { top: 11px; right: 9px; }
  .race-desc { font-size: 9.5px; }
  .race-bonus { font-size: 8.5px; }
  .race-detail { min-height: 0; }
  .detail-lore { font-size: 9.5px; }
  .detail-bonuses { gap: 4px 9px; }
  .detail-bonus { font-size: 8.5px; }
  .menu-controls { align-items: stretch; gap: 12px; }
  .difficulty-block { flex: 1; min-width: 0; }
  .start-btn { width: 190px; min-height: 62px; padding: 9px 16px; }
  .start-label { font-size: 21px; }

  .topbar {
    height: auto;
    min-height: 50px;
    flex-wrap: wrap;
    gap: 5px 9px;
    padding: 6px 8px;
    background: linear-gradient(180deg, rgba(5, 9, 14, 0.95), rgba(5, 9, 14, 0.75));
  }
  .player-crest { width: 34px; height: 34px; padding: 5px; }
  .player-crest .crest { width: 22px; height: 22px; }
  .player-race { font-size: 13px; }
  .player-side { font-size: 6.5px; }
  .icon-btn { width: 33px; height: 33px; }
  .resource-bar {
    order: 3;
    width: 100%;
    justify-content: center;
    padding: 3px;
    gap: 1px;
  }
  .resource {
    flex: 1;
    justify-content: center;
    min-width: 0;
    height: 27px;
    padding: 0 5px;
    font-size: 11px;
  }
  .resource .res-icon { width: 15px; height: 15px; }
  .resource.time { min-width: 0; font-size: 10px; }

  .objective { display: none; }
  .toasts { top: 92px; width: min(420px, 92vw); }
  .toast { font-size: 10px; padding: 6px 10px 6px 8px; }

  .bottom-hud {
    grid-template-columns: 1fr 1fr;
    grid-template-areas:
      "command command"
      "portrait minimap";
    grid-template-rows: auto 98px;
    gap: 5px;
    padding: 5px 6px calc(5px + var(--safe-b));
  }
  .command-block { grid-area: command; padding: 6px; min-height: 0; }
  .portrait-block { grid-area: portrait; min-height: 0; padding: 6px; gap: 7px; }
  .minimap-block { grid-area: minimap; padding: 5px; }
  .info-block { display: none; }
  .portrait-holder { width: 80px; height: 80px; }
  .portrait-meta { padding: 0; }
  .portrait-name { font-size: 14px; }
  .portrait-sub { font-size: 7px; }
  .portrait-hp-text { font-size: 8px; }
  .hp-track { margin-top: 8px; height: 7px; }
  .command-grid { gap: 3px; }
  .cmd-btn { min-height: 45px; }
  .cmd-icon { width: 23px; height: 23px; }
  .cmd-icon img { width: 24px; height: 24px; }
  .cmd-icon .ico { width: 19px; height: 19px; }
  .cmd-name { font-size: 7.4px; }
  .cmd-cost { font-size: 6.4px; }
  .queue-row { min-height: 17px; margin-top: 4px; }
  .queue-item { height: 17px; font-size: 6.8px; }
  .minimap-head { display: none; }
  #minimap { width: auto; height: 100%; margin: 0 auto; }
  .minimap-hint { display: none; }

  .help-grid { grid-template-columns: 1fr; }
  .help-grid > div { padding: 8px 10px; }
  .help-grid b { flex-basis: 76px; }
  .help-panel { padding: 25px 20px 20px; max-height: calc(100dvh - 28px); overflow-y: auto; }
  .end-panel { padding: 25px 20px 20px; max-height: calc(100dvh - 28px); overflow-y: auto; }
  .end-panel h2 { font-size: 37px; }
  .modal-panel { padding: 26px 20px 23px; max-height: calc(100dvh - 28px); overflow-y: auto; }
}

@media (max-width: 560px) {
  .menu-content { padding: 14px 12px 10px; }
  .menu-left { gap: 11px; padding-top: 16px; }
  .brand-kicker { font-size: 8px; letter-spacing: 0.22em; }
  .brand h1 { font-size: clamp(44px, 15vw, 66px); }
  .brand-sub { font-size: 13px; margin-top: 9px; }
  .race-cards { gap: 5px; }
  .race-card { min-height: 117px; padding: 10px 8px 8px; border-radius: 6px; }
  .race-emblem { width: 28px; height: 28px; margin-bottom: 5px; }
  .race-name { font-size: 15px; }
  .race-tag { display: none; }
  .race-desc { font-size: 8.5px; }
  .race-bonus { font-size: 7.6px; line-height: 1.2; }
  .race-detail { padding: 9px 10px 9px 11px; }
  .detail-emblem { display: none; }
  .detail-tagline { font-size: 12px; }
  .detail-lore { font-size: 8.8px; }
  .detail-bonus { font-size: 7.8px; }
  .menu-controls { flex-direction: column; align-items: stretch; gap: 8px; }
  .start-btn { width: 100%; min-height: 55px; }
  .start-label { font-size: 20px; }
  .menu-footer { font-size: 8px; gap: 5px 9px; }
  .menu-footer span:nth-child(n+4) { display: none; }
  .live-tag { top: 12px; right: 12px; font-size: 6.5px; padding: 5px 8px; }
  .section-label { font-size: 8.5px; margin-bottom: 8px; }

  .resource { font-size: 10px; }
  .top-actions { gap: 3px; }
  .icon-btn { width: 31px; height: 31px; }
  .btn-help { display: none; }
  .portrait-holder { width: 68px; height: 68px; }
  .portrait-name { font-size: 12px; }
  .portrait-sub { display: none; }
  .portrait-hp-text { display: none; }
  .portrait-count { top: 8px; left: 8px; min-width: 18px; height: 18px; font-size: 9px; }
  .bottom-hud { grid-template-rows: auto 84px; }
  .cmd-btn { min-height: 42px; }
  .cmd-icon { width: 20px; height: 20px; }
  .cmd-icon img { width: 22px; height: 22px; }
  .cmd-name { font-size: 6.8px; }
  .cmd-cost { display: none; }
  .queue-row { display: none; }
  .end-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .modal-actions button { min-width: 0; flex: 1; }
  .end-panel h2 { font-size: 32px; }
  .modal-panel h2 { font-size: 34px; }
}

@media (max-height: 760px) and (min-width: 901px) {
  .menu-content { padding-top: 18px; padding-bottom: 14px; }
  .menu-left { gap: 9px; }
  .brand-lore { display: none; }
  .brand h1 { font-size: clamp(48px, 6.4vw, 84px); }
  .brand-sub { margin-top: 7px; }
  .race-card { min-height: 126px; padding: 11px 12px 10px; }
  .race-emblem { width: 32px; height: 32px; margin-bottom: 6px; }
  .race-detail { min-height: 0; }
  .detail-bonuses { margin-top: 6px; padding-top: 5px; }
  .start-btn { min-height: 58px; }
}

@media (max-height: 520px) and (orientation: landscape) {
  .brand-kicker,
  .brand-lore,
  .race-detail,
  .menu-footer { display: none; }
  .brand h1 { font-size: 54px; }
  .brand-sub { display: none; }
  .menu-left { gap: 8px; }
  .race-card { min-height: 92px; }
  .race-bonus { display: none; }
  .menu-content { padding: 10px 14px; }
  .bottom-hud { grid-template-rows: auto 82px; }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

