  .detail-lore { font-size: 9.5px; line-height: 1.4; }
  .detail-bonuses { gap: 4px 8px; padding-top: 6px; margin-top: 6px; }
  .detail-bonus { font-size: 8px; }
  .menu-controls { display: block; }
